/* Evolvlings: path conversations of era 4, Las Forjas Hondas (the ten eras plan, https://claude.ai/artifact/RFy6uGdhz9DJeW7e9ZfdkE).
   Same format as the zone files (see rpg/events-aurora.js). These events only come up while the Glade lives in era 4:
   need.era says so (lore.js needOk), and need.layer counts the guardians beaten since the era began.
   Another generation has passed since El Lago que Recuerda. How era 3 ended (m3_farol / m3_mareas / m3_espejo) is
   still in the flags and changes a few lines and options.
   The Ember Guild found root metal under the Crater and is casting a Bell that puts the Root to sleep with no singer;
   the workers of the deep furnaces harden, hands first, like the third statue of the Heart (the smith).
   The nine peoples you bring together set the u4_* flags; with all nine, the final dilemma offers Everyone's Forge
   (rpg/data-eras.js derives e4_nueve). The m4_* flags are the marks this era leaves on the next.
   Loaded after the zone files (it adds to them). English text: rpg/events-era4.en.js. */
window.EVEVENTS = window.EVEVENTS || {};
(function (E) {
  const add = (zone, evs) => { E[zone] = Object.assign(E[zone] || {}, evs); };

  /* ==================== Entrega 1: el metal de raíz, la huelga, las manos de piedra y la Campana ==================== */

  /* ---------- Cráter Tibio: el molde de la Campana, la huelga, las manos y la Noche de Ascuas ---------- */
  add("crater", {
    "e4-fogarin": { kind: "dialogo", need: { era: 4, layer: 1 }, first: true, who: { fogarin: "Fogarín, Maestro del Gremio" }, start: "a", nodes: {
      a: { say: [[null, "En el fondo del Cráter, donde antes había una ladera de piedra, ahora hay un pozo ancho con escaleras de hierro. Abajo brilla algo rojo que no se apaga. Arriba, un hombre muy viejo con el delantal del Maestro te espera junto a un molde enorme."],
                 ["fogarin", "Cuidador. Ven, ven. Mira esto. Es el molde de la Campana. Cuando la fundamos, la Raíz va a dormir sin que nadie le cante. Ni tú, ni las Casas, ni nadie que cobre por la nana."],
                 ["fogarin", "Toda mi vida vi al Fuego comprado. Por las Casas, por el agua, por quien tuviera más. Con esto, el Fuego le da al Claro algo que nadie puede comprar. Un sueño de bronce para la Raíz."]],
           opts: [{ t: "«¿De dónde sale el metal?»", go: "metal", once: true },
                  { t: "«¿Quién va a tocar la Campana?»", go: "quien", once: true },
                  { t: "«He visto las manos de tus obreros.»", go: "manos" },
                  { t: "«Las Casas vendieron sus forjas por la versión de las Mareas.»", go: "mareas", cNeed: "m3_mareas" },
                  { t: "«Ayúdame a entender cómo funciona.»", go: "ayudar" }] },
      metal: { say: [["fogarin", "De abajo. De muy abajo. Es caliente y no se enfría nunca, aunque lo metas en nieve. Los viejos decían que era sangre de la Raíz. Los viejos decían muchas cosas."],
                     ["fogarin", "Yo digo que es metal. Y que con él se hacen cosas que antes no se podían hacer."]], back: "a" },
      quien: { say: [["fogarin", "Esa es la pregunta. Las Casas ya están comprando turnos. Como si la Campana fuera un horno que se alquila."],
                     ["fogarin", "Yo quiero que no la toque nadie que pague. Pero no sé quién, entonces. Por eso te lo pregunto a ti también."]], back: "a" },
      manos: { say: [["fogarin", "Sí. Las vi."],
                     [null, "Se mira sus propias manos. Las uñas tienen una raya gris en el borde, fina, como si se las hubiera pintado con ceniza."],
                     ["fogarin", "Los hornos hondos cansan. Las manos se ponen duras con el trabajo. Siempre fue así en el Gremio."],
                     [null, "No te mira cuando lo dice."]], back: "a" },
      mareas: { say: [["fogarin", "Las compré yo. Baratas. Ola me dijo que no lo hiciera. Lo hice igual: si no las compraba el Gremio, las compraba otro."],
                      ["fogarin", "Ahora tengo más hornos que nadie en la historia del Claro. Y todos los días alguien me recuerda que eran de otro."]], back: "a" },
      ayudar: { say: [[null, "Fogarín te muestra los planos, los hornos, el canal por donde va a correr el metal. Habla rápido, con las manos, como el aprendiz que fue hace sesenta años."],
                      ["fogarin", "La campana suena una vez, y la nota baja hasta el fondo, hasta la Raíz. No hay que cantar ocho versos. No hay que juntar a nueve pueblos. Una nota y listo."],
                      [null, "Lo dice como si eso fuera lo bueno. Te das cuenta de que, para él, lo es."]], end: { xp: 14, flag: "e4_campanaVista" } },
    } },

    "e4-huelga": { kind: "dialogo", need: { era: 4, layer: 2 }, who: { escoria: "Escoria, obrera", cobre: "Cobre, de las Casas" }, start: "a", nodes: {
      a: { say: [[null, "A la entrada de los hornos hondos hay cien obreros sentados en el suelo, con los brazos cruzados. Delante, una mujer con la cara llena de hollín grita más fuerte que todos."],
                 ["escoria", "¡Ni una pala más! ¡Ni un lingote más! Que bajen ellos a los hornos hondos, a ver cuánto tardan en no poder cerrar el puño."],
                 [null, "Detrás de ti, un hombre joven bien vestido te toma del codo. Tiene el escudo de una Casa en el pecho, gastado."],
                 ["cobre", "Cuidador. Me llamo Cobre. Mi Casa le pagó al Gremio por la Campana, por adelantado. Si la huelga sigue, no hay Campana, y mi Casa se hunde. Llévele esto a la obrera: una bolsa para cada uno que vuelva a trabajar."]],
           opts: [{ t: "«Escoria, ¿qué piden exactamente?»", go: "piden", once: true },
                  { t: "Apoyar la huelga y sentarte con los obreros", go: "apoyar" },
                  { t: "Llevar el recado de Cobre", go: "recado" },
                  { t: "Mediar entre los obreros y el Gremio", go: "mediar" }] },
      piden: { say: [["escoria", "Que se cierren los hornos hondos. Que se cave el metal de raíz solo con turnos cortos. Y que el Gremio diga en voz alta lo que les pasa a las manos."],
                     ["escoria", "No pedimos plata. Ya nos dieron plata. La plata no abre los dedos."]], back: "a" },
      apoyar: { say: [[null, "Te sientas en el suelo, entre los obreros. Al rato, tu criatura se echa a tu lado. Los obreros la miran, y uno le rasca la cabeza con una mano dura y gris."],
                      ["escoria", "El Cuidador está con nosotros. ¡El Cuidador está con nosotros!"],
                      [null, "La noticia corre. Esa noche se cierran los hornos hondos. Fogarín no baja a hablar. Cobre se va sin despedirse."],
                      ["escoria", "Esto no lo olvida el Gremio. Ni las Casas. Pero los dedos que no se ponen de piedra esta semana son nuestros."]], end: { xp: 20, flag: ["m4_huelga", "u4_barrio"] } },
      recado: { say: [[null, "Le llevas la bolsa a Escoria. Ella la abre, la mira y la tira a sus pies."],
                      ["escoria", "Una bolsa. Por mis manos."],
                      [null, "Pero detrás de ella, un obrero joven se agacha y la levanta. Después otro. Al otro día, la mitad vuelve a los hornos hondos. Escoria se queda sola en la entrada, gritando, más fuerte que nunca."],
                      ["cobre", "Gracias. Mi Casa no olvida a los que la ayudan. Tampoco a los que no."]], end: { xp: 12, coins: 30, flag: "m4_recado" } },
      mediar: { say: [[null, "Subes a hablar con Fogarín. Bajas a hablar con Escoria. Subes otra vez. Tarda tres días."],
                      [null, "Al final hay un trato: turnos de una hora en los hornos hondos, y un obrero que mira las manos de todos al salir. Nadie está contento. Todos firman."],
                      ["escoria", "Esto es poco. Pero lo firmé. Si mañana veo una mano más de piedra, rompo el papel."],
                      ["cobre", "La Campana se va a atrasar un año. Mi Casa no tiene un año. Pero bueno. Gracias por no elegir."]], end: { xp: 16, flag: ["m4_mediar", "u4_fuego"] } },
    } },

    "e4-manos": { kind: "encuentro", need: { era: 4, layer: 2 }, who: { yunque: "Yunque, forjador" }, start: "a", nodes: {
      a: { say: [[null, "En el último horno, el más hondo, un forjador ancho como una puerta martilla un lingote rojo. Lleva un amuleto con la cara de una estatua sin nombre. Golpea con una mano. La otra la tiene apoyada en el yunque, quieta."],
                 ["yunque", "No la puedo mover. Desde hace una luna. No duele. Solo pesa."],
                 ["yunque", "Es el Herrero Sin Nombre, el de la tercera estatua. Él forjó las primeras herramientas del Claro. Si me pasa lo mismo que a él, es que estoy haciendo lo mismo que él. Es un honor."]],
           opts: [{ t: "«¿Sabe cómo terminó el Herrero?»", go: "termino", once: true },
                  { t: "Contarles a todos los obreros lo de la estatua", go: "contar" },
                  { t: "No decir nada", go: "callar" },
                  { t: "Contárselo solo a Yunque", go: "yunque" }] },
      termino: { say: [["yunque", "Se quedó en el Corazón. Para siempre. Como una estatua. Eso dicen los ritos."],
                       ["yunque", "No dicen por qué. Yo creo que porque terminó su trabajo. Yo también quiero terminar el mío."]], back: "a" },
      contar: { say: [[null, "Juntas a los obreros del turno en la boca del horno. Les cuentas lo de la tercera estatua: la escoria pegada en la base, igual que la de sus manos. El forjador que sacó metal de abajo y terminó de piedra."],
                      [null, "Hay silencio. Después, un murmullo. Un obrero se mira las uñas. Otro deja la pala en el suelo y no la vuelve a levantar."],
                      ["yunque", "Les quitaste el honor. Ahora es solo miedo."],
                      [null, "Al otro día, la mitad de los obreros no baja. Los hornos hondos trabajan a medias. Yunque baja igual, con su mano quieta."]], end: { xp: 18, flag: "m4_manosContadas" } },
      callar: { say: [[null, "No dices nada. Yunque sigue martillando. El lingote se pone negro, después rojo otra vez, como si respirara."],
                      ["yunque", "Usted sabe algo. Se le nota. Bueno. Cada uno carga lo suyo."],
                      [null, "Los hornos hondos siguen trabajando a todo fuego. Esa noche, en el Corazón, alguien deja una vela al pie de la tercera estatua."]], end: { xp: 10, flag: "m4_manosCalladas" } },
      yunque: { say: [[null, "Esperas a que se vayan los otros. Le cuentas a Yunque, solo a él, lo de la estatua y la escoria."],
                      ["yunque", "Entonces no fue un honor. Fue un precio."],
                      [null, "Se queda mucho rato mirando su mano gris sobre el yunque."],
                      ["yunque", "Voy a terminar la Campana igual. Pero voy a ser el último que baja tan hondo. A los otros los mando arriba. Y no les digo por qué. Si se lo digo, se van. Y si se van, la Campana no se termina."]], end: { xp: 16, flag: "m4_manosYunque" } },
    } },

    "e4-ascuas": { kind: "dialogo", need: { era: 4, layer: 3 }, who: { tizon: "Maese Tizón" }, start: "a", nodes: {
      a: { say: [[null, "En una casa vieja en el borde del Cráter, un anciano cuenta monedas en la mesa, dos veces cada pila. Tiene más de cien años. Sus ojos son dos brasas chiquitas."],
                 ["tizon", "Tú. Te acuerdo. De antes de todo. Cuando la Noche de Ascuas era una fiesta, y se apagaban los hornos una noche al año para que el Fuego se acordara de que también sabe no arder."],
                 ["tizon", "Hace cuarenta años que no se hace. El Gremio dice que es perder una noche de trabajo. Yo digo que es la única noche en que el Fuego no bebe. Ya nadie se acuerda de cómo era."]],
           opts: [{ t: "«¿Cómo era la Noche de Ascuas?»", go: "como", once: true },
                  { t: "Revivir la Noche de Ascuas este año", go: "revivir" },
                  { t: "«Déjela olvidada. Ya no es de este tiempo.»", go: "olvidar" }] },
      como: { say: [["tizon", "Se apagaban todos los hornos al atardecer. Todos. Se cantaba la canción del Fuego con las manos frías. Y a la mañana se encendía uno solo, con una brasa vieja, y desde ese se encendían los otros."],
                    ["tizon", "Era para acordarse de que el Fuego empieza en una sola brasa. Que no es de nadie. Se me olvidó la letra de la canción. Me acuerdo de la música."]], back: "a" },
      revivir: { say: [[null, "Vas de horno en horno con Tizón, que camina con dos bastones. Él habla con los maestros. Tú hablas con los obreros. Algunos se ríen. Muchos no."],
                       [null, "Al atardecer del día más corto, se apagan los hornos. No todos: los hondos siguen ardiendo, porque el metal de raíz no se deja apagar. Pero los otros sí. El Cráter queda a oscuras por primera vez en cuarenta años."],
                       [null, "Alguien tararea la música. Otros la siguen. Nadie sabe la letra. Escoria, en la oscuridad, inventa una."],
                       ["tizon", "No era así. Pero se parece. A la mañana voy a prender el primero. Con una brasa vieja. Tengo una guardada desde hace cuarenta años."]], end: { xp: 22, flag: ["m4_ascuasViva", "u4_fuego"] } },
      olvidar: { say: [["tizon", "Olvidada. Sí. Como yo."],
                       [null, "Vuelve a contar las monedas. Pierde la cuenta. Empieza de nuevo."],
                       ["tizon", "Cuando me muera, no va a quedar nadie que se acuerde de la música. Bueno. A lo mejor el Fuego no necesita acordarse de nada. A lo mejor por eso bebe tanto."]], end: { xp: 10, flag: "m4_ascuasOlvido" } },
    } },
  });

  /* ---------- Prado Aurora: turnos de Campana y la niña que toca lo caliente ---------- */
  add("aurora", {
    "e4-cobre": { kind: "encuentro", need: { era: 4, layer: 1 }, who: { cobre: "Cobre, de las Casas" }, start: "a", nodes: {
      a: { say: [[null, "En la plaza del Prado hay un tablero enorme con casilleros. Cada casillero es una noche del año. La mitad ya tiene el escudo de una Casa pintado. Un hombre joven, de abrigo bueno con los puños gastados, pinta otro."],
                 ["cobre", "Turnos de Campana. Quien tenga la noche, decide si la Raíz duerme o no esa noche. Si duerme, nada se mueve bajo el Prado. Si no, se puede cavar."],
                 ["cobre", "Mi Casa compró ocho noches con lo último que le quedaba. Si la Campana no se termina, mi Casa se termina. Así que, ya ve, Cuidador: estoy a favor de la Campana."]],
           opts: [{ t: "«¿Y para qué quieren que la Raíz no duerma?»", go: "para", once: true },
                  { t: "«La Corte no olvidó lo de la Crónica, ¿no?»", go: "corte", cNeed: "m3_farol" },
                  { t: "«Que su Casa compre una noche para el Barrio.»", go: "barrio" },
                  { t: "«Vender noches de sueño es vender a la Raíz.»", go: "vender" }] },
      para: { say: [["cobre", "Para cavar, claro. Cuando la Raíz duerme, no se puede sacar metal de abajo: la tierra se cierra. Cuando está despierta, se abre. Es así."],
                    ["cobre", "No me mire así. Mi bisabuela vendía luz. Mi abuela, velas. Mi madre, nada. Yo vendo noches. Es lo que hay."]], back: "a" },
      corte: { say: [["cobre", "No. Compran noches también, con otro nombre. Las noches que ellos tienen, la Raíz no duerme, y la tierra se abre debajo del Prado."],
                     ["cobre", "Cincuenta años de Crónica Oficial y la Corte se la cobra de a una noche por vez."]], back: "a" },
      barrio: { say: [["cobre", "¿Una noche para el Barrio? ¿Gratis?"],
                      [null, "Mira el tablero. Mira el pincel. Pinta un casillero, el de la noche más larga del año, con un dibujo torcido de una puerta sin farol."],
                      ["cobre", "Que la decidan ellos. Una noche. Mi madre se va a morir de nuevo cuando lo vea. Pero las Casas no pueden ir al Corazón pidiendo y sin haber dado nada."]], end: { xp: 18, flag: ["e4_nocheBarrio", "u4_luz"] } },
      vender: { say: [["cobre", "Todo se vende, Cuidador. El agua se vendió. La luz se vendió. Si no lo vendo yo, lo vende otro, y otro se queda con la Casa."],
                      [null, "Termina de pintar el escudo. Le tiembla un poco la mano."]], end: { xp: 6 } },
    } },

    "e4-chispa": { kind: "encuentro", need: { era: 4, layer: 1 }, who: { chispa: "Chispa", tizon: "Maese Tizón" }, start: "a", nodes: {
      a: { say: [[null, "En el camino del Prado al Cráter, una niña flaca de la ladera sur está agachada junto a un lingote caído de una carreta. Lo toca con la punta del dedo. Lo retira. Lo vuelve a tocar."],
                 ["chispa", "No quema tanto. Quema lindo. Como cuando te sientas muy cerca del fuego en invierno."],
                 ["chispa", "Me llamo Chispa. Quiero aprender a forjar. En el Gremio no me dejan entrar porque soy de la ladera sur y no tengo apellido de horno. Pero yo sé que las manos me sirven."]],
           opts: [{ t: "«Mírate el dedo.»", go: "dedo", once: true },
                  { t: "Llevarla con Maese Tizón", go: "tizon" },
                  { t: "Regalarle un martillo y decirle que forje con hierro común", go: "martillo" },
                  { t: "«No toques eso. Vete a casa.»", go: "casa" }] },
      dedo: { say: [[null, "Chispa se mira la punta del dedo. Hay una manchita gris, del tamaño de una lenteja, donde tocó el lingote."],
                    ["chispa", "Se va a ir. Se va con agua. ¿No?"],
                    [null, "Se la frota contra el vestido. No se va."]], back: "a" },
      tizon: { say: [[null, "Tizón la mira desde su silla. La hace apretar un puño, abrir la mano, sostener una tenaza vacía."],
                     ["tizon", "Tiene manos de forja. Lástima que nació en este tiempo. Le voy a enseñar a forjar en frío. Hierro del río. Sin metal de abajo."],
                     ["chispa", "¿En frío? Eso es para chicos."],
                     ["tizon", "Eso es para los que quieren tener manos cuando sean viejos. Aprende eso primero. Lo otro lo aprende cualquiera."]], end: { xp: 16, flag: "e4_chispaTizon" } },
      martillo: { say: [[null, "Le das un martillo chico de tu cinturón. Chispa lo sostiene con las dos manos, como un tesoro."],
                        ["chispa", "Hierro común. Bueno. Igual voy a hacer algo con esto. Algo que nadie hizo."],
                        [null, "Se va corriendo hacia la ladera. Del lingote caído, en el camino, sube un humo finito que huele a tierra quemada."]], end: { xp: 12, flag: "e4_chispaMartillo" } },
      casa: { say: [["chispa", "Usted también. Todos me dicen eso."],
                    [null, "Se va. Pero antes, cuando cree que no la ves, vuelve a tocar el lingote con la punta del dedo."]], end: { xp: 6, flag: "e4_chispaSola" } },
    } },
  });

  /* ---------- Bosque Hondo: la tala para los hornos y la resina que ablanda ---------- */
  add("forest", {
    "e4-tala": { kind: "encuentro", need: { era: 4, layer: 1 }, who: { hacha: "Hacha, leñadora" }, start: "a", nodes: {
      a: { say: [[null, "En el Bosque Hondo se oye un ruido que nunca se oía: hachas, muchas, todo el día. Donde había un roble de tres siglos hay un tocón ancho como una mesa, que gotea resina como si llorara."],
                 ["hacha", "El Gremio paga tres veces lo que paga el Concejo por cuidar. Los hornos hondos necesitan leña para calentar el metal frío antes de mezclarlo con el de raíz."],
                 ["hacha", "Mi abuela cuidaba estos árboles. Yo los corto. Mi hija va a comer este invierno. Hagan las cuentas ustedes."]],
           opts: [{ t: "«¿Qué dice el Concejo?»", go: "concejo", once: true },
                  { t: "«Por cada árbol que corten, planten tres.»", go: "plantar" },
                  { t: "Esconderles las hachas por una noche", go: "esconder" },
                  { t: "Ayudarla a cargar la leña", go: "cargar" }] },
      concejo: { say: [["hacha", "El Concejo dice que no. El Concejo dice que no a todo desde hace cien años. Mientras dicen que no, el Gremio paga."],
                       ["hacha", "Si el Concejo pagara por cuidar lo que paga el Gremio por cortar, no habría hachas en el Bosque. Pero el Concejo no tiene hornos. Tiene musgo."]], back: "a" },
      plantar: { say: [["hacha", "¿Tres? ¿Y quién paga los brotes?"],
                       [null, "Lo piensa con el hacha apoyada en el hombro. Después silba fuerte. Los otros leñadores dejan de cortar."],
                       ["hacha", "Tres por cada uno. Lo pagamos nosotros, del jornal. Y se lo vamos a cobrar al Gremio después, en el Corazón, cuando se hable de quién paga qué. Que el Concejo vea que el Bosque también sabe cuidar sin decir que no."]], end: { xp: 20, flag: ["e4_tresPorUno", "u4_planta"] } },
      esconder: { say: [[null, "De noche escondes las hachas en un hueco bajo las raíces de un árbol viejo. A la mañana, los leñadores las buscan por todo el claro."],
                        [null, "Hacha las encuentra al mediodía. Te mira de lejos. No dice nada. Esa tarde cortan el doble, para recuperar el día perdido."]], end: { xp: 8, flag: "e4_hachasEscondidas" } },
      cargar: { say: [[null, "Cargas leña con ella hasta la carreta. Es pesada, húmeda, y huele a resina. Al final del día tienes los brazos llenos de rasguños."],
                      ["hacha", "Gracias. Nadie de afuera nos ayuda. Nos miran como si fuéramos el Gremio. No somos el Gremio. Somos los que el Gremio usa."]], end: { xp: 10, coins: 10 } },
    } },

    "e4-resina": { kind: "dialogo", need: { era: 4, layer: 2 }, who: { hacha: "Hacha, leñadora", escoria: "Escoria, obrera", fogarin: "Fogarín, Maestro del Gremio" }, start: "a", nodes: {
      a: { say: [[null, "En el claro de los tocones, Escoria está sentada con las manos metidas hasta las muñecas en un balde de resina caliente. Tiene los ojos cerrados. Hacha la mira con los brazos cruzados."],
                 ["escoria", "Ablanda. La resina de los árboles viejos ablanda las manos. No las cura, pero las ablanda. Puedo cerrar el puño otra vez."],
                 ["hacha", "Solo la de los árboles viejos. Los de tres siglos. Para un balde hay que cortar uno. Y hay cuatrocientos obreros con las manos grises en el Cráter."]],
           opts: [{ t: "«¿Cuántos árboles viejos quedan?»", go: "cuantos", once: true },
                  { t: "«Corten los que hagan falta. Las manos primero.»", go: "cortar" },
                  { t: "«Ni uno más. Busquen otra forma.»", go: "ninguno" },
                  { t: "«Un balde por horno, y que lo pague el Gremio.»", go: "gremio" }] },
      cuantos: { say: [["hacha", "Doscientos, quizás. Antes había miles. Se los llevaron los hornos de antes, y los de antes de antes."],
                       ["escoria", "Doscientos árboles. Cuatrocientas manos. Yo no voy a elegir cuál vale más. Para eso están los que mandan."]], back: "a" },
      cortar: { say: [[null, "Esa semana caen veinte árboles viejos. La resina va en baldes al Cráter. Los obreros meten las manos y las sacan blandas, rosadas, y lloran algunos."],
                      ["hacha", "Veinte. En una semana. Mi abuela tardó toda la vida en ver crecer uno."],
                      ["escoria", "Gracias. No me importa el Bosque. Me importan estos dedos. Pero gracias."]], end: { xp: 14, flag: "e4_resinaTala" } },
      ninguno: { say: [["escoria", "¿Otra forma? ¿Cuál? Dígamela y la uso."],
                       [null, "No tienes respuesta. Escoria saca las manos del balde. Se le vuelven a poner rígidas mientras la miras."],
                       ["hacha", "No es justo para ella. Pero tampoco es justo para los árboles. A veces no hay nada justo, y hay que elegir igual."]], end: { xp: 10, flag: "e4_resinaNo" } },
      gremio: { say: [[null, "Llevas la propuesta al Gremio. Fogarín la firma esa misma tarde, sin regatear: un balde de resina por horno, por luna, pagado por el Gremio, y tres brotes por cada árbol."],
                      ["fogarin", "No lo hago por bueno. Lo hago porque si los obreros no pueden cerrar el puño, no hay Campana."],
                      ["escoria", "Me da igual por qué. Lo firmó. Eso queda."]], end: { xp: 18, flag: "e4_resinaGremio" } },
    } },
  });

  /* ---------- Hondonada Umbría: carbón sin humo y el nombre del Herrero ---------- */
  add("hollow", {
    "e4-hulla": { kind: "encuentro", need: { era: 4, layer: 1 }, who: { hulla: "Hulla, carbonera de la Corte" }, start: "a", nodes: {
      a: { say: [[null, "Detrás de la Hondonada, en una hondonada más chica, hay montañas de carbón negro como agujeros. Una mujer con velo gris y las manos teñidas los cubre con lonas para que no se vean desde arriba."],
                 ["hulla", "Carbón de sombra. La madera de aquí, quemada despacio bajo tierra, da un carbón que arde sin humo. El Gremio lo usa para los hornos hondos, donde el humo no tiene por dónde salir."],
                 ["hulla", "Lo vendemos por la puerta de atrás. Si las Casas supieran que la Corte calienta la Campana, dejarían de comprar turnos. Y la Corte necesita las monedas."]],
           opts: [{ t: "«¿Por qué esconderlo?»", go: "esconder", once: true },
                  { t: "«Véndalo a la luz del día, con el nombre de la Corte.»", go: "luz" },
                  { t: "«Que el Barrio tenga carbón este invierno.»", go: "barrio" },
                  { t: "Contárselo a Cobre", go: "cobre" }] },
      esconder: { say: [["hulla", "Porque la Corte siempre hizo las cosas de espaldas. Es lo que sabe hacer. Lo hizo con la savia, con los pozos, con las visiones."],
                        ["hulla", "Y porque si se sabe, nos culpan otra vez. De la Campana, de las manos, de lo que pase después. Ya nos culparon una vez por una noche que fue de todos."]], back: "a" },
      luz: { say: [["hulla", "¿Con el nombre de la Corte? ¿Que todos vean que somos parte de esto?"],
                   [null, "Mira las lonas. Mira el carbón. Se saca el velo y lo dobla."],
                   ["hulla", "Está bien. Si nos van a culpar, que sea por algo que hicimos de verdad, y a la vista. Que se vea también que la Campana tiene algo nuestro. Cuando llamen del Corazón, la Corte va a estar."]], end: { xp: 20, flag: ["e4_carbonVisto", "u4_sombra"] } },
      barrio: { say: [[null, "Hulla manda tres carretas al Barrio esa misma noche, sin nota, sin velo, sin escudo."],
                      ["hulla", "Por los pozos. Por la Velada. Por lo que haya sido. No es perdón. Es carbón."]], end: { xp: 14, flag: "e4_carbonBarrio" } },
      cobre: { say: [[null, "Cobre se entera esa misma tarde. Al día siguiente, las Casas devuelven doce turnos de Campana. Exigen al Gremio que deje de comprar carbón a la Corte."],
                     ["hulla", "Sabía que iba a pasar. Siempre pasa. La Corte se queda con el carbón y sin monedas. Y el Gremio compra el carbón igual, más barato, en otra puerta de atrás."]], end: { xp: 8, flag: "e4_carbonDelatado" } },
    } },

    "e4-ebano": { kind: "dialogo", need: { era: 4, layer: 2 }, who: { ebano: "Ébano, archivero de la Corte", yunque: "Yunque, forjador" }, start: "a", nodes: {
      a: { say: [[null, "En el archivo de la Corte, un archivero joven, de velo nuevo y manos limpias, desenrolla un pergamino tan viejo que se deshace en las puntas."],
                 ["ebano", "Esto estaba en la caja más vieja. Es una lista de las primeras forjas del Claro. Y al final, tachado con tinta de otra época, un nombre: el del forjador que sacó el primer metal de abajo."],
                 ["ebano", "El Herrero Sin Nombre tenía nombre. Alguien lo borró. Y el sello que lo tachó es el del Gremio de la Brasa."]],
           opts: [{ t: "«¿Por qué lo habrá borrado el Gremio?»", go: "porque", once: true },
                  { t: "«Lléveselo a Yunque. Él reza a ese hombre.»", go: "yunque" },
                  { t: "«Muéstrelo en el Corazón, a todos.»", go: "corazon" },
                  { t: "«Guárdelo. No es el momento.»", go: "guardar" }] },
      porque: { say: [["ebano", "Supongo que porque un herrero con nombre es un hombre que murió por su trabajo. Un herrero sin nombre es un santo."],
                      ["ebano", "A los santos se les reza. A los muertos por el trabajo se les paga. El Gremio prefirió rezar."]], back: "a" },
      yunque: { say: [[null, "Llevas el pergamino al Cráter. Yunque lo sostiene con la mano buena. La otra cuelga, gris, al costado."],
                      [null, "Lee el nombre en voz baja. No lo repite. Lo dobla y lo guarda en el amuleto, detrás de la cara sin nombre."],
                      ["yunque", "Ahora sé a quién le estoy rezando. No a un santo. A un obrero que nadie cuidó. Voy a terminar la Campana por él. Y después voy a decir su nombre en voz alta."]], end: { xp: 18, flag: "e4_nombreYunque" } },
      corazon: { say: [[null, "Ébano lleva el pergamino al Corazón y lo clava en la base de la tercera estatua, sobre la escoria."],
                       [null, "Los del Gremio lo arrancan esa misma noche. Al día siguiente hay cuatro copias clavadas. Alguien en la Corte se pasó la noche copiando."],
                       ["ebano", "La Corte sabe esconder cosas. Esta vez supo mostrarlas. Es la primera vez que me siento orgulloso del velo."]], end: { xp: 20, flag: "e4_nombreVisto" } },
      guardar: { say: [["ebano", "Tiene razón. Si sale ahora, el Gremio va a decir que la Corte inventó el papel para frenar la Campana."],
                       [null, "Lo enrolla con cuidado y lo guarda en una caja nueva, con llave."],
                       ["ebano", "Algún día alguien va a necesitar ese nombre. Ojalá que no sea tarde."]], end: { xp: 10, flag: "e4_nombreGuardado" } },
    } },
  });

  /* ---------- Lago Espejo: el agua que hierve y la forja hundida ---------- */
  add("lake", {
    "e4-hierve": { kind: "encuentro", need: { era: 4, layer: 1 }, who: { salitre: "Salitre, pescadora", fogarin: "Fogarín, Maestro del Gremio" }, start: "a", nodes: {
      a: { say: [[null, "En la orilla sur del Lago Espejo sube vapor del agua como de una olla. Hay peces blancos flotando, cocidos. Una mujer de las Mareas los junta con una red, con cara de asco."],
                 ["salitre", "Debajo hay hornos. Hornos hondos del Gremio, que cavaron por debajo del Cráter hasta llegar aquí. El agua hierve donde están."],
                 ["salitre", "Mi abuela vendía agua. Mi madre la cuidaba. Yo junto pescado cocido que nadie quiere comprar porque huele a metal. Las Mareas siempre pagamos lo que otros hacen abajo."]],
           opts: [{ t: "«¿El Gremio sabe que esto pasa?»", go: "sabe", once: true },
                  { t: "«Que el Gremio pague a las Mareas por cada horno bajo el lago.»", go: "pagar" },
                  { t: "Bucear cerca del vapor, a ver qué hay", go: "bucear" },
                  { t: "Ayudarla a juntar los peces para el Barrio", go: "barrio" }] },
      sabe: { say: [["salitre", "Sabe. Le mandamos una barca llena de peces cocidos. Nos mandaron una bolsa de monedas y una nota: «Gracias por el pescado»."],
                    ["salitre", "Así son. Te pagan para que te calles, y lo llaman comprar."]], back: "a" },
      pagar: { say: [[null, "Vas al Cráter con Salitre y una barca de peces cocidos. Fogarín los mira, uno por uno, mucho rato."],
                     ["fogarin", "Me crié entre las Mareas. Ola me enseñó a nadar. Y ahora les hiervo el lago."],
                     [null, "Firma un papel: una moneda por pez cocido, cada semana, mientras haya hornos debajo. No es mucho. Es algo."],
                     ["salitre", "Nunca nadie nos pagó por lo que nos quitó. Las Mareas van a ir al Corazón con este papel. Que se vea."]], end: { xp: 20, flag: ["e4_lagoPagado", "u4_agua"] } },
      bucear: { say: [[null, "Te metes en el agua tibia. Cuanto más bajas, más caliente está. Abajo ves una luz roja, y paredes de piedra tallada, viejas, muy viejas."],
                      [null, "Subes antes de que te duela. Tienes la piel roja como un camarón."],
                      ["salitre", "¿Viste algo? Tienes cara de haber visto algo."]], end: { xp: 14, hurt: 0.1, flag: "e4_luzHundida" } },
      barrio: { say: [[null, "Juntan los peces en canastos y los llevan al Barrio. Huelen a metal, pero están cocidos y son gratis."],
                      ["salitre", "Comen igual. El hambre no tiene olfato. Eso decía mi abuela."]], end: { xp: 10 } },
    } },

    "e4-forjahundida": { kind: "encuentro", need: { era: 4, layer: 2 }, who: { salitre: "Salitre, pescadora", yunque: "Yunque, forjador" }, start: "a", nodes: {
      a: { say: [[null, "El agua bajó otra vez donde hierve, y en la orilla sur asoma una construcción de piedra que nadie había visto: un horno antiguo, redondo, con la boca hacia el lago. Adentro, todavía, una brasa roja."],
                 ["salitre", "Es una forja. Bajo el agua. Más vieja que cualquier cosa del Gremio."],
                 [null, "En la piedra del horno hay huellas de manos. Muchas, grabadas, como si alguien hubiera apoyado las manos en la piedra caliente para dejar la marca. Las últimas huellas son de piedra también: están pegadas a la pared, como guantes grises."]],
           opts: [{ t: "Tocar las huellas de piedra", go: "tocar" },
                  { t: "Avisar al Gremio", go: "gremio" },
                  { t: "Taparla con barro, que el agua la vuelva a cubrir", go: "tapar" },
                  { t: "Traer a Yunque", go: "yunque", cNeed: "m4_manosYunque" }] },
      tocar: { say: [[null, "Tocas una de las manos de piedra pegadas a la pared. Está tibia, como una mano de verdad."],
                     [null, "Por un instante sientes un peso en los dedos, como si se te durmieran. Retiras la mano. El peso se va despacio."],
                     ["salitre", "Se te fue el color de la cara. ¿Qué sentiste?"],
                     [null, "No sabes explicarlo. Algo que se quedó trabajando aquí hasta que ya no pudo moverse."]], end: { xp: 14, hurt: 0.05, flag: "e4_manosTocadas" } },
      gremio: { say: [[null, "Llegan tres maestros del Gremio con antorchas. Miran el horno con la boca abierta. Uno saca un cuaderno y empieza a medir."],
                      ["salitre", "Ya está. Ahora van a querer usarla. Una forja que nunca se apagó. Les va a parecer un regalo."],
                      [null, "Al otro día hay una cuerda alrededor del horno y un cartel con el escudo del Gremio."]], end: { xp: 10, flag: "e4_forjaGremio" } },
      tapar: { say: [[null, "Echan barro sobre la boca del horno hasta que la brasa no se ve. Esa noche el agua sube y lo cubre todo otra vez."],
                     ["salitre", "Que se quede abajo. Lo que estaba abajo, abajo. Mi abuela decía eso del lago. Nunca le hicimos caso."]], end: { xp: 12, flag: "e4_forjaTapada" } },
      yunque: { say: [[null, "Yunque llega caminando desde el Cráter, con la mano gris colgando. Entra en el horno hundido. Pone la mano buena sobre una de las huellas de piedra. Calza justo."],
                      ["yunque", "Aquí trabajaba. Aquí. No en el Cráter. El primero no forjaba en la montaña. Forjaba en el agua, para que el metal se enfriara."],
                      ["yunque", "Y igual se le fueron las manos. Con agua y todo. Entonces no hay forma de trabajar ese metal sin pagarlo."]], end: { xp: 20, flag: "e4_yunqueSabe" } },
    } },
  });

  /* ---------- Cuevas del Eco: los mineros del Gremio y la veta que late ---------- */
  add("caves", {
    "e4-galena": { kind: "encuentro", need: { era: 4, layer: 1 }, who: { galena: "Galena, minera" }, start: "a", nodes: {
      a: { say: [[null, "Los túneles nuevos de las Cuevas no son fríos. Bajas y el aire se pone tibio, después caliente. Una minera de la Hondura, con el casco abollado y la espalda empapada, empuja una carretilla llena de piedras rojas."],
                 ["galena", "Metal de raíz. El Gremio paga por carretilla. Nunca la Hondura ganó tanto. Mi abuelo golpeaba paredes por los muertos. Yo las golpeo por el Gremio."],
                 ["galena", "El problema es que cuanto más hondo, más caliente. Y a veces la pared responde. Golpeas, y la pared golpea de vuelta. Desde el otro lado."]],
           opts: [{ t: "«¿Quién golpea del otro lado?»", go: "quien", once: true },
                  { t: "«Que la Hondura deje de cavar los túneles calientes.»", go: "parar" },
                  { t: "Ayudarla a empujar la carretilla", go: "empujar" },
                  { t: "«Pídale más al Gremio. Arriesgan más que nadie.»", go: "mas" }] },
      quien: { say: [["galena", "Nadie, dicen los capataces. Es la roca que se dilata con el calor."],
                     ["galena", "Mi abuelo me enseñó a contar golpes. Estos van de dos en dos. Como los de la Hondura cuando avisa que alguien quedó abajo."]], back: "a" },
      parar: { say: [["galena", "¿Dejar? ¿Con lo que paga?"],
                     [null, "Pero se quita el casco. Se pasa la mano por la cara, negra de polvo."],
                     ["galena", "Mi abuelo no cavaba por plata. Cavaba para que nadie se olvidara. Voy a hablar con los otros. Si la pared golpea de dos en dos, alguien está avisando. La Hondura va a ir al Corazón con eso, no con carretillas."]], end: { xp: 20, flag: ["e4_tunelesParados", "u4_piedra"] } },
      empujar: { say: [[null, "Empujas la carretilla hasta la boca del túnel. Pesa como si estuviera llena de plomo. Al llegar arriba tienes las manos calientes, rojas."],
                       ["galena", "Gracias. Ahora límpiate bien las manos con agua fría. Bien. Los que no se las limpian, a la luna siguiente ya no las cierran igual."]], end: { xp: 10, coins: 8 } },
      mas: { say: [[null, "Galena va al Gremio con otros mineros y pide el doble. Se lo dan sin discutir."],
                   ["galena", "Sin discutir. Eso es lo que me da miedo. Si te dan el doble sin discutir, es que vale el triple."]], end: { xp: 10, flag: "e4_mineriaDoble" } },
    } },

    "e4-veta": { kind: "encuentro", need: { era: 4, layer: 2 }, who: { galena: "Galena, minera" }, start: "a", nodes: {
      a: { say: [[null, "En el túnel más hondo, Galena te muestra una veta roja que atraviesa la pared como una vena. Brilla. Y se mueve: muy despacio, sube y baja, como un pecho que respira."],
                 ["galena", "Late. Pon la mano. No toques el metal: pon la mano cerca."],
                 [null, "Pones la mano a un palmo de la veta. Sientes el calor. Y un ritmo, lento, grave: uno, pausa, uno, pausa. Como el corazón de algo muy grande que duerme."]],
           opts: [{ t: "«Es la Raíz. Esto es parte de la Raíz.»", go: "raiz" },
                  { t: "Dibujar un mapa de la veta", go: "mapa" },
                  { t: "Sellar el túnel", go: "sellar" },
                  { t: "Cantarle la nana a la veta", go: "nana" }] },
      raiz: { say: [["galena", "¿La Raíz? ¿Estamos sacando pedazos de la Raíz? ¿Para hacer una campana que la haga dormir?"],
                    [null, "Se queda mirando la carretilla llena."],
                    ["galena", "Es como sacarle sangre a alguien para hacerle un remedio para dormir. Y que se duerma porque le sacaste la sangre."]], end: { xp: 16, flag: "e4_vetaRaiz" } },
      mapa: { say: [[null, "Siguen la veta con una lámpara durante horas. Va hacia abajo y hacia el norte. Hacia el Corazón."],
                    ["galena", "Todas las vetas van para el mismo lado. Si esto es lo que creo, la Campana se está haciendo con lo mismo que va a dormir."]], end: { xp: 14, flag: "e4_vetaMapa" } },
      sellar: { say: [[null, "Tapan el túnel con piedras y argamasa. Galena golpea la pared sellada dos veces, de despedida."],
                      [null, "Desde el otro lado, lejos, muy despacio, responden dos golpes."],
                      ["galena", "Ya está. Que nadie cave aquí. Lo anoto en el libro de la Hondura. Con letra grande."]], end: { xp: 14, flag: "e4_vetaSellada" } },
      nana: { say: [[null, "Cantas la nana bajito, cerca de la veta. El ritmo se hace más lento. El brillo baja, como una brasa que se cubre de ceniza."],
                    ["galena", "Se duerme. Con la nana se duerme sola. No necesita campana. Necesita que alguien le cante."],
                    [null, "Cuando dejas de cantar, el brillo vuelve, despacio. Pero más lento que antes."]], end: { xp: 16, heal: 0.1, flag: "e4_vetaNana" } },
    } },
  });

  /* ---------- Los Altos: el metal por los pasos y la nieve que se derrite ---------- */
  add("heights", {
    "e4-peaje": { kind: "encuentro", need: { era: 4, layer: 1 }, who: { peaje: "Peaje, arriero" }, start: "a", nodes: {
      a: { say: [[null, "Por el paso del norte sube una fila de carretas con lingotes tapados con lonas. Las ruedas dejan dos rayas humeantes en la nieve. Un arriero de los Altos, con la cara quemada por el frío y por el calor a la vez, guía a los bueyes."],
                 ["peaje", "Metal de raíz para afuera. Del otro lado de las montañas pagan lo que no pagaría nadie aquí. Dicen que con esto hacen espadas que no se mellan nunca."],
                 ["peaje", "Los Altos siempre llevaron cosas de un lado al otro. Mensajes, versos, agua. Ahora llevamos esto. Lo que pesa, paga."]],
           opts: [{ t: "«¿El Gremio sabe que se vende afuera?»", go: "sabe", once: true },
                  { t: "«Que los Altos no saquen el metal del Claro.»", go: "quedar" },
                  { t: "«Cobren un peaje, y que vaya a los obreros.»", go: "cobrar" },
                  { t: "Ayudarlo a cruzar el paso", go: "cruzar" }] },
      sabe: { say: [["peaje", "El Gremio lo vende. Nosotros lo llevamos. Las Casas lo compran aquí y lo revenden allá. Todos saben. Nadie lo dice."],
                    ["peaje", "Lo que sale del Claro no vuelve, dicen los viejos. Pero las monedas sí vuelven. Esas siempre."]], back: "a" },
      quedar: { say: [["peaje", "¿Y de qué viven los Altos? ¿De viento?"],
                      [null, "Mira las rayas de humo en la nieve. Mira el valle, abajo, donde se ve el humo del Cráter."],
                      ["peaje", "Está bien. Este viaje es el último. Las carretas de los Altos no sacan más metal de abajo del Claro. Que lo saquen otros, si quieren, pero no por nuestros pasos. Eso vamos a decir en el Corazón."]], end: { xp: 20, flag: ["e4_pasosCerrados", "u4_altos"] } },
      cobrar: { say: [[null, "Peaje levanta una barrera en el paso y cobra una moneda por lingote. Las monedas las manda en una bolsa, cada luna, al Cráter, para los obreros de las manos grises."],
                      ["peaje", "No es mucho. Pero el metal que sale paga algo de lo que cuesta sacarlo. Antes no pagaba nada."]], end: { xp: 14, flag: "e4_peajeObreros" } },
      cruzar: { say: [[null, "Ayudas a empujar las carretas en la parte más empinada. La nieve se derrite bajo las ruedas y el barro te llega a los tobillos."],
                      ["peaje", "Gracias. Del otro lado nadie sabe dónde queda el Vado. Pero van a usar metal que pasó por tus manos."]], end: { xp: 10, coins: 15 } },
    } },

    "e4-alud": { kind: "encuentro", need: { era: 4, layer: 2 }, who: { peaje: "Peaje, arriero" }, start: "a", nodes: {
      a: { say: [[null, "En el pueblo de la ladera alta, debajo del paso, la gente mira la montaña con miedo. Las carretas calientes derritieron la nieve de abajo. La de arriba quedó colgando, enorme, sin nada que la sostenga."],
                 ["peaje", "Si cae, se lleva el pueblo. Treinta casas. Los viejos no quieren irse. Dicen que la montaña nunca se cayó en mil años."],
                 ["peaje", "La montaña nunca tuvo carretas calientes pasando por encima en mil años, les digo yo."]],
           opts: [{ t: "Ayudar a sacar a la gente del pueblo", go: "sacar" },
                  { t: "Hacer caer la nieve antes, con cuidado, con todos lejos", go: "caer" },
                  { t: "«Que las carretas dejen de pasar hasta que vuelva a nevar.»", go: "parar" }] },
      sacar: { say: [[null, "Pasas el día cargando viejos, cabras y cajas. Al anochecer, el pueblo está vacío. Dos viejas se niegan a salir. Las dejas con mantas y una vela."],
                     [null, "La nieve no cae esa noche. Ni la siguiente. A la tercera, cae. Las dos viejas salieron a último momento. Del pueblo quedan los techos."],
                     ["peaje", "Treinta casas. Todas por un metal que va para afuera."]], end: { xp: 18, flag: "e4_puebloSalvado" } },
      caer: { say: [[null, "Con todos lejos, Peaje y los arrieros tiran piedras desde un costado hasta que la nieve se suelta. Cae con un ruido que se oye hasta en el Cráter."],
                    [null, "Se lleva la mitad del pueblo. La otra mitad queda en pie. Nadie muere."],
                    ["peaje", "La mitad. Bueno. Los viejos me van a odiar toda la vida. Pero van a tener vida para odiarme."]], end: { xp: 16, flag: "e4_aludProvocado" } },
      parar: { say: [["peaje", "¿Parar las carretas? ¿Hasta el invierno?"],
                     [null, "Habla con los otros arrieros. Discuten a gritos. Al final, la fila de carretas espera en el valle, con los lingotes humeando bajo las lonas."],
                     [null, "Dos semanas después nieva. La nieve nueva sostiene la vieja. El pueblo se salva entero. Al Gremio le llegan los lingotes con quince días de atraso, y Fogarín no dice nada."]], end: { xp: 18, flag: "e4_carretasParadas" } },
    } },
  });

  /* ---------- El Fondo Blanco: el primer deshielo y el agua negra ---------- */
  add("deep", {
    "e4-deshielo": { kind: "encuentro", need: { era: 4, layer: 1 }, who: { tempano: "Témpano, guardiana del hielo", fogarin: "Fogarín, Maestro del Gremio" }, start: "a", nodes: {
      a: { say: [[null, "En el Fondo Blanco gotea. Gotean los techos de hielo, las paredes, los carámbanos de las puertas. Es un ruido que nadie de aquí había oído nunca. Una guardiana vieja pone baldes debajo de las goteras."],
                 ["tempano", "El hielo se derrite. Por primera vez. Mi abuela decía que el hielo del Fondo era eterno. Que lo había hecho la Raíz para guardar algo."],
                 ["tempano", "Ahora el calor viene de abajo. De los hornos del Gremio, que cavan por debajo de todo. El Fondo nunca tuvo que defenderse del fuego. No sabemos cómo."]],
           opts: [{ t: "«¿Qué guardaba el hielo?»", go: "guardaba", once: true },
                  { t: "«Vaya al Gremio y exija que cierren los hornos bajo el Fondo.»", go: "exigir" },
                  { t: "Ayudarla a mudar a la gente a las cuevas altas", go: "mudar" },
                  { t: "Juntar el agua del deshielo y guardarla", go: "guardar" }] },
      guardaba: { say: [["tempano", "Nadie sabe. Los cuentos dicen que el frío. Que la Raíz guardó aquí todo el frío del Claro para cuando hiciera falta."],
                        ["tempano", "Si se derrite, ¿a dónde va el frío? ¿Se pierde? ¿O vuelve todo junto, de golpe, algún día?"]], back: "a" },
      exigir: { say: [[null, "Témpano baja al Cráter con cuatro guardianes del Fondo, envueltos en pieles, en pleno calor. Fogarín los recibe sudando."],
                      ["fogarin", "Cerrar los hornos bajo el Fondo es atrasar la Campana un año."],
                      ["tempano", "No cerrarlos es que el Fondo deje de existir. Elija qué año prefiere perder."],
                      [null, "Fogarín cierra dos hornos de los cinco. Témpano vuelve sin agradecer. El Fondo Blanco va a ir al Corazón, dice, a contar lo que pasa cuando el fuego no pregunta."]], end: { xp: 20, flag: ["e4_hornosFondo", "u4_escarcha"] } },
      mudar: { say: [[null, "Ayudas a llevar a los viejos y a los niños a las cuevas altas, donde el hielo todavía no gotea. Tardan una semana."],
                     ["tempano", "Nos mudamos hacia arriba. Como si huyéramos del suelo. El Fondo Blanco subiendo. Mi abuela se moriría de vergüenza."]], end: { xp: 12, flag: "e4_fondoSube" } },
      guardar: { say: [[null, "Juntan el agua de las goteras en barriles de madera. Es agua clara, muy fría, que no se calienta aunque la pongas al sol."],
                       ["tempano", "Frío guardado. Si el hielo se va, por lo menos que quede esto. Algún día alguien lo va a necesitar."]], end: { xp: 14, flag: "e4_frioGuardado" } },
    } },

    "e4-aguanegra": { kind: "encuentro", need: { era: 4, layer: 2 }, who: { tempano: "Témpano, guardiana del hielo" }, start: "a", nodes: {
      a: { say: [[null, "Donde se derritió el hielo más viejo del Fondo, el que estaba debajo de la sala del Turno, aparece agua negra. No es agua: es espesa, brilla, y huele a algo que conoces de hace mucho."],
                 ["tempano", "Savia. Savia negra, de la de antes. Estaba congelada aquí abajo, desde hace no sé cuántas eras. El hielo la tenía quieta."],
                 ["tempano", "Ahora se mueve. Despacio. Hacia el sur, hacia el Corazón. Como si alguien la llamara."]],
           opts: [{ t: "Juntarla en barriles antes de que llegue lejos", go: "juntar" },
                  { t: "Volver a congelarla con el agua fría guardada", go: "congelar", cNeed: "e4_frioGuardado" },
                  { t: "Seguirla para ver a dónde va", go: "seguir" },
                  { t: "«Avise a todos los pueblos.»", go: "avisar" }] },
      juntar: { say: [[null, "Pasan dos días llenando barriles con palas de madera. La savia se pega a todo. Te deja las manos negras hasta los codos."],
                      [null, "Al tercer día, Cobre aparece con dos carretas y una bolsa. Quiere comprar los barriles. Dice que en las Casas se acuerdan de lo que valía la savia."],
                      ["tempano", "No se la vendo. Pero ya sabe que existe. Y si él sabe, todos saben."]], end: { xp: 14, flag: "e4_saviaBarriles" } },
      congelar: { say: [[null, "Echan sobre la savia el agua fría que guardaron del deshielo. Donde cae, la savia se pone dura, opaca, quieta."],
                        ["tempano", "Funciona. El frío viejo sirve para lo viejo. Pero ya no queda más agua fría. Si vuelve a derretirse, no hay con qué."]], end: { xp: 20, flag: "e4_saviaCongelada" } },
      seguir: { say: [[null, "Sigues el hilo negro por debajo del hielo durante horas. Baja por grietas, cruza bajo un río, se mete en la roca. Siempre hacia el sur."],
                      [null, "Al final se junta con otro hilo, rojo, que viene del Cráter. Los dos se meten juntos en la tierra, hacia el Corazón."],
                      ["tempano", "La savia vieja y el metal nuevo van al mismo lugar. No sé qué significa. No me gusta."]], end: { xp: 16, flag: "e4_saviaSigue" } },
      avisar: { say: [[null, "Mandas avisos con todos los que pasan. En una semana, la noticia está en todos los pueblos: hay savia negra en el Fondo Blanco."],
                      [null, "Algunos tienen miedo. Muchos se acuerdan de los cuentos. Unos cuantos empiezan a preguntar cuánto vale."],
                      ["tempano", "Avisar es lo justo. Pero los avisos también los oyen los que no deberían."]], end: { xp: 12, flag: "e4_saviaAvisada" } },
    } },
  });

  /* ---------- Corazón del Claro: la primera Campana y el final de la era ---------- */
  add("heart", {
    "e4-campana": { kind: "dialogo", need: { era: 4, layer: 3 }, who: { fogarin: "Fogarín, Maestro del Gremio", retama: "Retama, guarda del Tocón" }, start: "a", nodes: {
      a: { say: [[null, "En el Corazón, junto a la tercera estatua, cuelga de un andamio de madera una campana chica, del tamaño de un cubo, de un rojo que no se apaga. Es la primera de prueba. La grande todavía se está fundiendo."],
                 ["fogarin", "Esta ya funciona. La probamos anoche. Suena, y durante una hora, en todo el Corazón, la Raíz no se mueve. Ni un temblor."],
                 ["retama", "Soy Retama. Cuido el Tocón desde que murió el viejo Brezo. Y te digo: esa hora no fue sueño. Fue otra cosa. Las criaturas no se acercaron al Tocón en toda la noche."],
                 ["fogarin", "Las Casas quieren llevársela al Prado, para los turnos. Yo no sé a quién dársela. Decide tú. Eres la única persona a la que nadie le compró nada."]],
           opts: [{ t: "«¿Qué sintió la Raíz cuando sonó?»", go: "sintio", once: true },
                  { t: "Dársela a las Casas", go: "casas" },
                  { t: "Llevarla al Vado", go: "vado" },
                  { t: "«Que no la tenga nadie. Que se quede aquí, sin tocar.»", go: "nadie" }] },
      sintio: { say: [["retama", "Yo no sé lo que siente la Raíz. Nadie sabe. Pero las raíces del Tocón se pusieron frías como piedra. Y las flores de alrededor se cerraron a medianoche, como si fuera de día."],
                      ["fogarin", "Porque durmió. Eso es dormir."],
                      ["retama", "Eso es callarse. No es lo mismo."]], back: "a" },
      casas: { say: [[null, "La campana chica baja al Prado en una carreta de las Casas. Cobre la recibe con las manos temblando."],
                     ["fogarin", "Bueno. Ya está. Ellos pagaron. A lo mejor eso es justo."],
                     ["retama", "Ahora la Raíz duerme cuando paga una Casa. Que alguien se acuerde de este día."]], end: { xp: 16, coins: 20, flag: "m4_campanaCasas" } },
      vado: { say: [[null, "Llevas la campana chica al Vado, envuelta en una manta. Pesa como si llevaras un niño dormido."],
                    [null, "La cuelgas en la entrada, lejos de las criaturas. Nadie la toca. Tu criatura la mira todas las mañanas desde lejos, con las orejas bajas."],
                    ["fogarin", "En el Vado. Donde no se vende nada. Está bien. Que la toque quien cuida, si alguna vez hace falta."]], end: { xp: 18, flag: "m4_campanaVado" } },
      nadie: { say: [["fogarin", "¿Sin tocar? ¿Toda esa forja para nada?"],
                     [null, "Retama ata la lengua de la campana con un trapo y una cuerda. La campana queda colgando del andamio, muda, junto a la estatua del forjador."],
                     ["retama", "Para nada no. Para que se vea que se podía, y que se eligió no hacerlo. Eso también hay que forjarlo."],
                     [null, "Fogarín se va sin despedirse. Esa noche lo ven sentado al pie de la tercera estatua, con la mano en la escoria."]], end: { xp: 16, flag: "m4_campanaNadie" } },
    } },

    "e4-final": { kind: "dialogo", need: { era: 4, eraWin: "heart" }, first: true, once: true, who: { fogarin: "Fogarín, Maestro del Gremio", escoria: "Escoria, obrera", retama: "Retama, guarda del Tocón" }, start: "a", nodes: {
      a: { say: [[null, "La Raíz Caliente cae, y el suelo del Corazón queda tibio, como el piso de una cocina. Arriba, en el andamio, cuelga la Campana grande, terminada. Es roja y no se apaga."],
                 ["fogarin", "Está lista. Una nota y la Raíz duerme para siempre. Nadie más tiene que bajar a los hornos hondos, porque ya no hace falta más metal. Nadie más se vuelve piedra."],
                 ["escoria", "Y nadie más le canta. Y nadie sabe qué pasa con algo que duerme así, sin que nadie le cante, para siempre."],
                 ["retama", "Hay otra cosa que se puede hacer. Apagar los hornos. Todos. No una noche: para siempre. Que el Fuego deje de beber del todo."]],
           opts: [{ t: "«¿Qué pasa si toco la Campana?»", go: "q1", once: true },
                  { t: "«¿Y si apagamos todos los hornos?»", go: "q2", once: true },
                  { t: "«¿Y si no lo decide uno solo?»", go: "q3", once: true },
                  { t: "Tocar la Campana", go: "campana" },
                  { t: "Apagar todos los hornos del Claro", go: "ascuas" },
                  { t: "Repartir el metal: una forja chica por pueblo, con los nueve de testigos", go: "forja", cNeed: "e4_nueve" }] },
      q1: { say: [["fogarin", "La Raíz duerme. Profundo. No hay más temblores, no hay más savia, no hay más sed. Los hornos hondos se cierran porque ya no hacen falta."],
                  ["retama", "Y la Raíz no oye más. Ni nanas, ni pasos, ni nada. Algo sordo que duerme debajo de todo. No sé qué es eso, pero no es paz."]], back: "a" },
      q2: { say: [["escoria", "Se acaban las manos de piedra. Se acaba el metal de raíz. Se acaba el Gremio, también. Y nosotros."],
                  ["fogarin", "El Fuego no sabe hacer otra cosa que arder. Sin hornos, el Fuego baja al Vado a pedir. Toda la vida vi al Fuego comprado. Ahora lo vería mendigando."]], back: "a" },
      q3: { say: [["retama", "Se reparte el metal. Una forja chica por pueblo. Ninguna honda. Cada pueblo saca poco, y paga poco."],
                  ["escoria", "Y la sed se reparte. Poca en todas partes. La Raíz se enfría por todos lados a la vez. Eso solo funciona si los nueve dicen que sí. Si falta uno, ese uno hace su forja honda, y vuelve todo."]], back: "a" },
      campana: { say: [[null, "Subes al andamio. Fogarín te da el mazo. Pesa como si fuera de piedra."],
                       [null, "Golpeas. La nota es tan grave que no se oye: se siente en los huesos, en los dientes, en el suelo. Baja hasta el fondo. Abajo, algo enorme deja de moverse."],
                       ["fogarin", "Ya está. Ya está. Nadie más."],
                       ["retama", "Escucha. Ya no se oye nada. Ni los pájaros del Corazón."],
                       [null, "Esa noche empieza a nevar. Es temprano para la nieve. Nadie le da importancia."]], end: { xp: 60, flag: "m4_campana" } },
      ascuas: { say: [[null, "Bajas al Cráter con Escoria y Retama. Horno por horno, se apagan. Los obreros ayudan. Algunos lloran. Algunos rompen las palas contra el suelo."],
                      [null, "Los hornos hondos no se apagan con agua. Los tapan con piedras, con tierra, con lo que hay. Tarda una semana entera."],
                      ["escoria", "Ya está. Ninguna mano más de piedra. Y ningún trabajo, tampoco. Mañana voy al Vado a ver si alguien necesita leña. Yo, que tenía cuatrocientos obreros detrás."],
                      ["fogarin", "La Campana queda colgada en el Corazón. Fría. Muda. Es lo más grande que hice en mi vida, y es una estatua."]], end: { xp: 60, flag: "m4_ascuas" } },
      forja: { say: [[null, "Llegan los nueve. Cada uno trae algo: la huelga de Escoria, la resina del Bosque, el carbón de la Corte, el papel de las Mareas, el libro de la Hondura, los pasos cerrados de los Altos, el reclamo del Fondo, la Noche de Ascuas, el turno que las Casas regalaron."],
                     [null, "Fogarín funde la Campana grande. El metal rojo se reparte en nueve lingotes. Cada pueblo se lleva uno para una forja chica. Ninguna honda. Ningún horno que baje más que un brazo."],
                     ["escoria", "Poca forja. Poco metal. Pocas manos de piedra. Poco de todo."],
                     ["retama", "Y poca sed. En todas partes. La Raíz no duerme ni se despierta: se enfría, despacio, por todos lados a la vez. No sé si eso es bueno. Es de todos."]], end: { xp: 60, flag: "m4_forja" } },
    } },
  });
  /* ==================== Entrega 2: el Día (Prado Aurora, Cráter Tibio, Bosque Hondo) ==================== */

  /* ---------- Prado Aurora: el tablero de las noches, la tierra que se abre y la subasta ---------- */
  add("aurora", {
    "e4-tablero": { kind: "encuentro", need: { era: 4, layer: 1 }, who: { cerillo: "Cerillo" }, start: "a", nodes: {
      a: { say: [[null, "Delante del tablero de los turnos de Campana, un chico del Barrio, descalzo, cuenta los casilleros con el dedo. Mueve los labios. Se equivoca y empieza de nuevo."],
                 ["cerillo", "Trescientos sesenta y cinco. Y ninguno tiene una puerta sin farol. Bueno, uno sí, pero lo pintaron hace poco."],
                 ["cerillo", "Mi abuela dice que antes la Raíz dormía cuando alguien le cantaba. Ahora duerme cuando alguien paga. ¿Cuánto sale una noche? Para saber cuánto tengo que juntar."]],
           opts: [{ t: "«¿Para qué quieres una noche?»", go: "para", once: true },
                  { t: "Decirle el precio de verdad", go: "precio" },
                  { t: "Enseñarle la nana, que no cuesta nada", go: "nana" },
                  { t: "Pintar un casillero con él, con tiza, sin pagar", go: "tiza" }] },
      para: { say: [["cerillo", "Para que la Raíz duerma la noche del cumpleaños de mi hermana. Esa noche siempre tiembla el Barrio. Se caen las tazas. Ella llora."],
                    ["cerillo", "Una noche quieta. Nada más. Para que no se caiga nada."]], back: "a" },
      precio: { say: [[null, "Le dices lo que pagó la Casa de Cobre por ocho noches. Cerillo hace la cuenta en el polvo con un palito."],
                      ["cerillo", "Doscientos años de juntar latas. Bueno. Ya sé."],
                      [null, "Borra la cuenta con el pie. No llora. Se queda mirando el tablero un rato más, como se mira una vitrina."]], end: { xp: 8 } },
      nana: { say: [[null, "Te sientas con él en el borde de la fuente y le cantas la nana, despacio, dos veces. Cerillo la repite con la voz desafinada."],
                    ["cerillo", "¿Y esto la hace dormir? ¿Sin pagar?"],
                    [null, "Le dices que antes sí. Que no sabes si ahora alcanza. Cerillo se encoge de hombros."],
                    ["cerillo", "Igual la voy a cantar esa noche. Si no sirve, por lo menos mi hermana se duerme."]], end: { xp: 14, heal: 0.1, flag: "e4_nanaPabilo" } },
      tiza: { say: [[null, "Toman una tiza del suelo. En el borde del tablero, fuera de los casilleros, Cerillo dibuja uno más: una noche que no está en el año, con una taza parada en el medio."],
                    [null, "Al día siguiente hay diez casilleros de tiza. Al otro, cuarenta. Las Casas mandan a borrarlos. Vuelven a aparecer."],
                    ["cerillo", "No sirven para nada. Ya sé. Pero ahora todos ven que faltan noches."]], end: { xp: 16, flag: ["e4_casillerosTiza", "u4_barrio"] } },
    } },

    "e4-badajo": { kind: "encuentro", need: { era: 4, layer: 1 }, who: { badajo: "Badajo, campanero de las Casas" }, start: "a", nodes: {
      a: { say: [[null, "En el patio de una Casa, un hombre joven golpea una campana de madera con un mazo forrado en cuero. No suena nada. Golpea otra vez. Cuenta en voz alta."],
                 ["badajo", "Me están enseñando a tocar la Campana. Las Casas quieren un campanero propio para cuando la traigan. Practico con madera porque la de verdad, la de prueba, deja sordo al que la toca de cerca."],
                 ["badajo", "Ya no oigo bien de este oído. Del otro tampoco mucho. Dicen que es la madera. No es la madera: es que me hicieron tocar la de verdad una vez, para ver si aguantaba."]],
           opts: [{ t: "«¿Qué se siente cuando suena?»", go: "siente", once: true },
                  { t: "«Deje de practicar. Le están comprando las orejas.»", go: "dejar" },
                  { t: "«Practique con tapones. Pida que se los den.»", go: "tapones" },
                  { t: "Golpear la campana de madera tú", go: "golpear" }] },
      siente: { say: [["badajo", "No se oye. Se siente en los dientes. Y después, un silencio enorme, como si alguien hubiera cerrado una puerta del tamaño del Prado."],
                      ["badajo", "Las palomas se fueron del patio esa tarde. No volvieron."]], back: "a" },
      dejar: { say: [["badajo", "¿Y qué hago? Mi padre fue farolero. Cuando se apagaron los faroles, se quedó sentado en la puerta diez años. Yo no quiero sentarme en la puerta."],
                     [null, "Pero deja el mazo apoyado en la pared."],
                     ["badajo", "Hoy no practico. Hoy escucho. Mientras todavía oigo algo."]], end: { xp: 12, flag: "e4_badajoEscucha" } },
      tapones: { say: [[null, "Badajo va a pedir tapones a la Casa. Le dan cera de abejas y una palmada en la espalda."],
                       ["badajo", "Funciona. Un poco. Por lo menos ahora sé que mis orejas valen algo para alguien. Para usted."]], end: { xp: 10 } },
      golpear: { say: [[null, "Tomas el mazo y golpeas la madera. No suena nada. Pero tu criatura, en el suelo, se pone las patas sobre las orejas, como si hubiera oído algo que tú no."],
                       ["badajo", "Ella lo oye. ¿Ve? La madera también suena. Para ellas sí."]], end: { xp: 10, flag: "e4_criaturaOye" } },
    } },

    "e4-ambar": { kind: "dialogo", need: { era: 4, layer: 2 }, who: { ambar: "Doña Ámbar" }, start: "a", nodes: {
      a: { say: [[null, "En una casa grande del Prado con las paredes desnudas, una anciana está sentada en la única silla que queda. Donde había cuadros hay marcas más claras en la pintura. Es la madre de Cobre."],
                 ["ambar", "Lo vendí todo. Los cuadros, las alfombras, el farol de la entrada, el de la Velada. Para que mi hijo compre noches de una campana que todavía no suena."],
                 ["ambar", "Mi abuela vendía luz. Yo vendo lo que mi abuela compró con la luz. Al final, Cuidador, las Casas solo saben vender. Y comprar. Y llamarlo tradición."]],
           opts: [{ t: "«¿Usted está de acuerdo con la Campana?»", go: "acuerdo", once: true },
                  { t: "«Cobre pintó una noche para el Barrio.»", go: "barrio", cNeed: "e4_nocheBarrio" },
                  { t: "«Su Casa podría dejar de comprar.»", go: "dejar" },
                  { t: "Preguntarle por el farol de la Velada", go: "farol" }] },
      acuerdo: { say: [["ambar", "Estoy de acuerdo con que mi hijo coma. La Campana es la última cosa que se puede comprar en el Claro. Si no la compramos nosotros, la compra la Corte."],
                       ["ambar", "Y si la Corte tiene las noches, la tierra del Prado se abre cuando ellos quieren. Eso ya pasó. En otra era, con otra cosa. Siempre pasa."]], back: "a" },
      barrio: { say: [["ambar", "Sí. Me lo contó. Pensó que me iba a morir del disgusto."],
                      [null, "Se ríe, bajito, sin ganas."],
                      ["ambar", "Fue lo único que hizo en su vida sin preguntarme. Ese día pensé que a lo mejor mi Casa no se termina con él. A lo mejor empieza otra cosa."]], back: "a" },
      dejar: { say: [["ambar", "¿Dejar de comprar? ¿Y quedarnos con qué?"],
                     [null, "Mira las paredes vacías. Las marcas de los cuadros."],
                     ["ambar", "Tiene razón en algo. Ya no queda nada que perder. Eso da una libertad horrible. Voy a hablar con mi hijo. No le voy a decir qué hacer. Le voy a decir que ya no hace falta que me salve."]], end: { xp: 16, flag: "e4_ambarLibera" } },
      farol: { say: [["ambar", "Lo vendí al Gremio. Lo fundieron. Era de vidrio de raíz, de cuando las Casas sacaban luz de los pozos."],
                     ["ambar", "Ahora es parte de la Campana, supongo. La luz de mi abuela, hecha campana para dormir a la Raíz que despertó. Hay cosas que vuelven solas a donde empezaron."]], end: { xp: 12, flag: "e4_farolFundido" } },
    } },

    "e4-candela": { kind: "dialogo", need: { era: 4, layer: 2 }, who: { candela: "Abuela Candela" }, start: "a", nodes: {
      a: { say: [[null, "En una esquina del Barrio, una vieja vende pan desde una ventana. Tiene las manos llenas de harina y los ojos todavía rápidos. La reconoces por la forma de contar las monedas en la palma: es Candela, la nieta de Aurelia."],
                 ["candela", "Cuidador. Soy Candela, ¿se acuerda? Todavía vive. Yo también, mire. Las dos cosas son raras."],
                 ["candela", "Mi nieto trabaja en los hornos hondos. Tiene las uñas grises. Me dice que es el hollín. Yo vi a mi abuela decir que no sabía nada con la cara de alguien que sabía todo. Conozco esa cara."]],
           opts: [{ t: "«Usted leyó el cuaderno en voz alta, en el Juicio.»", go: "leyo", cNeed: "end_candela_A" },
                  { t: "«Usted bebía una copa por luna, para ver si su abuela lo abría.»", go: "bebia", cNeed: "end_candela_B" },
                  { t: "«Usted defendía a su abuela en cada esquina.»", go: "defendia", cNeed: "end_candela_C" },
                  { t: "«¿Qué quiere hacer con su nieto?»", go: "nieto" },
                  { t: "«Dígale lo de la estatua del Corazón.»", go: "estatua" }] },
      leyo: { say: [["candela", "Lo leí y me fui. Dejé el apellido en la tarima. Desde entonces vendo pan. Nadie me pregunta de qué Casa soy."],
                    ["candela", "Mi nieto no sabe que es Albor. Mejor. Un apellido es una deuda que te dejan."]], back: "a" },
      bebia: { say: [["candela", "Hasta que se secó el lago. Nunca lo abrió. Después de muerta, igual que antes."],
                     ["candela", "Ahora veo a mi nieto hacer lo mismo con sus manos. Mirarlas y no abrirlas. Se hereda, eso."]], back: "a" },
      defendia: { say: [["candela", "Grité mucho. Ya no grito. Se me cansó la voz antes que la rabia."],
                        ["candela", "La abuela sabía. Yo también lo sabía. Por eso gritaba."]], back: "a" },
      nieto: { say: [["candela", "Que deje los hornos. No me escucha. Dice que el Gremio paga y yo vendo pan."],
                     ["candela", "Tiene razón. Pero el pan no te vuelve piedra."]], back: "a" },
      estatua: { say: [[null, "Le cuentas lo de la tercera estatua: la escoria pegada en la base, igual que en las manos de los obreros."],
                       [null, "Candela cierra la ventana del pan. Se sacude la harina de las manos."],
                       ["candela", "Mi abuela calló y le costó a todo el Barrio. Yo no voy a callar. Se lo digo a mi nieto, y a todos los nietos de esta calle. Que el Prado sepa que el Barrio también sabe cosas."]], end: { xp: 18, flag: ["e4_candelaAvisa", "u4_luz"] } },
    } },

    "e4-hundimiento": { kind: "encuentro", need: { era: 4, layer: 2 }, who: { cerillo: "Cerillo" }, start: "a", nodes: {
      a: { say: [[null, "Al amanecer, en el borde del Prado, falta una casa. Donde estaba hay un agujero redondo, hondo, con el borde todavía humeando. Abajo se ve un brillo rojo."],
                 ["cerillo", "Anoche era noche de la Corte en el tablero. La Raíz no durmió. La tierra se abrió. La familia salió por la ventana. La casa no."],
                 [null, "Alrededor del agujero, gente de las Casas mide con cuerdas. Uno de la Corte mira desde lejos, con el velo puesto. Del fondo del agujero suben golpes: alguien está picando."]],
           opts: [{ t: "«¿Quién está picando abajo?»", go: "quien", once: true },
                  { t: "Ayudar a la familia que perdió la casa", go: "familia" },
                  { t: "Bajar al agujero", go: "bajar" },
                  { t: "Encarar al de la Corte", go: "corte" }] },
      quien: { say: [["cerillo", "Mineros del Gremio. Bajaron apenas se abrió. Dicen que debajo de las casas del Prado hay vetas buenas."],
                     ["cerillo", "Las noches de la Corte la tierra se abre, y el Gremio cava. Nadie compró una noche para que la casa no se cayera."]], back: "a" },
      familia: { say: [[null, "Pasas el día con la familia: una madre, dos chicos y un abuelo que no habla. Les consigues mantas, un techo en el Vado por unas noches, sopa."],
                       ["cerillo", "Usted no les devolvió la casa. Pero les dio un lugar donde no tiembla. Eso es bastante."]], end: { xp: 14, heal: 0.05, flag: "e4_familiaVado" } },
      bajar: { say: [[null, "Bajas por una cuerda. Abajo hace un calor de horno. Tres mineros pican una veta roja que sube por la pared como una raíz."],
                     [null, "Uno te mira, se quita el pañuelo de la boca. Tiene la cara joven y las manos grises hasta la muñeca."],
                     [null, "No dice nada. Vuelve a picar. Arriba, por el agujero, se ve un pedazo de cielo con la forma de una casa."]], end: { xp: 14, hurt: 0.1, flag: "e4_hundimientoVisto" } },
      corte: { say: [[null, "Te acercas al de la Corte. Se levanta el velo. Es una mujer joven, con ojeras."],
                     [null, "Le dices que la noche era de ellos. Que la casa se cayó en su noche."],
                     [null, "Ella no lo niega. Te da una moneda, la única que tiene en la mano, para la familia."],
                     [null, "«Nosotros compramos la noche para que se abriera la tierra debajo de la Torre del Alba», dice. «No sabíamos dónde se iba a abrir. Nadie sabe dónde se abre.»"]], end: { xp: 12, flag: "e4_corteMoneda" } },
    } },

    "e4-subasta": { kind: "dialogo", need: { era: 4, layer: 3 }, who: { cobre: "Cobre, de las Casas", badajo: "Badajo, campanero de las Casas" }, start: "a", nodes: {
      a: { say: [[null, "En la plaza del Prado hay una tarima y un subastador con martillo. Se subasta el primer toque de la Campana grande, la noche en que la cuelguen: quien gane decide si suena o no."],
                 ["cobre", "Las Casas juntaron todo. Todo. La Corte también. Van parejas. Si ganamos, Badajo toca. Si gana la Corte, no suena, y esa noche la tierra se abre debajo de todo el Prado."],
                 ["badajo", "Yo no sé si quiero tocar. Pero si toco, por lo menos sé dónde no se va a abrir la tierra."]],
           opts: [{ t: "«¿Y si no gana ninguno?»", go: "ninguno", once: true },
                  { t: "Pujar por el Vado", go: "vado", fx: { cost: 40 } },
                  { t: "Dejar que gane la Corte", go: "corte" },
                  { t: "Subir a la tarima y parar la subasta", go: "parar" }] },
      ninguno: { say: [["cobre", "Entonces el toque queda libre. Y el Gremio decide. Y el Gremio vende el toque a quien pague más después. Así que gana alguien igual."]], back: "a" },
      vado: { say: [[null, "Levantas la mano. La plaza se da vuelta a mirarte. El subastador repite tu oferta, que es poca, y nadie la entiende."],
                    [null, "Las Casas y la Corte se miran. Ninguna puja más. Las dos prefieren que lo tenga el Vado antes que la otra."],
                    ["cobre", "Ganó el Vado. Con nada. Porque nadie quería que ganara el otro. Así se gana en el Claro."],
                    ["badajo", "Entonces no toco yo. Bueno. Me alegra un poco."]], end: { xp: 18, flag: "e4_toqueVado" } },
      corte: { say: [[null, "No haces nada. La puja sube. Al final, la Corte gana por una moneda. Los de velo gris aplauden en silencio."],
                     ["cobre", "Perdimos. Mi Casa perdió. Esa noche la tierra se va a abrir donde quiera la Corte."],
                     [null, "Badajo deja el mazo de madera en la tarima y se va. Se ve aliviado, aunque trata de que no se le note."]], end: { xp: 10, flag: "e4_toqueCorte" } },
      parar: { say: [[null, "Subes a la tarima. El subastador te mira con el martillo en el aire. Hablas fuerte: que la Raíz no se subasta, que la tierra que se abre no elige dueño, que la casa que se cayó era de alguien que no compró nada."],
                     [null, "Algunos aplauden. Muchos gritan. El subastador baja el martillo sin golpear."],
                     ["cobre", "Lo arruinó. Todo lo que juntamos. Bueno. Lo arruinó para la Corte también."],
                     [null, "La subasta no se hace. El toque queda en manos del Gremio, que no sabe qué hacer con él."]], end: { xp: 16, flag: "e4_subastaRota" } },
    } },

    "e4-escuela": { kind: "encuentro", need: { era: 4, layer: 3 }, who: { pizarra: "Pizarra, maestra" }, start: "a", nodes: {
      a: { say: [[null, "En una escuela del Prado, veinte chicos sentados en el suelo repiten de memoria la historia del Claro. Una maestra con tiza en el pelo los escucha con los ojos cerrados."],
                 ["pizarra", "Pase, Cuidador. Los chicos aprenden lo que pasó. Lo que dice la Crónica, por lo menos. Ahora les toca la Campana: que el Gremio va a hacer dormir a la Raíz para siempre, y que eso es progreso."],
                 ["pizarra", "Los más chicos me preguntan quién le cantaba antes a la Raíz. No sé qué decirles. ¿Usted sabe?"]],
           opts: [{ t: "«La Crónica culpa a la Corte. No es toda la verdad.»", go: "farol", cNeed: "m3_farol" },
                  { t: "«Las Casas pagaron la culpa vendiendo las forjas.»", go: "mareas", cNeed: "m3_mareas" },
                  { t: "«Ya nadie se acuerda de la Línea. Yo sí.»", go: "espejo", cNeed: "m3_espejo" },
                  { t: "Contarles a los chicos quién cantaba", go: "contar" },
                  { t: "Enseñarles la nana", go: "nana" }] },
      farol: { say: [["pizarra", "Lo sé. Mi abuela era de la Corte. Yo enseño la Crónica porque si no, me echan."],
                     ["pizarra", "Pero a los chicos de la Corte les digo, en voz baja, que su abuela no fue la única. Ellos me miran como si les hubiera dado un regalo."]], back: "a" },
      mareas: { say: [["pizarra", "Sí. Y los chicos de las Casas lo saben. Algunos lo llevan como una vergüenza, otros como una herida de guerra."],
                      ["pizarra", "Ninguno sabe que lo que vendieron es lo que ahora hace la Campana. Eso no está en ningún libro."]], back: "a" },
      espejo: { say: [["pizarra", "¿La Línea? ¿Qué Línea?"],
                      [null, "Le explicas. Ella escribe en la pizarra mientras hablas, rápido, para no olvidarse."],
                      ["pizarra", "Esto no está en ningún lado. Nadie lo sabe. Si es verdad, la Campana es un error enorme. Y nadie lo va a ver venir."]], back: "a" },
      contar: { say: [[null, "Les cuentas a los chicos: que antes la Raíz dormía con una nana, que había que juntar a todos los pueblos para cantarla, que era difícil y que por eso valía."],
                      [null, "Una nena levanta la mano. «¿Y por qué no la cantamos ahora, en vez de hacer una campana?»"],
                      [null, "Nadie contesta. Pizarra anota la pregunta en la pizarra, con letra grande, y no la borra al final de la clase."],
                      ["pizarra", "Mañana se la pregunto a las Casas. La pregunta es de la nena. Yo solo la llevo."]], end: { xp: 18, flag: ["e4_preguntaNena", "u4_luz"] } },
      nana: { say: [[null, "Cantas la nana. Los chicos la aprenden en tres vueltas. Al final la cantan solos, desafinados, fuertes."],
                    [null, "Afuera, en la calle, alguien que pasaba se para a escuchar. Después otro."],
                    ["pizarra", "No está en el programa. Pero mañana la canto de nuevo, por si se les olvida."]], end: { xp: 14, heal: 0.1, flag: "e4_nanaEscuela" } },
    } },
  });

  /* ---------- Cráter Tibio: los maestros jóvenes, la fundición, Chispa, Escoria y Tizón ---------- */
  add("crater", {
    "e4-maestros": { kind: "dialogo", need: { era: 4, layer: 1 }, who: { fogarin: "Fogarín, Maestro del Gremio", fuelle: "Fuelle, maestro joven" }, start: "a", nodes: {
      a: { say: [[null, "En la sala de los maestros del Gremio hay una mesa larga con doce sillas. Fogarín está en la cabecera. En la otra punta, un maestro joven, de brazos fuertes y uñas ya grises, golpea la mesa con el puño."],
                 ["fuelle", "¡Más hornos hondos! Con diez más, la Campana grande está en un año. ¡Y con lo que sobra, hacemos herramientas que el Claro nunca vio!"],
                 ["fogarin", "Con diez más, en un año tenemos cuatrocientas manos de piedra más. Fuelle, mírate las uñas."],
                 ["fuelle", "Mis uñas son mías, Maestro. Y el Gremio es de los que trabajan, no de los que se acuerdan de las Mareas."]],
           opts: [{ t: "«¿Por qué tanta prisa, Fuelle?»", go: "prisa", once: true },
                  { t: "Apoyar a Fogarín", go: "fogarin" },
                  { t: "Apoyar a Fuelle", go: "fuelle" },
                  { t: "«Que voten los obreros, no los maestros.»", go: "votar" }] },
      prisa: { say: [["fuelle", "Porque si no la terminamos nosotros, la terminan las Casas con nuestros hornos. O la Corte con su carbón. La Campana tiene que ser del Fuego."],
                     ["fuelle", "Toda la vida nos compraron. Por una vez, que nos compren a nosotros algo que solo nosotros sabemos hacer."]], back: "a" },
      fogarin: { say: [[null, "Hablas a favor de Fogarín. Los maestros viejos asienten. Los jóvenes te miran con desconfianza."],
                       [null, "Se vota: no hay hornos nuevos. Fuelle se levanta y se va dando un portazo."],
                       ["fogarin", "Gracias. Ese muchacho va a ser Maestro algún día. Ojalá que con manos."]], end: { xp: 12, flag: "e4_hornosNo" } },
      fuelle: { say: [[null, "Hablas a favor de Fuelle. Fogarín te mira con algo parecido a la tristeza."],
                      [null, "Se vota: cinco hornos nuevos, no diez. Fuelle sonríe como si hubiera ganado todo."],
                      ["fogarin", "Cinco. Bueno. Cinco hornos más es lo que se lleva el Fuego cuando nadie le dice que no. Acuérdate de este día, Cuidador."]], end: { xp: 10, coins: 20, flag: "e4_hornosNuevos" } },
      votar: { say: [["fuelle", "¿Los obreros? ¿Los que se sientan en el suelo con los brazos cruzados?"],
                     ["fogarin", "Los que tienen las manos. Sí. Que voten ellos."],
                     [null, "Esa tarde votan cuatrocientos obreros en el patio del Gremio, con piedras blancas y negras en un balde. Ganan las negras: ningún horno nuevo. Fuelle cuenta las piedras dos veces."],
                     ["fuelle", "Bueno. Perdí con los míos. Eso duele distinto."]], end: { xp: 18, flag: ["e4_obrerosVotan", "u4_fuego"] } },
    } },

    "e4-fundicion": { kind: "encuentro", need: { era: 4, layer: 2 }, who: { yunque: "Yunque, forjador" }, start: "a", nodes: {
      a: { say: [[null, "Es el día de la fundición. El metal de raíz corre por el canal de piedra hacia el molde enorme de la Campana grande, rojo, lento, como un río que piensa. Cien obreros miran en silencio."],
                 [null, "A mitad de camino, el canal se agrieta. El metal empieza a salirse por un costado, hacia donde están los obreros más jóvenes. Yunque está más cerca que nadie."],
                 ["yunque", "¡Atrás! ¡Todos atrás!"]],
           opts: [{ t: "Ayudar a Yunque a tapar la grieta", go: "tapar" },
                  { t: "Sacar a los jóvenes de ahí", go: "jovenes" },
                  { t: "Cantar la nana hacia el metal", go: "nana" }] },
      tapar: { say: [[null, "Corres con Yunque. Él mete la mano gris en la grieta, la de piedra, la que ya no siente. El metal no la quema. Tú empujas una losa contra la pared del canal."],
                     [null, "La grieta se cierra. El metal sigue hacia el molde. Yunque saca la mano. Ahora la piedra le llega hasta el codo."],
                     ["yunque", "No duele. Ya se lo dije. Solo pesa más."]], end: { xp: 18, hurt: 0.1, flag: "e4_yunqueCodo" } },
      jovenes: { say: [[null, "Empujas a los obreros jóvenes hacia atrás, a gritos. El metal pasa por donde estaban y se enfría en un charco rojo en el suelo."],
                       [null, "Yunque tapa la grieta solo, con la mano de piedra. Cuando termina, la mira como quien mira una herramienta que se rompió."],
                       ["yunque", "Bien hecho. Ellos todavía tienen manos de carne. Que les duren."]], end: { xp: 16, flag: "e4_jovenesSalvados" } },
      nana: { say: [[null, "No sabes por qué lo haces. Cantas. El metal que se sale por la grieta se pone más lento, más oscuro, como si escuchara."],
                    [null, "Yunque aprovecha y tapa la grieta. El resto del metal llega al molde sin apuro."],
                    ["yunque", "¿Qué fue eso? El metal se quedó quieto. Como un animal cuando le hablas bajito."],
                    [null, "Los obreros te miran raro el resto del día. Algunos tararean la nana en voz baja mientras trabajan."]], end: { xp: 18, flag: "e4_metalEscucha" } },
    } },

    "e4-chispa2": { kind: "encuentro", need: { era: 4, layer: 2, anyFlag: ["e4_chispaTizon", "e4_chispaMartillo", "e4_chispaSola"] }, who: { chispa: "Chispa" }, start: "a", nodes: {
      a: { say: [[null, "En la ladera sur, detrás de su casa, Chispa armó una forja con piedras del río y un fuelle hecho con una bolsa de cuero. Está martillando algo chiquito."],
                 ["chispa", "¡Cuidador! Mire. Es un clavo. Mi primer clavo. Está torcido, pero es un clavo."],
                 [null, "Te muestra la mano. La manchita gris de la punta del dedo creció. Ahora le cubre la uña entera."]],
           opts: [{ t: "«¿Con qué metal lo hiciste?»", go: "metal", once: true },
                  { t: "«Tizón te enseñó a forjar en frío.»", go: "frio", cNeed: "e4_chispaTizon" },
                  { t: "«Ese martillo te lo di yo.»", go: "martillo", cNeed: "e4_chispaMartillo" },
                  { t: "Llevarla a meter la mano en resina del Bosque", go: "resina" },
                  { t: "«Sigue. Lo estás haciendo bien.»", go: "sigue" }] },
      metal: { say: [["chispa", "Hierro del río, casi todo. Y un poquito de rojo. De un lingote que se cayó de una carreta. Un poquito nada más, para que agarre."],
                     ["chispa", "Con el poquito rojo el hierro se pone bueno. Se dobla y no se rompe. No le diga a nadie."]], back: "a" },
      frio: { say: [["chispa", "Sí. Es aburrido. Se tarda tres veces más. Pero el maestro dice que el que forja en frío tiene manos a los cien años. Como él."],
                    ["chispa", "Este clavo lo hice en frío. Sin nada rojo. Por eso está torcido. Pero es mío entero."]], back: "a" },
      martillo: { say: [["chispa", "¡Sí! Lo uso todos los días. Ya tiene una abolladura con la forma de mi mano."],
                        ["chispa", "Cuando sea grande, voy a hacerle uno a usted. Mejor que este."]], back: "a" },
      resina: { say: [[null, "La llevas al Bosque. Hacha le deja meter la mano en un balde de resina de un árbol viejo."],
                      [null, "Cuando la saca, la uña sigue gris. Pero la punta del dedo se dobla otra vez."],
                      ["chispa", "Se mueve. ¡Se mueve! Bueno. No voy a usar más rojo. Lo juro. Por lo menos hasta que sea grande."]], end: { xp: 16, flag: "e4_chispaResina" } },
      sigue: { say: [["chispa", "¿Sí? ¿De verdad?"],
                     [null, "Se pone a martillar más fuerte, feliz. La manchita gris brilla un poco con el fuego."],
                     [null, "Te vas. Desde la cuesta todavía se oye el martillo, chiquito, terco."]], end: { xp: 8, flag: "e4_chispaSigue" } },
    } },

    "e4-escoria": { kind: "dialogo", need: { era: 4, layer: 3, anyFlag: ["m4_huelga", "m4_recado", "m4_mediar"] }, who: { escoria: "Escoria, obrera" }, start: "a", nodes: {
      a: { say: [[null, "Escoria está sentada en la escalinata del Gremio, sola, con las manos en el regazo. Ya no grita. Tiene la voz ronca de tanto hacerlo."],
                 ["escoria", "¿Viene a ver cómo terminó? Siéntese."]],
           opts: [{ t: "«Los hornos hondos se cerraron por la huelga.»", go: "huelga", cNeed: "m4_huelga" },
                  { t: "«La mitad volvió a trabajar por la bolsa de Cobre.»", go: "recado", cNeed: "m4_recado" },
                  { t: "«Se firmó el trato de los turnos cortos.»", go: "mediar", cNeed: "m4_mediar" },
                  { t: "«¿Y sus manos?»", go: "manos" }] },
      huelga: { say: [["escoria", "Se cerraron una semana. Después el Gremio trajo gente de afuera, de la ladera sur, gente que no sabía. Ahora los chicos de la ladera tienen las manos grises, y nosotros no tenemos trabajo."],
                      ["escoria", "Ganamos. Así se gana: le pasas el problema a otro más pobre."]], back: "a" },
      recado: { say: [["escoria", "La mitad. Ahora la mitad tiene una bolsa y las manos grises. La otra mitad, nada. Y me odian los dos lados: unos por no haber agarrado la bolsa, otros por haberles hecho sentir que estaba mal agarrarla."],
                      ["escoria", "Cobre me mandó una carta pidiendo perdón. La usé para prender el fuego."]], back: "a" },
      mediar: { say: [["escoria", "Turnos de una hora. Funciona. Las manos se ponen grises más despacio. Más despacio no es nunca."],
                      ["escoria", "Pero mire: la semana pasada alguien rompió la mano de un capataz porque lo hizo quedarse dos horas. Antes no se rompía nada. Ahora hay un papel que romper."]], back: "a" },
      manos: { say: [[null, "Escoria levanta las manos. Las tiene grises hasta la muñeca. Los dedos se doblan, pero despacio, como si pensaran antes de moverse."],
                     ["escoria", "Todavía. Pero no por mucho. Quiero que cuando ya no las mueva, alguien se acuerde de por qué. No quiero una estatua. Quiero que se acuerden."]],
               opts: [{ t: "«Yo me voy a acordar.»", go: "acordar" },
                      { t: "«Escríbalo. Que lo guarde la Hondura en piedra.»", go: "escribir" },
                      { t: "«Vaya al Corazón. Que lo vean los nueve pueblos.»", go: "corazon" }] },
      acordar: { say: [["escoria", "Usted. Bueno. Usted se acuerda de cosas de hace sesenta años. Eso dicen."],
                       [null, "Te toma la mano con la suya, dura y tibia. No aprieta. No puede apretar mucho."]], end: { xp: 14 } },
      escribir: { say: [[null, "Escoria dicta. Tú escribes. Los nombres de los obreros de manos grises, los turnos, las horas, lo que pasó con la huelga."],
                        [null, "Galena lo lleva a las Cuevas y lo graba en una pared nueva, lejos de las otras. Una pared de manos."],
                        ["escoria", "Ahí. En la piedra. Que es lo que nos va a pasar a todos. Por lo menos que diga quiénes fuimos."]], end: { xp: 18, flag: "e4_paredManos" } },
      corazon: { say: [["escoria", "¿Al Corazón? ¿A pedir?"],
                       [null, "Se queda mirando sus manos un rato largo."],
                       ["escoria", "No a pedir. A mostrar. Si los nueve pueblos se juntan, el Barrio va a ir con estas manos levantadas. Que nadie diga que no sabía."]], end: { xp: 16, flag: ["e4_manosCorazon", "u4_barrio"] } },
    } },

    "e4-tizon": { kind: "dialogo", need: { era: 4, layer: 3 }, who: { tizon: "Maese Tizón" }, start: "a", nodes: {
      a: { say: [[null, "Maese Tizón está en la cama. Tiene una pila de monedas sobre la manta, ordenadas por tamaño. Respira despacio, con un silbido. Al verte, sonríe con la mitad de la boca."],
                 ["tizon", "Viniste. Bien. Me estoy muriendo. No pongas esa cara: tengo ciento doce años y conté estas monedas dos veces cada día de mi vida. Ya era hora."],
                 ["tizon", "No sé a quién dejárselas. Al Gremio, que fue mi vida. O a alguien que no sea del Gremio. Decide tú. Yo ya decidí demasiado."]],
           opts: [{ t: "«¿Por qué las contaba dos veces?»", go: "dos", once: true },
                  { t: "«Déjeselas al Gremio.»", go: "gremio" },
                  { t: "«Déjeselas a Chispa.»", go: "chispa", cNeed: "e4_chispaTizon" },
                  { t: "«Déjeselas a los obreros de manos grises.»", go: "obreros" }] },
      dos: { say: [["tizon", "Porque la primera vez cuentas lo que tienes. La segunda, lo que te costó tenerlo."],
                   ["tizon", "Nunca me dio lo mismo. Ni una vez en cien años."]], back: "a" },
      gremio: { say: [["tizon", "El Gremio. Sí. Que me sobreviva. Es lo único que quise."],
                      [null, "Cierra los ojos. Fogarín llega esa noche y se queda sentado al lado de la cama hasta la mañana. No cuenta las monedas."]], end: { xp: 12, flag: "e4_tizonGremio" } },
      chispa: { say: [["tizon", "La chica de la ladera. Sí. La que forja en frío porque se lo pedí."],
                      [null, "Te da las monedas envueltas en un trapo. Pesan más de lo que parece."],
                      ["tizon", "Dile que no las cuente. O que las cuente una vez. Que no aprenda mi costumbre. Que aprenda la otra."],
                      [null, "Muere al amanecer. Chispa recibe el trapo y llora sin abrirlo durante una hora."]], end: { xp: 20, flag: "e4_tizonChispa" } },
      obreros: { say: [[null, "Tizón te mira mucho rato. Después asiente, despacio."],
                       ["tizon", "Toda la vida les pagué lo justo. Lo justo según yo. Que se lo queden. Para resina, para comida, para lo que les falte cuando ya no puedan cerrar el puño."],
                       [null, "Muere esa noche. Las monedas se reparten en el patio del Gremio, una por obrero. Escoria cuenta la suya dos veces y se ríe, llorando."]], end: { xp: 18, flag: "e4_tizonObreros" } },
    } },
  });

  /* ---------- Bosque Hondo: el Concejo, el claro, el último árbol viejo y el incendio ---------- */
  add("forest", {
    "e4-musgo": { kind: "dialogo", need: { era: 4, layer: 1 }, who: { musgo: "Musgo, del Concejo" }, start: "a", nodes: {
      a: { say: [[null, "En la casa del Concejo, siete viejos discuten si se puede discutir. Un hombre de barba verdosa preside desde una silla de raíces. Cada tanto alguien dice «no» y todos asienten."],
                 ["musgo", "El Concejo prohibió la tala. Hace un año. Los leñadores siguen talando. El Concejo prohibió vender leña al Gremio. Siguen vendiendo. El Concejo prohibió que se hable de esto. Y aquí estamos."],
                 ["musgo", "Sabemos decir que no. Es lo único que sabemos. No sabemos qué hacer cuando nadie escucha el no."]],
           opts: [{ t: "«Dejen de prohibir y paguen por cuidar.»", go: "pagar" },
                  { t: "«Hablen con Hacha. Ella planta tres por uno.»", go: "hacha", cNeed: "e4_tresPorUno" },
                  { t: "«Prohíban más fuerte. Pongan guardias.»", go: "guardias" },
                  { t: "«¿Qué decía el Concejo antes de saber decir que no?»", go: "antes" }] },
      pagar: { say: [["musgo", "¿Pagar? El Concejo no tiene monedas. Tiene musgo, hongos y años."],
                     [null, "Uno de los viejos levanta la mano. Dice que tienen semillas. Las más viejas del Claro. Que valen más que la leña, si alguien sabe usarlas."],
                     ["musgo", "Semillas por árboles no cortados. Es una idea. Es una idea rara. No es un no. Hace mucho que el Concejo no tenía una idea que no fuera un no."]], end: { xp: 16, flag: "e4_semillasPago" } },
      hacha: { say: [["musgo", "¿La leñadora? ¿La que corta?"],
                     [null, "Le cuentas lo de los tres por uno. Los siete viejos se miran."],
                     ["musgo", "Entonces la que corta cuida más que el Concejo. Eso no me gusta. Pero es verdad. Que venga Hacha a la próxima sesión. Con su hacha, si quiere. El Bosque va a ir al Corazón con la que corta y con la que no."]], end: { xp: 20, flag: ["e4_concejoHacha", "u4_planta"] } },
      guardias: { say: [[null, "El Concejo manda a doce jóvenes con palos a vigilar los árboles viejos. A la semana, seis se pasaron a los leñadores. El Gremio les paga más."],
                        ["musgo", "Ya ve. Un no con palo es un no que se puede comprar."]], end: { xp: 8, flag: "e4_guardiasComprados" } },
      antes: { say: [["musgo", "Antes de saber decir que no... decía «espera». Eso dicen los registros. «Espera a que crezca.» «Espera a ver.»"],
                     ["musgo", "Creo que a algún Concejo viejo le cansó esperar, y aprendió el no. Más rápido. Peor."]], back: "a" },
    } },

    "e4-claro": { kind: "encuentro", need: { era: 4, layer: 1 }, who: {}, start: "a", nodes: {
      a: { say: [[null, "Donde antes había un bosque cerrado, ahora hay un claro enorme lleno de tocones. El sol entra de golpe. Hace calor. El musgo de las piedras se secó y se cae a pedazos."],
                 [null, "No se oyen pájaros. Las criaturas del Bosque se fueron más adentro, donde todavía hay sombra. Tu criatura se pega a tus piernas, con los ojos entrecerrados por la luz."],
                 [null, "En el borde del claro, una criatura chiquita del Bosque, sola, da vueltas alrededor de un tocón. Busca algo que ya no está."]],
           opts: [{ t: "Acercarte a la criatura del tocón", go: "criatura" },
                  { t: "Plantar algo en el claro", go: "plantar" },
                  { t: "Seguir de largo hacia la sombra", go: "seguir" }] },
      criatura: { say: [[null, "Te agachas. La criatura te mira y no huye. En el tocón hay un hueco, y en el hueco, restos de un nido."],
                        [null, "Tu criatura se acerca despacio y le toca la nariz con la suya. Las dos se quedan quietas un rato."],
                        [null, "Al final la criatura chiquita te sigue hasta la sombra, a unos pasos, sin acercarse más. Esa noche duerme cerca del fuego del campamento."]], end: { xp: 14, heal: 0.1, flag: "e4_criaturaClaro" } },
      plantar: { say: [[null, "Con las manos haces un hoyo en la tierra seca y entierras una semilla que llevabas en el bolsillo desde hace quién sabe cuándo. La riegas con el agua de tu cantimplora."],
                       [null, "No va a crecer. Hace demasiado calor, el suelo está lleno de ceniza. Lo sabes. La plantas igual."],
                       [null, "Tu criatura se sienta al lado del hoyo. Cuando te vas, se queda un rato más, como si esperara algo."]], end: { xp: 10, flag: "e4_semillaClaro" } },
      seguir: { say: [[null, "Cruzas el claro rápido, sin mirar. En la sombra del otro lado el aire es fresco, y huele a hojas. Se oye un pájaro, lejos."],
                      [null, "Atrás, el claro brilla como un plato vacío."]], end: { xp: 6 } },
    } },

    "e4-carboneros": { kind: "encuentro", need: { era: 4, layer: 2 }, who: { hacha: "Hacha, leñadora", hulla: "Hulla, carbonera de la Corte" }, start: "a", nodes: {
      a: { say: [[null, "En el límite entre el Bosque y la Hondonada, dos grupos se miran con odio. De un lado, leñadores con hachas. Del otro, gente de la Corte con velos y palas negras."],
                 ["hacha", "La Corte vende carbón al Gremio más barato que nuestra leña. Si siguen, nos quedamos sin trabajo. Y el Bosque se tala igual, porque la Corte también corta: corta aquí, de noche, y lo quema en la Hondonada."],
                 ["hulla", "Cortamos lo que ustedes dejan tirado. Ramas, tocones. Los árboles enteros los cortan ustedes. No vengan a decir que el Bosque es suyo porque lo matan primero."]],
           opts: [{ t: "«¿Por qué pelean entre ustedes y no con el Gremio?»", go: "gremio", once: true },
                  { t: "Proponer que trabajen juntos: leña y carbón, un solo precio", go: "juntos" },
                  { t: "Ponerte del lado de Hacha", go: "hacha" },
                  { t: "Ponerte del lado de Hulla", go: "hulla" }] },
      gremio: { say: [["hacha", "Porque al Gremio no se le puede pegar. Está lejos, tiene hornos, paga."],
                      ["hulla", "Y entre nosotros sí. Siempre es más fácil pelear con el que está tan fregado como uno."],
                      [null, "Se miran. Por un momento, casi se ríen."]], back: "a" },
      juntos: { say: [[null, "Les propones un trato: un solo precio para la leña y el carbón, que lo pague el Gremio igual a los dos. Y que ninguno corte árboles vivos de más de cien años."],
                      ["hacha", "¿Con la Corte? Mi abuela se levantaría de la tumba."],
                      ["hulla", "La mía también. A lo mejor se encuentran por el camino y se ponen de acuerdo."],
                      [null, "Firman con tierra en los dedos, en una piedra. Al Gremio le llega el precio al día siguiente. Fogarín lo acepta sin regatear. Dice que ya era hora de que alguien se pusiera de acuerdo en algo."]], end: { xp: 20, flag: "e4_leniaCarbon" } },
      hacha: { say: [[null, "Te pones del lado de los leñadores. La Corte retrocede, despacio, hacia la Hondonada."],
                     ["hulla", "Bien. Ya sabemos de qué lado está el Vado. Siempre del lado del que tiene más gente."],
                     [null, "Esa noche desaparecen tres hachas del campamento de Hacha. Nadie vio nada."]], end: { xp: 8, flag: "e4_ladoHacha" } },
      hulla: { say: [[null, "Te pones del lado de la Corte. Los leñadores te miran con rabia."],
                     ["hacha", "La Corte. Claro. La que siempre tiene una excusa. Disfruten el carbón."],
                     [null, "Al día siguiente el Gremio deja de comprar leña. Compra solo carbón. Doce familias de leñadores se quedan sin ingreso ese mes."]], end: { xp: 8, flag: "e4_ladoHulla" } },
    } },

    "e4-retono": { kind: "dialogo", need: { era: 4, layer: 2 }, who: { retono: "Retoño, del Concejo" }, start: "a", nodes: {
      a: { say: [[null, "En la orilla del lago del Bosque, un hombre de pelo gris y boca sin manchas está sentado en una silla chica que alguien sacó de la casa del Concejo. Mira los tocones de la otra orilla."],
                 ["retono", "Cuidador. Soy Retoño. Pasaron años. Yo era el muchacho de la boca morada, ¿se acuerda? Ahora la boca está limpia y el Bosque está cortado. No sé qué es peor."],
                 ["retono", "Los jóvenes del Bosque ya no van al lago a beber visiones. Van al Cráter a trabajar. Vuelven con las manos grises. Siempre hay algo que los jóvenes van a buscar afuera y les cuesta algo."]],
           opts: [{ t: "«Usted habla en el Concejo por los jóvenes.»", go: "concejo", cNeed: "end_retono_A" },
                  { t: "«Usted se quedó en la orilla contando a los que volvían.»", go: "orilla", cNeed: "end_retono_B" },
                  { t: "«Usted bajaba a la orilla con los viejos del Concejo.»", go: "viejos", cNeed: "end_retono_C" },
                  { t: "«¿Qué hace falta para que se queden?»", go: "quedar" },
                  { t: "«Vaya al Cráter y tráigalos.»", go: "traer" }] },
      concejo: { say: [["retono", "Hablo. Lo segundo que iba a pedir nunca lo dije. Ya no me acuerdo qué era. Creo que era «que se pueda volver»."],
                       ["retono", "Ahora lo pediría. Que se pueda volver del Cráter con las manos enteras."]], back: "a" },
      orilla: { say: [["retono", "Los contaba. Ahora cuento a los que vuelven del Cráter. Son más los que vuelven. Pero vuelven distintos."],
                      ["retono", "La silla chica sigue vacía en el Concejo. La saqué para mirar el agua. Nadie la reclamó."]], back: "a" },
      viejos: { say: [["retono", "Bajábamos. Hablábamos hasta que salía el sol. Ahora los viejos de entonces están muertos y los viejos de ahora somos nosotros."],
                      ["retono", "Mañana bajo con los jóvenes del Cráter. A ver si hablando se arregla algo. Antes no se arregló nada. Pero nos conocimos."]], back: "a" },
      quedar: { say: [["retono", "Trabajo. Algo que pague y que no te vuelva de piedra ni te quite recuerdos. El Bosque nunca pagó por cuidarlo. Ese es el problema de siempre."],
                      ["retono", "Si el Concejo pagara con semillas, con tierra, con algo... Los jóvenes no quieren monedas. Quieren algo suyo."]], back: "a" },
      traer: { say: [[null, "Retoño se levanta de la silla chica despacio. Se va al Cráter esa misma tarde, a pie."],
                     [null, "Vuelve a la semana con ocho jóvenes del Bosque. Tienen las uñas grises. Uno, la mano entera."],
                     ["retono", "Ocho de cuarenta. Los otros dijeron que no. Que el Gremio paga y el Bosque no. Tienen razón. Pero estos ocho van a plantar los tres por uno. Algo es."]], end: { xp: 18, flag: "e4_retonoTrae" } },
    } },

    "e4-semillas": { kind: "encuentro", need: { era: 4, layer: 2, anyFlag: ["e4_tresPorUno", "e4_semillasPago", "e4_resinaGremio"] }, who: { hacha: "Hacha, leñadora" }, start: "a", nodes: {
      a: { say: [[null, "En el claro de los tocones hay filas de brotes plantados. Son cientos, con palitos al lado para que no se caigan. La mitad están amarillos. Algunos, negros en la punta."],
                 ["hacha", "La tierra está llena de ceniza de los hornos. Y caliente desde abajo. Los brotes no aguantan. Plantamos tres por uno y se mueren dos."],
                 ["hacha", "Un árbol viejo tarda trescientos años. Un brote muere en un mes. Las cuentas no dan, Cuidador. Nunca dieron."]],
           opts: [{ t: "«¿Por qué está caliente la tierra?»", go: "caliente", once: true },
                  { t: "Regar con el agua fría del Fondo", go: "fria", cNeed: "e4_frioGuardado" },
                  { t: "Plantar en la sombra, más adentro", go: "sombra" },
                  { t: "«Planten igual. Que alguno aguante.»", go: "igual" }] },
      caliente: { say: [["hacha", "Las vetas. Los mineros dicen que hay vetas rojas que pasan por debajo del Bosque, hacia el Corazón. Calientan todo desde abajo."],
                        ["hacha", "El Bosque se está cocinando de abajo hacia arriba. Y nosotros plantando arriba."]], back: "a" },
      fria: { say: [[null, "Témpano manda dos barriles del agua fría del deshielo. Riegan una fila entera de brotes."],
                    [null, "A la semana, esa fila está verde. Las otras, no."],
                    ["hacha", "El frío del Fondo salva al Bosque. Pero solo una fila. Y el agua fría no vuelve. Eso es lo que hay, siempre: alcanza para una fila."]], end: { xp: 18, flag: "e4_filaVerde" } },
      sombra: { say: [[null, "Trasplantan los brotes que quedan más adentro, a la sombra de los árboles que todavía están en pie. Tarda días."],
                      ["hacha", "Ahí aguantan más. Pero ahí los árboles viejos les quitan la luz. Como siempre. Los viejos no dejan crecer a los nuevos, y si los cortas, los nuevos se cocinan."]], end: { xp: 14, flag: "e4_brotesSombra" } },
      igual: { say: [["hacha", "Plantar igual. Sí. Es lo que hacía mi abuela. Plantaba aunque supiera."],
                     [null, "Siguen plantando. Al final de la estación, de cien brotes quedan once. Hacha los cuenta como quien cuenta hijos."]], end: { xp: 10 } },
    } },

    "e4-arbolviejo": { kind: "dialogo", need: { era: 4, layer: 3 }, who: { hacha: "Hacha, leñadora", musgo: "Musgo, del Concejo", escoria: "Escoria, obrera" }, start: "a", nodes: {
      a: { say: [[null, "En el centro del Bosque queda un árbol enorme, el más viejo, el que el Concejo llama la Madre. Alrededor hay tres personas que no se hablan."],
                 ["escoria", "Su resina sola alcanza para cien obreros durante un año. Cien pares de manos que se vuelven a doblar."],
                 ["hacha", "Su madera alcanza para que el Gremio deje de comprar leña tres inviernos. Doce familias comen tres años."],
                 ["musgo", "Y es la Madre. Las semillas de todo el Bosque vienen de ella. Si la cortan, el Bosque no vuelve. Nunca."]],
           opts: [{ t: "«¿No hay otra forma de sacarle resina?»", go: "otra", once: true },
                  { t: "«Córtenla. Las manos primero.»", go: "cortar" },
                  { t: "«Sangrarla de a poco, sin cortarla.»", go: "sangrar" },
                  { t: "«Nadie la toca.»", go: "nadie" }] },
      otra: { say: [["musgo", "Sangrarla. Hacerle cortes chicos en la corteza y juntar lo que gotea. Tarda años. La debilita. Pero vive."],
                    ["escoria", "Años. Mis manos no tienen años."]], back: "a" },
      cortar: { say: [[null, "Tarda dos días cortarla. Cae con un ruido que se oye hasta en el Prado. El Bosque queda en silencio."],
                      [null, "La resina va en barriles al Cráter. Cien obreros meten las manos. Las sacan blandas. Escoria llora delante de todos."],
                      ["musgo", "Ya está. La Madre cura manos. Que se acuerden de eso cuando el Bosque no vuelva."]], end: { xp: 14, flag: "e4_madreCortada" } },
      sangrar: { say: [[null, "Le hacen doce cortes chicos en la corteza, como venas abiertas. La resina gotea despacio en baldes. Un balde por luna."],
                       ["escoria", "Un balde por luna. Doce manos por luna. Bueno. Doce es más que ninguna."],
                       ["hacha", "Y la Madre sigue en pie. Herida, pero en pie. Como todos aquí."]], end: { xp: 18, flag: "e4_madreSangra" } },
      nadie: { say: [["escoria", "¿Nadie? ¿Usted me va a mirar las manos cuando no se muevan más y me va a decir que valió la pena por un árbol?"],
                     [null, "No tienes respuesta que le sirva. Musgo pone la mano en la corteza de la Madre."],
                     ["musgo", "Gracias. El Bosque no lo va a olvidar. Escoria tampoco. Las dos cosas son verdad."]], end: { xp: 10, flag: "e4_madreIntacta" } },
    } },

    "e4-incendio": { kind: "encuentro", need: { era: 4, layer: 3 }, who: { hacha: "Hacha, leñadora" }, start: "a", nodes: {
      a: { say: [[null, "Al atardecer sube humo del borde del Bosque, donde pasa el camino de las carretas del metal. Un lingote cayó de una carreta y prendió la hojarasca seca. El fuego avanza hacia los brotes nuevos."],
                 ["hacha", "¡Agua! ¡Tierra! ¡Lo que sea!"],
                 [null, "Los leñadores corren con baldes. No alcanzan. El fuego es rojo, demasiado rojo, y no se apaga con agua: el lingote del medio sigue ardiendo."]],
           opts: [{ t: "Abrir una zanja para cortar el fuego", go: "zanja" },
                  { t: "Sacar el lingote del medio del fuego", go: "lingote" },
                  { t: "Salvar los brotes, aunque se queme el resto", go: "brotes" }] },
      zanja: { say: [[null, "Cavas con los leñadores una zanja ancha entre el fuego y el Bosque viejo. Tardan toda la noche. El fuego llega a la zanja y se detiene."],
                     [null, "Del otro lado quedó todo negro: los brotes, los tocones, el camino. El Bosque viejo, del lado de acá, intacto."],
                     ["hacha", "Salvamos lo viejo. Se quemó lo nuevo. Siempre es así cuando hay que elegir rápido."]], end: { xp: 16, flag: "e4_zanja" } },
      lingote: { say: [[null, "Te tapas con una manta mojada y entras. El calor es tan fuerte que no se puede respirar. Tomas el lingote con dos ramas verdes y lo arrastras hasta el arroyo."],
                       [null, "Cuando cae al agua, el arroyo hierve y suelta un vapor rojo. Sin el lingote, el fuego se debilita. Los baldes alcanzan."],
                       ["hacha", "¿Perdió la cabeza? Bueno. Gracias. Mírese las manos."],
                       [null, "Tienes las palmas rojas. Y en una, una manchita gris del tamaño de una lenteja."]], end: { xp: 22, hurt: 0.2, flag: "e4_manchaPropia" } },
      brotes: { say: [[null, "Corres hacia los brotes con los leñadores más jóvenes. Arrancan los que pueden, con tierra y todo, y los llevan hacia el arroyo en los brazos."],
                      [null, "Salvan cuarenta. El resto del claro se quema. El fuego llega hasta el borde del Bosque viejo y quema tres árboles antes de que lo paren."],
                      ["hacha", "Cuarenta brotes por tres árboles viejos. No sé si es un buen cambio. Pero los brotes los elegimos nosotros."]], end: { xp: 16, flag: "e4_brotesSalvados" } },
    } },
  });

  /* ==================== Entrega 3: la Noche (Hondonada Umbría, Lago Espejo, Cuevas del Eco) ==================== */

  /* ---------- Hondonada Umbría: los hornos de carbón, la tumba del rey, la Reina y los velos ---------- */
  add("hollow", {
    "e4-hornos": { kind: "encuentro", need: { era: 4, layer: 1 }, who: { hulla: "Hulla, carbonera de la Corte" }, start: "a", nodes: {
      a: { say: [[null, "Bajo la Hondonada hay galerías que antes eran bodegas de visiones. Ahora son hornos: montañas de leña tapadas con tierra, ardiendo despacio, sin llama. El aire es espeso y dulce. Cuesta respirar."],
                 [null, "Una fila de carboneros con velo sale de una galería, tosiendo. Uno se cae de rodillas. Los demás lo levantan sin dejar de toser."],
                 ["hulla", "El carbón de sombra no echa humo afuera. Lo echa adentro. Se queda en las galerías, en los pulmones. Por eso no se ve desde arriba. Por eso lo compran."]],
           opts: [{ t: "«¿Cuánto aguanta un carbonero aquí?»", go: "cuanto", once: true },
                  { t: "Cavar chimeneas, aunque el humo se vea desde arriba", go: "chimeneas" },
                  { t: "Traer musgo del Bosque para filtrar el aire", go: "musgo" },
                  { t: "Apagar el horno más hondo", go: "apagar" }] },
      cuanto: { say: [["hulla", "Diez años, si empieza joven. Después tose hasta que se le olvida respirar."],
                      ["hulla", "Las manos del Cráter se ven. Los pulmones de la Hondonada, no. Por eso nadie hace huelga aquí."]], back: "a" },
      chimeneas: { say: [[null, "Cavas con los carboneros tres chimeneas angostas hasta la superficie. Tarda una semana. El humo sale por fin, gris, y se queda colgado sobre la Hondonada como un techo."],
                         [null, "Desde el Prado se ve. Al día siguiente, las Casas preguntan. Al otro, todo el Claro sabe quién calienta la Campana."],
                         ["hulla", "Respiramos. Y nos miran. Las dos cosas a la vez. Supongo que no se puede una sin la otra."]], end: { xp: 18, flag: "e4_chimeneas" } },
      musgo: { say: [[null, "Traes del Bosque sacos de musgo húmedo. Los carboneros se lo atan sobre la boca, debajo del velo. Huele a tierra mojada."],
                     ["hulla", "Funciona. Toso menos. Los leñadores nos cobran el musgo, claro. Todo se cobra. Pero lo cobran barato."],
                     [null, "Por primera vez en años, alguien de la Corte y alguien del Bosque hacen un trato sin pelear."]], end: { xp: 16, flag: "e4_mascarasMusgo" } },
      apagar: { say: [[null, "Echas agua sobre el horno más hondo hasta que la tierra deja de humear. Sale un vapor negro que te hace llorar los ojos."],
                      ["hulla", "Ese horno daba el carbón de un mes. El Gremio va a pagar menos. Algunos van a comer menos."],
                      ["hulla", "Pero el que trabajaba ahí era mi sobrino. Así que gracias. Y no vuelva a hacerlo sin preguntar."]], end: { xp: 12, flag: "e4_hornoApagado" } },
    } },

    "e4-tumba": { kind: "encuentro", need: { era: 4, layer: 1 }, who: { onix: "Ónix, guarda de las tumbas" }, start: "a", nodes: {
      a: { say: [[null, "En el cementerio de la Corte, entre lápidas negras, un guarda joven barre las hojas con una escoba de ramas. Se detiene frente a una tumba más grande que las otras, con una corona tallada y la piedra gastada."],
                 ["onix", "Me llamo Ónix. Cuido a los muertos de la Corte. Este es el rey Lóbrego. Murió hace sesenta años. Usted lo conoció, dicen."],
                 ["onix", "Los chicos vienen de noche a escribirle cosas. Yo las borro de día. No sé bien por qué. Me pagan para borrar."]],
           opts: [{ t: "«¿Qué dice la tumba?»", go: "dice", once: true },
                  { t: "«Él dijo en el Juicio que no preguntó.»", go: "nopregunto", cNeed: "end_e3lobrego_A" },
                  { t: "«Él dejaba la puerta del Trono abierta.»", go: "puerta", cNeed: "end_e3lobrego_B" },
                  { t: "«Su copa sigue sin tocar en la bodega.»", go: "copa", cNeed: "end_e3lobrego_C" },
                  { t: "«No borre lo que escriben.»", go: "noborrar" }] },
      dice: { say: [["onix", "«Rey». Nada más. Y abajo, lo que escriben los chicos. Anoche escribieron: «Vendió la noche y compró carbón»."],
                    ["onix", "No es verdad. El carbón es de ahora. Pero los chicos mezclan a los muertos. Para ellos todos los reyes son el mismo."]], back: "a" },
      nopregunto: { say: [["onix", "Sí. «Que no preguntó». Eso está grabado. Alguien lo grabó con un clavo, hondo, hace mucho. No se puede borrar."],
                          ["onix", "A veces pienso que la Corte entera debería tener eso en la puerta. Que no pregunta. Que nunca pregunta de dónde viene lo que vende."]], back: "a" },
      puerta: { say: [["onix", "La puerta del Trono sigue abierta. Nadie la cerró cuando murió. La Reina Merma entra y sale por ahí todos los días."],
                      ["onix", "Nadie le pregunta nada a ella. La puerta abierta no sirve si nadie entra a preguntar."]], back: "a" },
      copa: { say: [["onix", "La copa. Sí. La bodega la cuido yo también. Tiene polvo de sesenta años. Nadie se anima a tirarla ni a beberla."],
                    ["onix", "A veces la miro y pienso que adentro está todo lo que el rey no quiso saber. Y que la Corte sigue sin querer."]], back: "a" },
      noborrar: { say: [["onix", "¿Y si me echan?"],
                        [null, "Mira la tumba. Mira la escoba."],
                        ["onix", "Bueno. Dejo una. La que diga algo verdadero. Las mentiras las borro, las verdades las dejo. Así por lo menos borrar sirve para algo."],
                        [null, "Esa noche, alguien escribe en la piedra: «La Corte calienta la Campana». Ónix no la borra."]], end: { xp: 16, flag: "e4_tumbaEscrita" } },
    } },

    "e4-bruna": { kind: "dialogo", need: { era: 4, layer: 2 }, who: { bruna: "Doña Bruna" }, start: "a", nodes: {
      a: { say: [[null, "En una casa baja de la Hondonada, una anciana teje sentada junto a una lámpara. No mira el tejido. Mira las sombras que la lámpara hace en la pared."],
                 ["bruna", "Cuidador. Soy Bruna, ¿se acuerda? La niña de la sombra. Ahora soy la vieja de la sombra. Pase."],
                 ["bruna", "Mire las sombras de los carboneros cuando pasan por la puerta. Están duras. No se doblan cuando ellos se doblan. Como si fueran de piedra. Yo de sombras sé."]],
           opts: [{ t: "«Usted camina con una sombra de niebla.»", go: "niebla", cNeed: "end_bruna_A" },
                  { t: "«Usted le cantaba la nana al sol.»", go: "sol", cNeed: "end_bruna_B" },
                  { t: "«Usted ya no busca su sombra.»", go: "sinsombra", cNeed: "end_bruna_C" },
                  { t: "«¿Qué les pasa a las sombras?»", go: "pasa" },
                  { t: "«Enséñeles a cuidar su sombra.»", go: "ensenar" }] },
      niebla: { say: [["bruna", "La de Calina. Todavía la tengo. Está gastada, con agujeros, como una manta vieja. Calina murió hace mucho. La sombra no."],
                      ["bruna", "Con esta sombra veo las otras. Por eso sé que están duras. Las sombras que se tejen saben cuándo otra está enferma."]], back: "a" },
      sol: { say: [["bruna", "Todos los días. Sesenta años. Lo pálido que me seguía sigue ahí. Más pálido. Ya casi no se ve."],
                   ["bruna", "Pero ahora también sigue a los carboneros, cuando les canto. Un poco. Como si les prestara algo."]], back: "a" },
      sinsombra: { say: [["bruna", "No la busco. Pero veo las de los demás. Cuando no tienes, miras mucho las que tienen los otros."],
                         ["bruna", "Y las de los carboneros se están poniendo como la mía antes de irse. Quietas. Primero se ponen quietas."]], back: "a" },
      pasa: { say: [["bruna", "El humo del carbón de sombra está hecho de sombra quemada. Cuando lo respiras, se te mete la sombra de los árboles adentro. Y la tuya se pone dura para hacerle lugar."],
                    ["bruna", "Lo mismo que las manos del Cráter. El metal entra, la carne se hace piedra. Aquí el humo entra, la sombra se hace piedra. Siempre es lo mismo, pero en otro lugar del cuerpo."]], back: "a" },
      ensenar: { say: [[null, "Bruna junta a diez carboneros jóvenes en su casa. Les enseña a mover las manos delante de la lámpara, despacio, mirando la sombra, hasta que la sombra se dobla de nuevo."],
                       ["bruna", "Es un juego de niños. Mi madre me lo enseñaba. Pero si la sombra se vuelve a doblar, todavía se puede."],
                       [null, "Al final de la noche, tres de los diez tienen la sombra blanda otra vez. Los otros siete, no. Bruna se los anota en un papel."],
                       ["bruna", "Voy a ir al Corazón con este papel y con mi sombra. Que la Hondonada no vaya solo con carbón."]], end: { xp: 20, flag: ["e4_brunaSombras", "u4_sombra"] } },
    } },

    "e4-reina": { kind: "dialogo", need: { era: 4, layer: 2 }, who: { merma: "Reina Merma" }, start: "a", nodes: {
      a: { say: [[null, "En el Trono de la Hondonada, una mujer de mediana edad, sin corona, firma papeles uno tras otro. Tiene tinta en los dedos y ojeras de muchas noches. Detrás de ella, la puerta del Trono está abierta."],
                 ["merma", "Cuidador. Soy Merma. Reina, dicen. Contadora, más bien. La Corte tiene más deudas que velos."],
                 ["merma", "Vendo carbón al Gremio, compro noches en el tablero y con esas noches la tierra se abre debajo de la Torre del Alba. ¿Sabe por qué? Porque debajo de la Torre hay más metal que en todo el Cráter. Y es la primera vez en mil años que la Corte puede tener algo que las Casas no."]],
           opts: [{ t: "«Por su noche se cayó una casa del Barrio.»", go: "casa", cNeed: "e4_hundimientoVisto" },
                  { t: "«Una de sus guardias le dio una moneda a la familia.»", go: "moneda", cNeed: "e4_corteMoneda" },
                  { t: "«¿Y si la Torre se cae?»", go: "torre", once: true },
                  { t: "«Venda el metal, pero que no se abra la tierra donde vive gente.»", go: "acuerdo" },
                  { t: "«Si no para, le cuento a todo el Claro.»", go: "contar" }] },
      casa: { say: [["merma", "Lo sé. La tierra no se abrió donde la pedimos. Se abrió donde quiso."],
                    [null, "Deja la pluma. Por primera vez te mira de frente."],
                    ["merma", "Pagué la casa. Doble. La familia no quiso las monedas. Las dejaron en la puerta del Trono. Siguen ahí, en el suelo. Las piso cada mañana."]], back: "a" },
      moneda: { say: [["merma", "Sí. Tiniebla se llama. La castigué por darla sin permiso. Después le subí el sueldo, sin decírselo a nadie."],
                      ["merma", "Así se gobierna aquí: castigas lo que está bien en público, y lo premias en secreto. No me pida que le guste."]], back: "a" },
      torre: { say: [["merma", "Entonces las Casas pierden su Torre. Y la Corte, por una vez, no tiene la culpa: fue la tierra."],
                     ["merma", "Eso es lo que me dice la parte de mí que es Reina. La otra parte, la que cuenta, sabe que la Torre tiene trescientas personas adentro."]], back: "a" },
      acuerdo: { say: [["merma", "¿Elegir dónde se abre? Nadie sabe elegir dónde se abre."],
                       [null, "Le hablas de las vetas de Galena, del mapa, de que van todas hacia el Corazón. Merma escucha con la cabeza inclinada, como quien suma."],
                       ["merma", "Entonces no compro noches para la Torre. Compro noches para las tierras vacías del norte, donde pasan las vetas. Menos metal. Nadie debajo."],
                       ["merma", "La Corte va a ser un poco más pobre. Y un poco menos odiada. No sé cuál de las dos me cuesta más."]], end: { xp: 20, flag: "e4_reinaNorte" } },
      contar: { say: [["merma", "Cuénteles. Le van a creer. Usted tiene sesenta años de buena fama, yo tengo mil años de mala."],
                      [null, "Se levanta, despacio, y te acompaña hasta la puerta abierta."],
                      ["merma", "Pero antes de contarlo, pregúntese quién compra la tierra si la Corte no la compra. Mañana el Claro me odia un poco más. Y pasado, las Casas cavan debajo de la Hondonada."]], end: { xp: 12, flag: "e4_reinaExpuesta" } },
    } },

    "e4-lista": { kind: "dialogo", need: { era: 4, layer: 2, anyFlag: ["e4_nombreYunque", "e4_nombreVisto", "e4_nombreGuardado"] }, who: { ebano: "Ébano, archivero de la Corte" }, start: "a", nodes: {
      a: { say: [[null, "Ébano te espera en el archivo con la lámpara baja. Sobre la mesa hay otro pergamino, más largo que el primero, desenrollado con pesas en las puntas."],
                 ["ebano", "Encontré la segunda hoja. La lista no terminaba en el nombre tachado. Sigue. Son cuarenta y un nombres más. Los obreros de las primeras forjas."],
                 ["ebano", "Al lado de cada nombre hay una marca. Una mano chiquita, dibujada. Algunas manos están rellenas de tinta gris. Treinta y nueve de cuarenta y uno."]],
           opts: [{ t: "«¿Qué significan las manos grises?»", go: "manos", once: true },
                  { t: "«Busque si alguno tiene familia hoy.»", go: "familia" },
                  { t: "«Dele la lista a Escoria.»", go: "escoria" },
                  { t: "«Mándela grabar en la pared de las Cuevas.»", go: "pared" }] },
      manos: { say: [["ebano", "Que se les fueron las manos. Treinta y nueve de cuarenta y uno. Y las dos que quedan en blanco tienen al lado otra palabra: «se fue»."],
                     ["ebano", "No dice adónde. Supongo que dos personas en cuarenta y uno se dieron cuenta a tiempo. El Gremio no guardó cómo."]], back: "a" },
      familia: { say: [[null, "Ébano pasa tres días cruzando la lista con los libros de nacimientos. Encuentra apellidos. Uno se repite: es el apellido de Fogarín."],
                       ["ebano", "El abuelo del abuelo del Maestro del Gremio está en la lista. Con la mano gris."],
                       [null, "Llevas la hoja al Cráter. Fogarín la lee sentado en un yunque frío. No dice nada. Esa noche no baja a los hornos hondos."]], end: { xp: 18, flag: "e4_fogarinLista" } },
      escoria: { say: [[null, "Escoria lee la lista en la escalinata del Gremio, en voz alta, nombre por nombre, a quien quiera oír. Se junta gente."],
                       [null, "Cuando llega al final, alguien grita: «¿Y los dos que se fueron? ¿Cómo se fueron?». Nadie sabe."],
                       [null, "Desde ese día, en el Cráter se dice «irse» en vez de «renunciar». Los capataces lo odian."]], end: { xp: 16, flag: "e4_listaLeida" } },
      pared: { say: [[null, "Galena graba los cuarenta y dos nombres en la pared de las Cuevas, con una mano chiquita al lado de cada uno. Tarda un mes."],
                     ["ebano", "Ahora está en piedra. La Corte lo guardó en papel mil años y lo tuvo escondido. La Hondura lo pone en piedra en un mes y lo deja a la vista. Cada pueblo guarda como sabe."]], end: { xp: 16, flag: "e4_listaPiedra" } },
    } },

    "e4-humo": { kind: "encuentro", need: { era: 4, layer: 3 }, who: { hulla: "Hulla, carbonera de la Corte" }, start: "a", nodes: {
      a: { say: [[null, "A medianoche se oyen gritos en la Hondonada. Una galería de hornos se derrumbó y el humo del carbón de sombra sube por las bodegas viejas hasta las casas. Negro, espeso, dulce."],
                 [null, "La gente sale a la calle tosiendo. Hay chicos con los ojos rojos. Un perro corre en círculos. Las lámparas no alumbran: el humo se come la luz."],
                 ["hulla", "¡Hay que sacar el humo o sacar a la gente! ¡Las dos cosas no alcanzan!"]],
           opts: [{ t: "Romper las chimeneas viejas de las bodegas para que salga el humo", go: "romper" },
                  { t: "Llevar a todos al Vado", go: "vado" },
                  { t: "Bajar a la galería derrumbada por los que quedaron", go: "bajar" }] },
      romper: { say: [[null, "Rompes con una barreta los tapones de piedra de las chimeneas viejas, las de cuando la Corte hacía visiones. El humo empieza a subir, despacio."],
                      [null, "Sube tanto que al amanecer el cielo del Claro está gris. En el Prado no sale el sol hasta el mediodía."],
                      ["hulla", "La Hondonada respira. El Prado no ve el sol. Mañana nos van a echar la culpa de la noche. Esta vez tienen razón."]], end: { xp: 16, flag: "e4_cieloGris" } },
      vado: { say: [[null, "Guías a la gente por el camino del río hasta el Vado. Son cientos. Llegan al amanecer, tosiendo, con mantas, con chicos dormidos en brazos."],
                    [null, "El Vado se llena. Hay que compartir el agua, el pan, el piso. Algunos vecinos del Vado no abren la puerta."],
                    ["hulla", "Los que abrieron se van a acordar. Los que no, también. La Hondonada tiene buena memoria para las puertas."]], end: { xp: 18, heal: 0.05, flag: "e4_hondonadaVado" } },
      bajar: { say: [[null, "Te atas un trapo mojado a la cara y bajas. No ves nada. Encuentras a dos carboneros por la tos, tirados contra una pared. Los arrastras de a uno."],
                     [null, "Cuando subes con el segundo, no puedes dejar de toser. Hulla te sostiene la cabeza."],
                     ["hulla", "Dos. Sacó dos. Quedaban tres. El tercero era mi sobrino."],
                     [null, "No dice nada más. Te da agua. Se queda sentada al lado tuyo hasta que paras de toser."]], end: { xp: 20, hurt: 0.2, flag: "e4_carbonerosSalvados" } },
    } },

    "e4-velos": { kind: "dialogo", need: { era: 4, layer: 3 }, who: { merma: "Reina Merma", hulla: "Hulla, carbonera de la Corte" }, start: "a", nodes: {
      a: { say: [[null, "En el patio del Trono, la Corte entera está reunida. Hay velos de todos los grises. Llegó la noticia: los pueblos se juntan en el Corazón por la Campana. La Corte tiene que decidir si va."],
                 ["merma", "Si vamos, nos van a mirar. Nos van a culpar del humo, de la tierra, de la casa del Barrio. Y de cosas de hace mil años."],
                 ["hulla", "Si no vamos, nos culpan igual. Pero no estamos para decir lo que sabemos."]],
           opts: [{ t: "«Vayan sin velo.»", go: "sinvelo" },
                  { t: "«Vayan con velo. Es lo que son.»", go: "convelo" },
                  { t: "«Que no vaya la Reina. Que vayan los carboneros.»", go: "carboneros" },
                  { t: "«No vayan. Esta vez no.»", go: "novan" }] },
      sinvelo: { say: [["merma", "¿Sin velo? ¿Delante de las Casas?"],
                       [null, "Hulla se saca el velo primero. Después Ónix, el guarda de las tumbas. Después una vieja. Después todos, uno por uno, hasta que el patio está lleno de caras."],
                       ["merma", "Bueno. Si nos van a mirar, que vean la cara de los que tosen. Vamos al Corazón así."]], end: { xp: 20, flag: ["e4_sinVelo", "u4_sombra"] } },
      convelo: { say: [["merma", "Con velo. Sí. Mil años de velo no se tiran en una noche."],
                       ["hulla", "Mil años de velo y nadie sabe nuestras caras. Ni nosotros."],
                       [null, "La Corte va al Corazón con velo. La miran igual. Nadie sabe a quién mirar."]], end: { xp: 12, flag: "e4_conVelo" } },
      carboneros: { say: [["merma", "¿Que la Corte vaya sin su Reina? Eso nunca pasó."],
                          ["hulla", "Por eso. Que vaya la que respira el humo. Usted firma. Nosotros tosemos."],
                          [null, "Merma se queda en silencio un rato largo. Después asiente."],
                          ["merma", "Vaya, Hulla. Y diga todo. Lo del carbón, lo de la Torre, lo mío. Si va a ir la Corte de verdad, que vaya entera."]], end: { xp: 20, flag: ["e4_carbonerosVan", "u4_sombra"] } },
      novan: { say: [[null, "La Corte se queda. Nadie de la Hondonada va al Corazón."],
                     ["hulla", "Ya está. Otra vez de espaldas. Que digan lo que quieran de nosotros. Siempre lo dicen."]], end: { xp: 8, flag: "e4_corteNoVa" } },
    } },
  });

  /* ---------- Lago Espejo: Remanso, los baños, los peces, la orilla que se lee y el agua que se seca ---------- */
  add("lake", {
    "e4-remanso": { kind: "dialogo", need: { era: 4, layer: 1 }, who: { remanso: "Remanso, el viejo vidente" }, start: "a", nodes: {
      a: { say: [[null, "En la orilla norte, un viejo de pelo blanco y ojos claros está sentado en un muelle podrido, con los pies en el agua. Mira el vapor que sube de la orilla sur."],
                 ["remanso", "Cuidador. Soy Remanso. El niño del muelle. Ahora soy el viejo del muelle. El muelle es el mismo, más podrido."],
                 ["remanso", "El agua caliente trae visiones otra vez. No hay que beberla: con el vapor alcanza. La gente se para en la orilla sur y respira. Y ve cosas."]],
           opts: [{ t: "«Usted dejó de beber y pesca en el río.»", go: "rio", cNeed: "end_remanso_A" },
                  { t: "«Usted vio a su padre en el lago.»", go: "padre", cNeed: "end_remanso_B" },
                  { t: "«Usted bebía por los que pagaban.»", go: "pagaban", cNeed: "end_remanso_C" },
                  { t: "«¿Qué ven en el vapor?»", go: "ven" },
                  { t: "«Avise a la gente que no respire ese vapor.»", go: "avisar" }] },
      rio: { say: [["remanso", "Pesco en el río. El río no hierve, todavía. Pero los peces del río tienen una raya gris en el lomo. Como una mano."],
                   ["remanso", "Dejé el lago para no ver cosas. Ahora las cosas vienen al río."]], back: "a" },
      padre: { say: [["remanso", "Lo vi. Y seguí bebiendo. Tengo los ojos así por eso."],
                     ["remanso", "Ahora en el vapor veo otra cosa. Veo a un hombre trabajando en una forja bajo el agua. Le veo las manos. Se le van poniendo grises mientras martilla. No para."]], back: "a" },
      pagaban: { say: [["remanso", "Bebía. Ya no puedo: me tiemblan las manos y se me cae la copa. Ahora respiro el vapor gratis, como todos."],
                       ["remanso", "No me acuerdo de cuántos años tengo. Pero me acuerdo de lo que vi anoche: una campana que suena y una tierra que se calla de golpe. Y después, nada. Un silencio sin fondo."]], back: "a" },
      ven: { say: [["remanso", "Cada uno ve algo distinto. Pero todos ven lo mismo al final: un sonido que no se oye y una cosa muy grande que deja de moverse."],
                   ["remanso", "Los del Gremio dicen que es la Campana funcionando. Que es un buen augurio. Yo vi muchos augurios. Los buenos se parecen mucho a los malos, de lejos."]], back: "a" },
      avisar: { say: [[null, "Remanso se levanta del muelle, con trabajo. Camina hasta la orilla sur apoyado en tu brazo. Se para entre la gente y el vapor."],
                      ["remanso", "Yo bebí visiones toda la vida. Miren mis ojos. No respiren esto. Lo que ven no es el futuro. Es lo que el lago no quiere que pase."],
                      [null, "Algunos se van. Otros se quedan, respirando. Remanso se queda con ellos, de pie, para que lo vean."]], end: { xp: 16, flag: "e4_remansoAvisa" } },
    } },

    "e4-banos": { kind: "encuentro", need: { era: 4, layer: 1 }, who: { nacar: "Nácar, de las Casas", salitre: "Salitre, pescadora" }, start: "a", nodes: {
      a: { say: [[null, "En la orilla sur, donde el agua hierve menos, las Casas construyeron unos baños de madera blanca, con toldos y escalones. Un cartel dice: «Aguas del Alba. Salud y descanso». Hay fila."],
                 ["nacar", "Bienvenido, Cuidador. Agua caliente natural. Cura la tos, el frío, las penas. Una moneda la hora. Para las Casas, la mitad."],
                 [null, "Al lado de los baños, detrás de una cerca, Salitre limpia peces cocidos en un balde. No mira los toldos."]],
           opts: [{ t: "«¿Por qué las Mareas no pueden entrar?»", go: "mareas", once: true },
                  { t: "«Que entren gratis los que trabajan en los hornos.»", go: "gratis" },
                  { t: "«Que una parte de lo que cobran vaya a las Mareas.»", go: "parte" },
                  { t: "Romper la cerca", go: "cerca" }] },
      mareas: { say: [["nacar", "Pueden entrar. Pagando. Como todos."],
                      ["salitre", "Pagando por bañarnos en el lago que era nuestro. Que hierve porque el Gremio cava. Que las Casas cobran porque llegaron primero con madera."]], back: "a" },
      gratis: { say: [["nacar", "¿Gratis? ¿Para los obreros? Ellos ensucian el agua con hollín."],
                      [null, "Le dices que el agua caliente ablanda un poco las manos grises. Que lo viste. Nácar duda."],
                      ["nacar", "Una hora a la semana. Los martes, temprano, antes de que lleguen los de las Casas. Es lo que puedo."],
                      [null, "El martes siguiente hay cien obreros en la fila, a oscuras. Salen con las manos rojas y un poco más blandas."]], end: { xp: 18, flag: "e4_banosObreros" } },
      parte: { say: [["nacar", "¿Una parte? ¿De qué?"],
                     ["salitre", "De lo que cobra por nuestra agua."],
                     [null, "Nácar mira la fila. Mira a Salitre. Saca la cuenta en voz baja."],
                     ["nacar", "Un décimo. Ni una moneda más. Y que conste que es un regalo de las Casas."],
                     ["salitre", "Un regalo. Con nuestra agua. Bueno. Lo acepto. Y lo anoto."]], end: { xp: 14, coins: 10, flag: "e4_banosParte" } },
      cerca: { say: [[null, "Arrancas dos tablas de la cerca. Salitre te mira. Después arranca la tercera."],
                     [null, "Las Mareas entran a los baños sin pagar, con los pies llenos de barro. Los de las Casas se van, ofendidos. Nácar grita."],
                     [null, "Al día siguiente hay una cerca nueva, más alta, y un guardia. Y un cartel nuevo: «Prohibido el paso a los que rompen»."]], end: { xp: 10, flag: "e4_cercaRota" } },
    } },

    "e4-peces": { kind: "encuentro", need: { era: 4, layer: 2 }, who: {}, start: "a", nodes: {
      a: { say: [[null, "En una cala del lago, el agua está tibia y quieta. Las criaturas de agua que antes saltaban aquí están en la orilla, tiradas en el barro fresco, respirando rápido."],
                 [null, "Una criatura grande, de escamas azules, tiene una mancha gris en la aleta. No la mueve. Tu criatura se acerca, la huele, y se queda a su lado sin moverse."],
                 [null, "Más allá, en el agua, la superficie burbujea despacio. Debajo hay un horno."]],
           opts: [{ t: "Llevar a las criaturas a la orilla norte, donde el agua es fría", go: "norte" },
                  { t: "Echar agua fría sobre la cala", go: "fria" },
                  { t: "Quedarte con la criatura de la mancha gris", go: "quedarte" }] },
      norte: { say: [[null, "Llevas a las criaturas una por una hasta la orilla norte, cargándolas, arrastrándolas, convenciéndolas. Tarda todo el día."],
                     [null, "En el agua fría, algunas se hunden y vuelven a salir, sacudiéndose. La de la mancha gris no se hunde. Se queda flotando, quieta, mirándote."]], end: { xp: 16, flag: "e4_crianzaNorte" } },
      fria: { say: [[null, "Acarreas baldes de agua del río y los vacías en la cala. Es como llenar un lago con una taza. Al atardecer tienes los brazos rotos."],
                    [null, "El agua de la cala está un poco menos tibia. Una criatura chica se mete y nada en círculos. No alcanza para las otras. Pero esa nada."]], end: { xp: 12, flag: "e4_calaFria" } },
      quedarte: { say: [[null, "Te sientas en el barro al lado de la criatura grande. Tu criatura se acuesta contra ella. Pasa la noche."],
                        [null, "Al amanecer la criatura de la mancha gris mueve la aleta. Despacio. Una vez. Después se arrastra hasta el agua y se hunde."],
                        [null, "No sabes si se fue a morir o a vivir. Tu criatura mira el agua mucho rato."]], end: { xp: 14, heal: 0.1, flag: "e4_aletaGris" } },
    } },

    "e4-rada": { kind: "dialogo", need: { era: 4, layer: 2 }, who: { rada: "Rada, de las Mareas" }, start: "a", nodes: {
      a: { say: [[null, "Cuando baja el agua en la orilla sur, una mujer de las Mareas camina entre las piedras de la plaza hundida con los ojos cerrados y la mano apoyada en las paredes."],
                 ["rada", "Me llamo Rada. Mi abuela me enseñó a leer las paredes con los dedos. Ella era Orilla. Las Mareas tenemos la costumbre de leer lo que el agua tapa."],
                 ["rada", "Ahora que el agua hierve y baja, aparecen paredes que nunca vimos. Hay una que habla de la forja hundida. Y del que trabajaba ahí."]],
           opts: [{ t: "«Su abuela caminaba por aquí con la mano en las paredes.»", go: "camina", cNeed: "end_e3orilla_A" },
                  { t: "«Su abuela contaba las luces que se apagaban.»", go: "luces", cNeed: "end_e3orilla_B" },
                  { t: "«Las Mareas eran guardianas del lago.»", go: "guardianas", cNeed: "end_e3ola_A" },
                  { t: "«¿Qué dice la pared de la forja?»", go: "pared" }] },
      camina: { say: [["rada", "Todos los días que bajaba el agua. Yo la seguía. Así aprendí. Ella decía que las paredes no mienten porque nadie las escribió para que las leyera alguien."],
                      ["rada", "Lo que se escribe para nadie es lo más verdadero que hay."]], back: "a" },
      luces: { say: [["rada", "Las contaba. Después contaba a los que pasaban sin mirarla. Yo la miraba siempre. Por eso me enseñó."],
                     ["rada", "Me dijo: cuando ya no haya luces que contar, lee las piedras. Las piedras se quedan."]], back: "a" },
      guardianas: { say: [["rada", "Lo éramos. Cobrábamos poco y sacábamos menos. Ahora el Gremio saca por abajo y las Casas cobran por arriba. A las guardianas nos queda mirar."],
                          ["rada", "Pero mirar también es guardar. Por lo menos alguien ve lo que pasa."]], back: "a" },
      pared: { say: [[null, "Rada pone tu mano sobre la piedra, al lado de la suya. Sientes surcos, cortos, en filas."],
                     ["rada", "Dice: «Trabajé en el agua para que el metal se enfriara. El agua no alcanzó. El metal no se enfría. Solo cambia de lugar: de la veta a la mano, de la mano a la piedra»."],
                     ["rada", "Y abajo, más chico: «Al que venga: el metal es de la Raíz. Lo que le sacas, te lo cobra en el cuerpo»."]],
             opts: [{ t: "«Hay que llevar esto al Corazón.»", go: "corazon" },
                    { t: "«Cópielo en papel para el Gremio.»", go: "copiar" },
                    { t: "«Déjelo aquí. El agua lo va a volver a tapar.»", go: "dejar" }] },
      corazon: { say: [["rada", "¿Una pared? No se puede llevar una pared."],
                       [null, "Lo piensas. Le dices que ella sí se puede llevar: los dedos que la leyeron."],
                       ["rada", "Entonces voy yo. Con los ojos cerrados, como mi abuela. Que las Mareas lleven lo que el lago guardó."]], end: { xp: 20, flag: ["e4_radaLee", "u4_agua"] } },
      copiar: { say: [[null, "Rada copia la pared en un papel, letra por letra, con los ojos cerrados y la mano izquierda en la piedra. Tarda toda la tarde."],
                      [null, "Fogarín recibe el papel. Lo lee dos veces. Lo guarda en el delantal."],
                      ["rada", "No lo rompió. No lo mostró. Lo guardó. A veces eso es lo peor que te pueden hacer con algo verdadero."]], end: { xp: 14, flag: "e4_paredCopiada" } },
      dejar: { say: [["rada", "Sí. Que la tape. Lo que se escribe para nadie no es para nosotros."],
                     [null, "Esa noche sube el agua. Pero no tanto como antes: el lago tiene menos agua cada año. La pared queda a medio tapar."]], end: { xp: 10, flag: "e4_paredDejada" } },
    } },

    "e4-vapor": { kind: "encuentro", need: { era: 4, layer: 2 }, who: { fuelle: "Fuelle, maestro joven", salitre: "Salitre, pescadora" }, start: "a", nodes: {
      a: { say: [[null, "En la orilla sur, Fuelle y tres obreros clavan tubos de cobre en el agua hirviendo. Los tubos suben por la ladera, hacia el Prado."],
                 ["fuelle", "¡Cuidador! Mire esto. El vapor del lago va por los tubos hasta las casas del Prado. Calor gratis todo el invierno. ¡El lago hierve igual, por lo menos que sirva!"],
                 ["salitre", "Calor gratis para las Casas. ¿Y para el Barrio? ¿Y para nosotros, que vivimos al lado del agua que hierve?"]],
           opts: [{ t: "«¿Gratis para quién, Fuelle?»", go: "quien", once: true },
                  { t: "«Que los tubos vayan primero al Barrio.»", go: "barrio" },
                  { t: "«Que las Mareas manejen las válvulas.»", go: "valvulas" },
                  { t: "«Saquen los tubos. Esto es como los tubos largos.»", go: "sacar" }] },
      quien: { say: [["fuelle", "Bueno, gratis no. El Gremio pone los tubos. Las Casas pagan los tubos. Las Casas tienen el calor."],
                     ["fuelle", "¿Qué quiere? Así funciona. El que pone, cobra. Al Gremio lo compraron toda la vida. Ahora vende."]], back: "a" },
      barrio: { say: [["fuelle", "¿Al Barrio? El Barrio no paga tubos."],
                      [null, "Le recuerdas la votación de las piedras negras. Que los obreros son del Barrio. Que el calor que vende sale de las manos de ellos."],
                      ["fuelle", "Está bien. Uno de cada tres tubos al Barrio. Y no me mire así, que es más de lo que nadie les dio nunca."]], end: { xp: 16, flag: "e4_tubosBarrio" } },
      valvulas: { say: [["salitre", "¿Nosotras? ¿Que las Mareas decidan cuánto vapor sube?"],
                        ["fuelle", "Las Mareas no saben de tubos."],
                        ["salitre", "Sabemos de agua. Mil años sabiendo de agua. Si el lago baja mucho, cerramos. Si sube, abrimos. Eso sí sabemos."],
                        [null, "Fuelle lo piensa. Le da la llave de la primera válvula. Salitre la cuelga de su cuello, con un cordón de red."]], end: { xp: 18, flag: "e4_valvulasMareas" } },
      sacar: { say: [[null, "Arrancas el primer tubo del agua. Sale un chorro de vapor que te quema el antebrazo. Fuelle grita."],
                     ["fuelle", "¿Usted sabe lo que cuesta un tubo?"],
                     [null, "Los obreros no clavan el segundo. Esperan. Fuelle mira el lago hervir sin que nadie lo aproveche."],
                     ["fuelle", "Bueno. Que hierva para nada, entonces. Como siempre."]], end: { xp: 10, hurt: 0.1, flag: "e4_tubosFuera" } },
    } },

    "e4-cuaderno": { kind: "dialogo", need: { era: 4, layer: 3, anyFlag: ["e4_lagoPagado", "e4_banosParte", "e4_valvulasMareas"] }, who: { salitre: "Salitre, pescadora" }, start: "a", nodes: {
      a: { say: [[null, "Salitre tiene un cuaderno de hojas mojadas, atado con hilo de red. Lo abre sobre una piedra. Son números. Peces, monedas, semanas."],
                 ["salitre", "Mi abuela tenía uno igual. Era Ola, ¿sabe? La de las Mareas. Ella también anotaba todo."],
                 ["salitre", "Yo cuento lo que nos pagan. El número sube. Y el lago baja. Mire: cada vez que el número sube, el agua baja un dedo. Son la misma cuenta."]],
           opts: [{ t: "«Su abuela nunca llegó a cero.»", go: "cero", cNeed: "end_e3ola_C" },
                  { t: "«Su abuela firmó con las Casas.»", go: "firmo", cNeed: "end_e3ola_B" },
                  { t: "«Deje de cobrar. Que no haya cuenta.»", go: "dejar" },
                  { t: "«Lleve el cuaderno al Gremio y muéstreles la cuenta.»", go: "mostrar" }] },
      cero: { say: [["salitre", "Nunca. Se murió con un número chico en la última hoja. Siete barriles. No sé de qué eran."],
                    ["salitre", "Yo no quiero morirme con un número grande. Prefiero el chico. Por lo menos el chico se parece a algo que se cuida."]], back: "a" },
      firmo: { say: [["salitre", "Firmó. Tenemos papeles de la orilla norte. Las Mareas no vagan. Tampoco nos acordamos de por qué vagábamos."],
                     ["salitre", "Ahora sí me acuerdo. Vagábamos porque el agua se mueve. Si te quedas quieta al lado del agua, terminas cobrándole."]], back: "a" },
      dejar: { say: [["salitre", "¿Dejar de cobrar? ¿Y que hiervan el lago gratis?"],
                     [null, "Cierra el cuaderno. Lo aprieta contra el pecho."],
                     ["salitre", "Tiene razón y no la tiene. Si no cobro, el Gremio cava igual. Si cobro, el Gremio cava y yo tengo monedas. El lago baja en las dos. Me quedo con las monedas. Y con la vergüenza, que también se guarda."]], end: { xp: 12, flag: "e4_salitreCobra" } },
      mostrar: { say: [[null, "Vas con Salitre al Cráter. Abre el cuaderno delante de los doce maestros, en la mesa larga."],
                       ["salitre", "Aquí. Cada moneda que nos pagan, un dedo de agua menos. Ustedes no compran pescado cocido. Compran el lago. De a dedo."],
                       [null, "Los maestros se miran. Fogarín pide el cuaderno. Lo lee entero, en silencio, mientras todos esperan."],
                       [null, "Esa semana el Gremio cierra dos hornos bajo el lago. No los diez. Dos. El agua deja de bajar en la cala del norte."]], end: { xp: 20, flag: "e4_hornosLagoCerrados" } },
    } },

    "e4-cala": { kind: "encuentro", need: { era: 4, layer: 3 }, who: { salitre: "Salitre, pescadora", galena: "Galena, minera" }, start: "a", nodes: {
      a: { say: [[null, "Una mañana, la cala del sur amanece seca. El agua se fue toda, en una noche, por una grieta del fondo. Donde estaba el lago hay barro cocido y peces blancos pegados al suelo."],
                 [null, "En el medio de la cala seca asoma una veta roja, ancha como un camino, que baja hacia el Corazón. Late. Se ve latir a simple vista."],
                 ["galena", "Es la más grande que vi. Con esto el Gremio hace diez campanas."],
                 ["salitre", "Con esto el lago se vacía entero. La grieta es la veta. El agua se va por donde el metal sube."]],
           opts: [{ t: "Tapar la grieta con piedras y barro para que vuelva el agua", go: "tapar" },
                  { t: "Dejar que el Gremio saque la veta", go: "sacar" },
                  { t: "Cantarle la nana a la veta", go: "nana" }] },
      tapar: { say: [[null, "Llamas a las Mareas, a los mineros, a los obreros de los martes. Llegan cien. Acarrean piedras y barro durante tres días."],
                     [null, "La grieta se tapa. El agua de la lluvia empieza a juntarse en la cala, despacio. Va a tardar años en llenarse."],
                     ["salitre", "Años. Bueno. El lago tardó mil en hacerse. Puede tardar algunos en volver."],
                     ["galena", "Y la veta queda abajo, latiendo. Ahora sabemos dónde está. El Gremio también."]], end: { xp: 20, flag: "e4_calaTapada" } },
      sacar: { say: [[null, "No haces nada. Al día siguiente llegan los mineros del Gremio con picos y carretillas. Sacan la veta en una semana."],
                     [null, "Con ese metal se termina la Campana grande. Fuelle está feliz."],
                     ["salitre", "La cala no va a volver. El agua sigue yéndose por el agujero de la veta. Despacio. Todos los días un poco."]], end: { xp: 10, coins: 20, flag: "e4_vetaLagoSacada" } },
      nana: { say: [[null, "Te sientas en el barro cocido y cantas. Salitre no conoce la letra, pero tararea. Galena golpea el ritmo con el pico, en la piedra, de a dos."],
                    [null, "El latido de la veta se hace más lento. El rojo se oscurece. La grieta, no se cierra, pero deja de tragar."],
                    ["galena", "Se calma con la nana. Siempre se calma con la nana. ¿Por qué estamos haciendo una campana, entonces?"],
                    [null, "Nadie contesta. Salitre anota algo en el cuaderno: no un número, una palabra."]], end: { xp: 18, heal: 0.1, flag: "e4_calaNana" } },
    } },
  });

  /* ---------- Cuevas del Eco: Cuarzo, el capataz, el derrumbe, la Noche del Eco y lo que golpea del otro lado ---------- */
  add("caves", {
    "e4-cuarzo": { kind: "encuentro", need: { era: 4, layer: 1 }, who: { galena: "Galena, minera" }, start: "a", nodes: {
      a: { say: [[null, "En la Sala del Eco, Galena te muestra las paredes que grabó Cuarzo, el cronista de la Hondura, hace sesenta años. Hay noches enteras grabadas, nombres, una nana a medias."],
                 ["galena", "Cuarzo era el abuelo de mi abuelo. O algo así: en la Hondura se cuenta raro. Grabó hasta que se le gastó el cincel."],
                 ["galena", "Los mineros pasan por aquí todos los días y no miran. Las paredes están tan llenas que ya parecen piedra lisa."]],
           opts: [{ t: "«Él dejó de grabar y la gente contaba en voz alta.»", go: "voz", cNeed: "end_cuarzo_A" },
                  { t: "«Él borró los nombres de su abuelo para grabar Veladas.»", go: "borro", cNeed: "end_cuarzo_B" },
                  { t: "«Él encontró grabados más viejos, muy abajo.»", go: "viejos", cNeed: "end_cuarzo_C" },
                  { t: "«Lea una pared en voz alta.»", go: "leer" }] },
      voz: { say: [["galena", "Sí. Durante años, en la Sala, se contaban las noches en voz alta. Después el Gremio puso turnos dobles y nadie tuvo tiempo de venir."],
                   ["galena", "La Sala está vacía de noche desde hace diez años. Las paredes no dicen nada si nadie viene."]], back: "a" },
      borro: { say: [["galena", "Los gritaba en la Noche del Eco. Cuando se murió, nadie los aprendió. Esos nombres no están en ningún lado."],
                     ["galena", "En la Hondura decimos que lo que nadie dice, se lo queda la piedra. Supongo que esos nombres son piedra ya."]], back: "a" },
      viejos: { say: [["galena", "Sí. Los encontré yo también, en los túneles calientes. Son manos. Manos grabadas con una raya al lado. Como los de la forja del lago."],
                      ["galena", "Cuarzo no dijo lo que decían porque no sabía leerlas. Yo tampoco sé. Pero sé contar: son cuarenta y dos."]], back: "a" },
      leer: { say: [[null, "Galena lee una pared en voz alta: una Velada de hace sesenta años, con nombres, con lo que cantó cada pueblo. Su voz rebota por la Sala."],
                    [null, "Dos mineros que pasaban se detienen. Después cinco. Se sientan en el suelo. Galena lee hasta que se le seca la boca."],
                    ["galena", "Mañana leo otra. Si vienen, leo. Si no, leo igual. La piedra no se queja."]], end: { xp: 14, flag: "e4_salaLeida" } },
    } },

    "e4-capataz": { kind: "encuentro", need: { era: 4, layer: 1 }, who: { plomo: "Plomo, capataz del Gremio", galena: "Galena, minera" }, start: "a", nodes: {
      a: { say: [[null, "En la boca de los túneles calientes, un capataz del Gremio con una pizarra cuenta carretillas. Tiene las uñas limpias y la voz cansada."],
                 ["plomo", "Turnos dobles hasta que se termine la Campana. Órdenes de arriba. El que no quiere, que se vaya. Hay cola en la ladera sur para entrar."],
                 ["galena", "Turnos dobles en los túneles calientes son manos grises en tres lunas, Plomo. Tú lo sabes."],
                 ["plomo", "Yo sé contar carretillas. Lo demás no me lo pagan."]],
           opts: [{ t: "«¿Y si se niegan todos a la vez?»", go: "todos", once: true },
                  { t: "«Que los turnos dobles sean en los túneles fríos.»", go: "frios" },
                  { t: "«Ponga agua fría en la boca del túnel. Que se laven las manos.»", go: "agua" },
                  { t: "Ponerte a empujar carretillas para que los mineros descansen", go: "empujar" }] },
      todos: { say: [["plomo", "Entonces el Gremio trae a los de la ladera, que no saben. Y los de la Hondura se quedan sin trabajo y sin manos igual, porque ya las tienen medio grises."],
                     ["plomo", "No crea que me gusta. Mi padre era minero. Yo soy capataz para no ser minero. Eso es todo lo que hice bien."]], back: "a" },
      frios: { say: [["plomo", "¿En los fríos? Ahí no hay metal."],
                     [null, "Le explicas: los turnos dobles en los fríos, sacando piedra para los moldes; los turnos simples en los calientes. Misma cantidad de horas. Menos manos grises."],
                     ["plomo", "Las carretillas de metal van a ser menos. Arriba se van a enojar."],
                     [null, "Mira a Galena. Tacha algo en la pizarra."],
                     ["plomo", "Que se enojen. Las carretillas las cuento yo."]], end: { xp: 18, flag: "e4_turnosFrios" } },
      agua: { say: [[null, "Traes con Galena dos barriles de agua de las filtraciones frías y los pones en la boca del túnel. Cada minero que sale mete las manos hasta el codo."],
                    ["galena", "Mi abuelo decía que el agua fría no cura, pero frena. Frenar está bien. Frenar es lo único que se puede."]], end: { xp: 12, flag: "e4_barrilesFrios" } },
      empujar: { say: [[null, "Empujas carretillas toda la tarde. Diez mineros descansan sentados contra la pared, con las manos en el regazo."],
                       [null, "Al final tienes las palmas rojas y calientes. Te las lavas con agua fría, como dijo Galena, hasta que dejan de arder."],
                       ["plomo", "Diez descansaron una tarde. Mañana vuelven. Usted no puede empujar todas las tardes."]], end: { xp: 10, hurt: 0.05, coins: 6 } },
    } },

    "e4-derrumbe": { kind: "encuentro", need: { era: 4, layer: 2 }, who: { galena: "Galena, minera", plomo: "Plomo, capataz del Gremio" }, start: "a", nodes: {
      a: { say: [[null, "Un ruido sordo, largo, recorre las Cuevas. Cae polvo del techo. Después, silencio. Después, gritos: el túnel caliente número siete se derrumbó."],
                 ["plomo", "Seis adentro. Seis. Tenía seis anotados."],
                 [null, "Galena pega la oreja a las piedras caídas. Golpea dos veces con el pico. Espera. Del otro lado, débiles, responden dos golpes. Después otros dos. Después uno."]],
           opts: [{ t: "Cavar con las manos, ahora", go: "cavar" },
                  { t: "Pedir al Gremio herramientas y gente", go: "gremio" },
                  { t: "Mandar a tu criatura por una grieta chica", go: "criatura" }] },
      cavar: { say: [[null, "Cavas con Galena y veinte mineros, a mano, pasando piedras de mano en mano. Las piedras de este túnel están calientes. Te queman los dedos."],
                     [null, "Tardan un día y una noche. Sacan a cinco. El sexto no responde a los golpes desde la mañana."],
                     ["galena", "Cinco. La Hondura saca a los suyos con las manos. Siempre. Aunque se le pongan grises."],
                     [null, "Miras tus manos. Tienen polvo rojo en las uñas que no sale con agua."]], end: { xp: 20, hurt: 0.15, flag: "e4_cincoSalvados" } },
      gremio: { say: [["plomo", "Voy yo. Corro."],
                      [null, "Plomo vuelve en una hora con Fogarín, diez obreros del Cráter y barretas de metal de raíz. Las barretas abren la piedra como si fuera barro."],
                      [null, "Sacan a los seis vivos. Los obreros del Cráter tienen las manos más grises después de usar las barretas."],
                      ["galena", "El metal que nos enferma nos sacó. No sé qué pensar de eso. No sé si tengo que dar las gracias."]], end: { xp: 18, flag: "e4_barretasRaiz" } },
      criatura: { say: [[null, "Tu criatura mira la grieta. Te mira. Entra. Tardas en dejar de oír sus pasos."],
                        [null, "Al rato, del otro lado, alguien grita de sorpresa. Después, voces. Tu criatura vuelve con un trapo atado al cuello: un mapa dibujado con hollín del lugar donde están."],
                        [null, "Con el mapa, los mineros cavan justo donde hay que cavar. Sacan a los seis antes del amanecer."],
                        ["galena", "Su criatura sabe ir por donde nosotros no. Abajo, eso vale más que un pico."]], end: { xp: 20, flag: "e4_criaturaMapa" } },
    } },

    "e4-ecos": { kind: "encuentro", need: { era: 4, layer: 2 }, who: { galena: "Galena, minera" }, start: "a", nodes: {
      a: { say: [[null, "Es la Noche del Eco. La Hondura entera se junta en la Sala, con lámparas. Antes, esta noche, se gritaban los nombres de los muertos para que la piedra los repitiera."],
                 [null, "Este año, la mitad de la gente no grita nombres. Grita números: carretillas, monedas, turnos. Se ríen. La piedra repite los números igual."],
                 ["galena", "Es la primera vez que la Hondura gana bien. La gente está contenta. No sé si está mal que estén contentos."]],
           opts: [{ t: "Gritar el nombre del minero que no salió del derrumbe", go: "nombre", cNeed: "e4_cincoSalvados" },
                  { t: "Gritar los cuarenta y dos nombres de la lista", go: "lista", cNeed: "e4_listaPiedra" },
                  { t: "Gritar «manos»", go: "manos" },
                  { t: "No gritar. Dejar que festejen.", go: "festejar" }] },
      nombre: { say: [[null, "Gritas el nombre del sexto. La piedra lo repite, una vez, dos, tres, cada vez más lejos."],
                      [null, "La Sala se calla. Alguien llora. Después, una voz grita otro nombre, de otro año. Y otra."],
                      ["galena", "Ahí está. La Hondura se acordó de lo que hace esta noche. Hacía falta un muerto nuevo para acordarse de los viejos."]], end: { xp: 18, flag: "e4_ecoNombres" } },
      lista: { say: [[null, "Lees en voz alta los nombres de la pared nueva, uno por uno, los cuarenta y dos. La piedra los repite. Los mineros callan."],
                     [null, "Cuando terminas, Galena golpea la pared dos veces. Desde muy abajo, lejos, responden dos golpes."],
                     ["galena", "Nos oyeron. No sé quién. Pero nos oyeron."]], end: { xp: 20, flag: "e4_ecoNombres" } },
      manos: { say: [[null, "Gritas «manos». La piedra lo repite: manos, manos, manos, hasta que suena como un martillo."],
                     [null, "Algunos mineros se miran las suyas. Uno esconde las suyas en los bolsillos. Otro las levanta, grises, para que las vean."],
                     ["galena", "Una palabra. A veces una palabra alcanza para que alguien se mire las manos."]], end: { xp: 14, flag: "e4_ecoManos" } },
      festejar: { say: [[null, "No gritas. La Hondura festeja. Los números rebotan por la Sala hasta tarde."],
                        [null, "Al final, cuando ya casi no queda nadie, Galena grita un solo nombre, bajito. El de su abuelo. La piedra lo repite una vez y se calla."]], end: { xp: 8 } },
    } },

    "e4-pizca": { kind: "encuentro", need: { era: 4, layer: 2 }, who: { pizca: "Pizca", plomo: "Plomo, capataz del Gremio" }, start: "a", nodes: {
      a: { say: [[null, "En un túnel tan angosto que no pasa un adulto, una niña de la ladera sur sale a gatas empujando un balde de piedras rojas. Tiene las rodillas peladas y una lámpara atada a la frente."],
                 ["pizca", "Me llamo Pizca. Soy de los chicos de los túneles chicos. El Gremio paga la mitad, pero entramos donde los grandes no."],
                 ["pizca", "Mi amiga Chispa forja. Yo saco lo que ella forja. Somos un equipo. Aunque ella no lo sabe todavía."]],
           opts: [{ t: "«¿Cuántos chicos trabajan aquí?»", go: "cuantos", once: true },
                  { t: "Hablar con Plomo para que saquen a los chicos de los túneles", go: "plomo" },
                  { t: "Llevar a Pizca con Chispa", go: "chispa" },
                  { t: "Enseñarle a contar golpes, como la Hondura", go: "golpes" }] },
      cuantos: { say: [["pizca", "Treinta. Treinta y uno con el nuevo. Los más chicos tienen siete. Yo tengo diez, soy de las viejas."],
                       ["pizca", "No se preocupe. Nos dan agua fría y pan. Y si las uñas se ponen grises, nos cambian al túnel de afuera. Eso dicen."]], back: "a" },
      plomo: { say: [[null, "Plomo te escucha con la pizarra contra el pecho."],
                     ["plomo", "Si los saco, el Gremio pone a otros chicos, de otra ladera. O cierra los túneles chicos y pierde el metal. O me saca a mí y pone a otro capataz que no pregunta."],
                     [null, "Pero esa noche Plomo borra los treinta y un nombres de la pizarra. Al día siguiente pone una tabla en la boca de los túneles chicos: «Cerrado por derrumbe». No hubo derrumbe."]], end: { xp: 18, flag: "e4_tunelesChicosCerrados" } },
      chispa: { say: [[null, "Llevas a Pizca a la forja de piedras de la ladera. Chispa la mira con desconfianza. Pizca le muestra una piedra roja del balde."],
                      ["pizca", "Esto lo saco yo. Tú lo usas para que el hierro agarre."],
                      [null, "Chispa mira la piedra. Mira las rodillas peladas de Pizca. Mira su propia uña gris."],
                      [null, "Al día siguiente las dos forjan en frío, sin nada rojo. Tardan el triple. Se ríen el doble."]], end: { xp: 16, flag: "e4_pizcaChispa" } },
      golpes: { say: [[null, "Le enseñas lo que Galena te enseñó: dos golpes, alguien quedó abajo; uno largo, todo bien; tres rápidos, que salgan todos."],
                      ["pizca", "¡Ya sé un idioma de piedra! Se lo voy a enseñar a todos los chicos de los túneles chicos."],
                      [null, "Una semana después, cuando se cae un techo en un túnel chico, los chicos se avisan con tres golpes rápidos. Salen todos. No se lastima nadie."]], end: { xp: 16, flag: "e4_chicosGolpes" } },
    } },

    "e4-paredmanos": { kind: "encuentro", need: { era: 4, layer: 3, anyFlag: ["e4_paredManos", "e4_listaPiedra"] }, who: { galena: "Galena, minera", escoria: "Escoria, obrera", fogarin: "Fogarín, Maestro del Gremio" }, start: "a", nodes: {
      a: { say: [[null, "En una galería nueva, lejos de la Sala, hay una pared llena de manos grabadas. Debajo de cada una, un nombre. Algunas son del Gremio de hoy. Otras, de la lista de hace mil años."],
                 [null, "Hay gente frente a la pared. Obreros del Cráter con las manos grises, carboneros de la Corte con el musgo en la boca, mineros de la Hondura. No hablan. Miran."],
                 ["escoria", "Vinieron solos. Nadie los llamó. Bajaron desde el Cráter a pie para ver sus nombres en la piedra."],
                 ["galena", "La Hondura graba para que nadie se olvide. Nunca grabó para los vivos. Esta es la primera pared de vivos."]],
           opts: [{ t: "«Que todos los pueblos graben aquí a los suyos.»", go: "todos" },
                  { t: "«Que la vea el Maestro del Gremio.»", go: "fogarin" },
                  { t: "Grabar tu propia mano", go: "tumano" }] },
      todos: { say: [[null, "Durante una luna bajan de todos lados. Leñadores del Bosque, pescadoras de las Mareas, arrieros de los Altos. Cada uno graba una mano y un nombre."],
                     [null, "La pared se llena. Galena abre otra galería al lado. También se llena."],
                     ["galena", "Nueve pueblos en una pared. Si llaman del Corazón, la Hondura va a ir con esto. No con carretillas. Con manos."]], end: { xp: 22, flag: ["e4_paredPueblos", "u4_piedra"] } },
      fogarin: { say: [[null, "Fogarín baja a las Cuevas por primera vez en su vida. Camina despacio, con un bastón. Se para frente a la pared un rato largo."],
                       [null, "Busca un nombre con el dedo. Lo encuentra: su abuelo del abuelo, el de la lista de Ébano. Al lado, la mano de Yunque, recién grabada."],
                       ["fogarin", "Mil años y seguimos poniendo nombres en la misma pared. Esto no es un Gremio. Es un cementerio que trabaja."],
                       [null, "Pide un cincel. Graba su propia mano. La de las uñas con la línea gris."]], end: { xp: 20, flag: "e4_fogarinPared" } },
      tumano: { say: [[null, "Apoyas la mano en la piedra. Galena la marca con un clavo y la graba despacio. Debajo pones el nombre que te dicen en el Vado."],
                      [null, "Tu criatura apoya su pata al lado. Galena la graba también, sin preguntar."],
                      ["escoria", "El Cuidador tiene la mano limpia. Bueno. Que haya una mano limpia en la pared, para acordarse de cómo eran."]], end: { xp: 16, flag: "e4_manoCuidador" } },
    } },

    "e4-otrolado": { kind: "encuentro", need: { era: 4, layer: 3 }, who: { galena: "Galena, minera" }, start: "a", nodes: {
      a: { say: [[null, "Galena te lleva al túnel más hondo de todos, donde la pared golpea de dos en dos. Trae un pico de metal de raíz que pidió prestado al Gremio."],
                 ["galena", "Voy a abrir. Hace un año que esta pared me contesta. Quiero ver quién."],
                 [null, "Golpea. La piedra se abre en un agujero del tamaño de una puerta. Del otro lado sale aire tibio, quieto, viejo."],
                 [null, "Adentro hay una sala redonda. En las paredes, sentados, de pie, apoyados, hay figuras de piedra con forma de personas. Muchas. Tienen herramientas en las manos. Algunas tienen la boca abierta, como si cantaran."]],
           opts: [{ t: "«¿Son... los de la lista?»", go: "lista", once: true },
                  { t: "Entrar y tocar una figura", go: "tocar" },
                  { t: "Sellar la sala otra vez", go: "sellar" },
                  { t: "Traer a todos a verla", go: "mostrar" }] },
      lista: { say: [["galena", "Cuarenta. Cuento cuarenta. La lista decía treinta y nueve con las manos grises. Y uno tachado. Cuarenta."],
                     ["galena", "No se murieron. Se quedaron. Siguieron trabajando hasta que se volvieron piedra del todo. Y los pusieron aquí. O vinieron solos."],
                     [null, "En el medio de la sala hay una veta roja que late. Los golpes de dos en dos son el latido, rebotando en cuarenta cuerpos de piedra."]], back: "a" },
      tocar: { say: [[null, "Tocas el hombro de una figura. Está tibia. Debajo de la piedra, muy despacio, algo late. No es la veta. Es más lento."],
                     [null, "La figura no se mueve. Pero tu criatura gruñe bajito, con las orejas hacia atrás, y no se acerca."],
                     ["galena", "Siguen. Están vivos de alguna forma. Como la piedra está viva. Despacio. Muy despacio."]], end: { xp: 18, hurt: 0.05, flag: "e4_figurasTibias" } },
      sellar: { say: [[null, "Galena te mira un rato largo. Después asiente. Tapan el agujero con piedra y argamasa."],
                      [null, "Galena graba en la pared sellada: «Aquí están los cuarenta. No cavar». Y al lado, cuarenta manos chiquitas."],
                      ["galena", "Los dejamos descansar. Si se puede decir así. Por lo menos que nadie los use de carretilla."]], end: { xp: 14, flag: "e4_cuarentaSellados" } },
      mostrar: { say: [[null, "Durante una semana baja gente de todo el Claro a ver la sala de los cuarenta. Mineros, obreros, maestros del Gremio, gente de las Casas con pañuelos en la nariz."],
                       [null, "Algunos salen llorando. Otros, callados. Un maestro joven sale y vomita. Fuelle sale último y no dice nada en todo el camino de vuelta."],
                       ["galena", "Ahora lo saben. Lo que nos va a pasar ya pasó. Cuarenta veces. Lo que no sé es si saberlo cambia algo."]], end: { xp: 20, flag: ["e4_cuarentaVistos", "u4_piedra"] } },
    } },
  });

  /* ==================== Entrega 4: los Altos, el Fondo y el Corazón ==================== */

  /* ---------- Los Altos: la nieve roja, el mirador, la compradora de afuera, los versos y la espada que vuelve ---------- */
  add("heights", {
    "e4-nieveroja": { kind: "encuentro", need: { era: 4, layer: 1 }, who: {}, start: "a", nodes: {
      a: { say: [[null, "En el camino del paso, la nieve no es blanca. Es rosada, a manchas, y en algunos lugares roja como una herida. Las carretas del metal dejan un polvo fino que el viento esparce por las laderas."],
                 [null, "Las criaturas de la montaña comen esa nieve. Una cabra blanca de los Altos lame una mancha roja y después se queda quieta, con las patas rígidas, mirando el valle."],
                 [null, "Tu criatura huele la nieve roja y estornuda. No la toca. Te mira como si te preguntara por qué está así."]],
           opts: [{ t: "Tapar las manchas con nieve limpia", go: "tapar" },
                  { t: "Llevar a la cabra rígida al pueblo", go: "cabra" },
                  { t: "Juntar nieve roja para mostrarla abajo", go: "juntar" }] },
      tapar: { say: [[null, "Echas nieve limpia sobre las manchas con las manos, con los pies, con una tabla. Es como barrer el mar. El camino entero está manchado."],
                     [null, "Al atardecer pasa otra fila de carretas. El polvo rojo vuelve a caer. Tu criatura se sienta al lado del camino y no quiere seguir."]], end: { xp: 8 } },
      cabra: { say: [[null, "Cargas a la cabra hasta el pueblo de la ladera. Pesa más de lo que debería. Tiene las patas duras, frías, como de piedra."],
                     [null, "Una vieja la frota con grasa al lado del fuego toda la noche. Al amanecer, la cabra dobla una pata. Después la otra."],
                     [null, "La vieja no dice nada. Pone un cartel en la puerta del corral: «No comer la nieve roja». Lo dibuja, para los que no leen."]], end: { xp: 14, heal: 0.05, flag: "e4_cabraSalvada" } },
      juntar: { say: [[null, "Llenas una bolsa de cuero con nieve roja. Al bajar, la nieve se derrite y queda un barro rojo en el fondo de la bolsa, tibio."],
                      [null, "En el Vado lo pones en un frasco, en la repisa, con una etiqueta: «Los Altos». Los que pasan lo miran y preguntan. Les cuentas."]], end: { xp: 12, flag: "e4_frascoRojo" } },
    } },

    "e4-mirador": { kind: "dialogo", need: { era: 4, layer: 1 }, who: { toldo: "Toldo, de los Altos" }, start: "a", nodes: {
      a: { say: [[null, "En el mirador del viento hay un toldo a rayas, gastado, remendado muchas veces. Debajo, un hombre de mediana edad vende mapas de los pasos, dibujados a mano."],
                 ["toldo", "Me llamo Toldo. Mi abuelo era Trueque, el del toldo. Vendía pedazos de noches. Yo vendo pedazos de montaña: por dónde pasar con una carreta caliente sin que se caiga la nieve."],
                 ["toldo", "Todo el mundo vende algo en este mirador. Mi abuelo decía que el viento lo compra todo y no paga nunca."]],
           opts: [{ t: "«Su abuelo mostraba la noche entera, gratis.»", go: "entera", cNeed: "end_trueque_A" },
                  { t: "«Su abuelo se hizo rico vendiendo pedazos.»", go: "rico", cNeed: "end_trueque_B" },
                  { t: "«Su abuelo decía que vendía lo mismo que siempre.»", go: "mismo", cNeed: "end_trueque_C" },
                  { t: "«¿Sus mapas muestran dónde se cae la nieve?»", go: "mapas" },
                  { t: "«Regale los mapas a los arrieros.»", go: "regalar" }] },
      entera: { say: [["toldo", "Sí. Y vendía frasquitos al lado, más caros que nunca. Una cosa pagaba la otra."],
                      ["toldo", "Yo hago igual. Regalo el mapa de los pasos seguros a los pueblos de la ladera. Y se lo vendo caro al Gremio. El Gremio paga por todos."]], back: "a" },
      rico: { say: [["toldo", "Rico. Con casa en el Prado y un perro malo. Cuando se murió, las Casas se quedaron con la casa por las deudas. El perro se vino conmigo."],
                    ["toldo", "Está ahí, mire, debajo de la mesa. Ya no muerde. Lo que se gana vendiendo pedazos se pierde de una vez, entero."]], back: "a" },
      mismo: { say: [["toldo", "«Lo mismo que siempre.» Sí. Nadie sabía qué contestar. Yo tampoco sé, todavía."],
                     ["toldo", "Creo que vendía lo que la gente quería creer. Que es siempre lo mismo, aunque cambie el frasco."]], back: "a" },
      mapas: { say: [["toldo", "Muestran dónde se cayó. Dónde se va a caer, no lo sabe nadie. Desde que pasan las carretas, la montaña cambia más rápido que mis dibujos."],
                     [null, "Te muestra un mapa. Hay cruces rojas en tres pueblos de la ladera."],
                     ["toldo", "Estas cruces las dibujé este año. El año pasado no había ninguna."]], back: "a" },
      regalar: { say: [["toldo", "¿Regalarlos? ¿A los arrieros, que llevan el metal?"],
                       [null, "Le dices que los arrieros son los primeros que mueren cuando cae la nieve. Que el metal va a pasar igual, con o sin mapa."],
                       ["toldo", "Mi abuelo me mataría. Bueno, ya está muerto. Los regalo. Pero los que sean para el Gremio, los cobro el triple."]], end: { xp: 16, flag: "e4_mapasRegalados" } },
    } },

    "e4-afuera": { kind: "dialogo", need: { era: 4, layer: 2 }, who: { cizalla: "Cizalla, compradora de afuera", peaje: "Peaje, arriero" }, start: "a", nodes: {
      a: { say: [[null, "En la posada más alta del paso hay una mujer que no es del Claro. Lleva ropa de lana gruesa, de un color que no se tiñe aquí, y habla con un acento cortado. Tiene una espada sobre la mesa."],
                 ["cizalla", "Me llamo Cizalla. Compro metal para los señores del otro lado. Ellos hacen guerras. Yo hago compras. Cada uno tiene su oficio."],
                 ["cizalla", "Esta espada es de su metal rojo. No se mella. No se enfría. Mis señores quieren mil. Pagan con oro. Ustedes no saben lo que vale el oro afuera."],
                 ["peaje", "Yo la traje hasta aquí. Quiere ver el Cráter. Quiere hablar con el Gremio directamente, sin los Altos en el medio."]],
           opts: [{ t: "«¿Contra quién son esas guerras?»", go: "guerras", once: true },
                  { t: "«Las espadas que no se enfrían también vuelven las manos de piedra.»", go: "manos" },
                  { t: "Llevarla al Cráter", go: "llevar" },
                  { t: "«Vuelva por donde vino.»", go: "volver" }] },
      guerras: { say: [["cizalla", "Contra otros señores. Siempre hay otros señores. No se preocupe: el Claro está lejos y es chico. Nadie va a hacerle la guerra a un valle que no tiene oro."],
                       ["cizalla", "Por ahora. El metal rojo puede cambiar eso. Se lo digo porque soy honesta, no porque me importe."]], back: "a" },
      manos: { say: [["cizalla", "¿Las manos?"],
                     [null, "Le cuentas. Ella escucha sin interrumpir. Al final mira la espada. Se mira la mano con la que la agarró en el camino."],
                     ["cizalla", "Mis señores no tocan las espadas. Las tocan los soldados. Los soldados no hacen preguntas. Gracias por decírmelo. No va a cambiar nada. Pero ahora lo sé."]], end: { xp: 12, flag: "e4_cizallaSabe" } },
      llevar: { say: [[null, "Llevas a Cizalla al Cráter. Fogarín la recibe en la sala de los maestros. Fuelle no le saca los ojos de encima a la bolsa de oro."],
                      [null, "Hablan toda la tarde. Al final, el Gremio firma: doscientos lingotes al año para afuera, a cambio de oro. Los Altos se quedan con el transporte, pero no con el trato."],
                      ["peaje", "Ya está. Ahora el Claro le vende guerras a otros. Y yo las llevo en la carreta."]], end: { xp: 10, coins: 30, flag: "e4_tratoAfuera" } },
      volver: { say: [["cizalla", "¿Volver? He cruzado tres montañas."],
                      ["peaje", "Y cruza tres de vuelta. Yo la llevo. Gratis."],
                      [null, "Cizalla se ríe. Guarda la espada. Se va al amanecer, con Peaje y dos bueyes, sin el trato."],
                      ["peaje", "Va a volver otro. Siempre vuelve otro. Pero este año, no."]], end: { xp: 16, flag: "e4_cizallaVuelve" } },
    } },

    "e4-versos": { kind: "encuentro", need: { era: 4, layer: 2 }, who: { romanza: "Romanza, mensajera" }, start: "a", nodes: {
      a: { say: [[null, "En una cueva de la cumbre, donde antes los mensajeros de los Altos ensayaban los versos que llevaban de pueblo en pueblo, hay una sola mujer, joven, con un tambor chico."],
                 ["romanza", "Soy Romanza. Soy la última mensajera de los Altos. Los demás se hicieron arrieros. Llevar metal paga. Llevar versos, no."],
                 ["romanza", "Me sé ciento cuarenta versos de memoria. La nana entera, también. Nadie me pide ninguno desde hace dos años."]],
           opts: [{ t: "«Cánteme uno.»", go: "cantar", once: true },
                  { t: "«Lleve la nana a los hornos del Cráter.»", go: "hornos" },
                  { t: "«Enseñe los versos a los arrieros, para el camino.»", go: "arrieros" },
                  { t: "«Escriba los versos antes de que se pierdan.»", go: "escribir" }] },
      cantar: { say: [[null, "Romanza toca el tambor despacio y canta un verso viejo de los Altos: un mensaje de un pueblo a otro avisando que la nieve iba a caer, hace trescientos años."],
                      ["romanza", "Ese verso salvó un pueblo. Ahora el aviso lo da un mapa de Toldo. Es más exacto. Pero nadie lo canta."]], back: "a" },
      hornos: { say: [[null, "Romanza baja al Cráter con su tambor. Se para en la boca de los hornos hondos y canta la nana. Los obreros que salen se detienen."],
                      [null, "Al día siguiente vuelve. Al otro, también. Los obreros empiezan a esperarla. Algunos la cantan bajando."],
                      ["romanza", "No sé si sirve para algo. Pero bajan cantando. Antes bajaban callados."]], end: { xp: 16, flag: "e4_nanaHornos" } },
      arrieros: { say: [[null, "Romanza camina con la fila de carretas dos semanas. Les enseña los versos de los pasos: dónde se cae la nieve, dónde hay agua, dónde no parar."],
                        ["romanza", "Los aprendieron. Los cantan para no dormirse. Llevan metal y versos en la misma carreta. Es raro. Pero los Altos siempre llevaron dos cosas a la vez."]], end: { xp: 14, flag: "e4_versosArrieros" } },
      escribir: { say: [[null, "Romanza dicta. Tú escribes. Tarda tres días: ciento cuarenta versos y la nana, entera, con las notas dibujadas como puede."],
                        ["romanza", "Ahora están en papel. Si me muero, quedan. Pero un verso escrito no viaja solo. Alguien tiene que cantarlo."]], end: { xp: 14, flag: "e4_versosEscritos" } },
    } },

    "e4-trineo": { kind: "encuentro", need: { era: 4, layer: 2 }, who: { peaje: "Peaje, arriero" }, start: "a", nodes: {
      a: { say: [[null, "En una curva del paso, una carreta se salió del camino. Está volcada en la nieve, a medio derretir. Los lingotes calientes abrieron agujeros humeantes alrededor. Un buey está atrapado debajo."],
                 ["peaje", "¡Era de mi primo! Él saltó. El buey no."],
                 [null, "El buey muge. Debajo de la carreta, la nieve se hunde despacio, derretida por los lingotes."]],
           opts: [{ t: "Levantar la carreta entre todos", go: "levantar" },
                  { t: "Sacar los lingotes primero, para que deje de hundirse", go: "lingotes" },
                  { t: "Cortar los arneses y tirar del buey", go: "arneses" }] },
      levantar: { say: [[null, "Llamas a los arrieros. Diez personas, con palos, levantan la carreta un palmo. El buey sale arrastrándose, con una pata rota."],
                        [null, "La carreta cae otra vez. Se hunde en el agujero de nieve derretida y desaparece. Los lingotes también."],
                        ["peaje", "Se perdió la carga. El Gremio va a cobrársela a mi primo. Pero el buey vive. Mi primo lo va a cuidar aunque tenga que comer menos."]], end: { xp: 16, flag: "e4_bueyVivo" } },
      lingotes: { say: [[null, "Tomas los lingotes con cueros mojados y los tiras a la nieve, lejos. Cada uno abre un pozo humeante donde cae. Te quemas los dedos a través del cuero."],
                        [null, "La carreta deja de hundirse. Pero el buey ya no muge. Se quedó quieto debajo, con los ojos abiertos."],
                        ["peaje", "Salvamos el metal. El metal siempre se salva. Es lo único que no se muere."]], end: { xp: 10, hurt: 0.1, flag: "e4_metalSalvado" } },
      arneses: { say: [[null, "Cortas los arneses con el cuchillo de Peaje. Tiran del buey entre tres. Sale, mugiendo, y se queda parado en la nieve, temblando."],
                       [null, "La carreta se hunde sola. Los lingotes se pierden en el fondo del agujero, donde siguen humeando."],
                       ["peaje", "Ahí abajo van a seguir calientes cien años. Cuando se derrita la nieve en primavera, el agua de este arroyo va a bajar tibia hasta el Lago. Ya veremos qué hace."]], end: { xp: 14, flag: "e4_lingotesNieve" } },
    } },

    "e4-espada": { kind: "dialogo", need: { era: 4, layer: 3 }, who: { peaje: "Peaje, arriero", cizalla: "Cizalla, compradora de afuera" }, start: "a", nodes: {
      a: { say: [[null, "Por el paso del norte no sube una carreta: baja una persona. Es Cizalla, la compradora de afuera. Viene a pie, sin bueyes, con el brazo derecho envuelto en trapos."],
                 ["cizalla", "Vengo a devolver esto. No me lo pidió nadie. Me lo pido yo."],
                 [null, "Pone sobre la mesa de la posada una espada roja. Al lado, se desenvuelve el brazo. La mano está gris hasta el codo. No la mueve."],
                 ["cizalla", "Mis señores ganaron su guerra. Los soldados que agarraron las espadas tienen las manos como la mía. Ya no pueden agarrar nada. Ni la paga."]],
           opts: [{ t: "«¿Por qué volvió?»", go: "porque", once: true },
                  { t: "«Llévela al Corazón. Que la vean.»", go: "corazon" },
                  { t: "«Tírela al Lago, donde no la toque nadie.»", go: "lago" },
                  { t: "«Quédese. En el Claro sabemos de manos.»", go: "quedarse" }] },
      porque: { say: [["cizalla", "Porque usted me lo dijo y no me importó. Ahora me importa. Llega tarde, siempre llega tarde."],
                      ["peaje", "Lo que sale del Claro no vuelve, decían los viejos. Vuelve. Vuelve con el brazo de otro."]], back: "a" },
      corazon: { say: [[null, "Cizalla y Peaje llevan la espada al Corazón. La clavan en la tierra, al pie de la tercera estatua, al lado de la escoria."],
                       ["cizalla", "Que la vean los nueve. Que vean lo que hace afuera lo que ustedes hacen adentro."],
                       ["peaje", "Los Altos van a ir al Corazón con esto. No con carretas. Con lo que las carretas traen de vuelta."]], end: { xp: 20, flag: ["e4_espadaCorazon", "u4_altos"] } },
      lago: { say: [[null, "Tiras la espada al Lago desde la orilla norte. Cae de punta y se hunde sin salpicar. Donde cayó, el agua empieza a echar vapor."],
                    ["cizalla", "Se hundió. Pero el lago va a hervir un poco más ahí. Nada de esto se va del todo. Solo se cambia de lugar."]], end: { xp: 12, flag: "e4_espadaLago" } },
      quedarse: { say: [["cizalla", "¿Quedarme? ¿En un valle sin oro?"],
                        [null, "Mira su mano gris. Mira la posada, el fuego, a Peaje."],
                        ["cizalla", "Bueno. No tengo a dónde ir con una mano sola. Me quedo en los Altos. Voy a enseñar lo que sé de afuera. Que sepan lo que hay del otro lado de las montañas, por si un día viene."]], end: { xp: 16, flag: "e4_cizallaQueda" } },
    } },

    "e4-cumbre": { kind: "dialogo", need: { era: 4, layer: 3 }, who: { peaje: "Peaje, arriero", romanza: "Romanza, mensajera" }, start: "a", nodes: {
      a: { say: [[null, "En la plaza del pueblo más alto de los Altos, los arrieros y los últimos mensajeros se juntan alrededor de un fuego. Llegó la noticia: los pueblos se reúnen en el Corazón por la Campana."],
                 ["peaje", "Si vamos, nos van a pedir que dejemos de llevar el metal. Y los Altos comen de eso."],
                 ["romanza", "Si no vamos, el Corazón decide sin nadie que sepa lo que hay del otro lado de los pasos."]],
           opts: [{ t: "«Vayan los arrieros, con lo que llevaron.»", go: "arrieros" },
                  { t: "«Que vaya Romanza, con los versos.»", go: "romanza" },
                  { t: "«No vayan. Que decidan los de abajo.»", go: "novan" }] },
      arrieros: { say: [["peaje", "Con lo que llevamos. Con las carretas, las quemaduras, los bueyes muertos. Con las cuentas, también. Que se sepa cuánto pagan afuera."],
                        [null, "Los arrieros levantan las manos, uno por uno. Tienen las palmas quemadas de agarrar lonas calientes."],
                        ["peaje", "Vamos. Y si nos piden que dejemos de llevar, vamos a pedir algo a cambio. Los Altos no regalan nada. Pero escuchan."]], end: { xp: 18, flag: ["e4_arrierosVan", "u4_altos"] } },
      romanza: { say: [["romanza", "¿Yo? ¿Sola, con un tambor?"],
                       ["peaje", "Con todos nosotros detrás. Pero que hable usted. Que los Altos vuelvan a llevar un mensaje y no un lingote, por una vez."],
                       [null, "Romanza toca el tambor. Los arrieros cantan el verso de la nieve que cae. Es la primera vez en años que se oye en la cumbre."]], end: { xp: 20, flag: ["e4_romanzaVa", "u4_altos"] } },
      novan: { say: [["peaje", "Que decidan ellos. Y que nos digan después qué llevar. Como siempre."],
                     [null, "El fuego se apaga temprano. Romanza se va a su cueva sin tocar el tambor."]], end: { xp: 8, flag: "e4_altosNoVan" } },
    } },
  });

  /* ---------- Fondo Blanco: las goteras, el Turno, Nieve, el hielo que se vende y lo que guardaba el hielo ---------- */
  add("deep", {
    "e4-goteras": { kind: "encuentro", need: { era: 4, layer: 1 }, who: { copo: "Copo" }, start: "a", nodes: {
      a: { say: [[null, "En una sala de hielo del Fondo, veinte chicos sentados en el suelo ponen tazas, cuencos y botas debajo de las goteras. Cuando una se llena, la vacían en un barril y la vuelven a poner."],
                 ["copo", "Me llamo Copo. Esto es la escuela. Bueno, era. Ahora es la sala de las goteras. La maestra dice que contar gotas también es aprender."],
                 ["copo", "Hoy contamos tres mil. Ayer, dos mil ochocientas. Mañana van a ser más. Eso sí lo aprendimos."]],
           opts: [{ t: "«¿Por qué no se mudan arriba?»", go: "arriba", once: true },
                  { t: "Ayudar a tapar las goteras con nieve apretada", go: "tapar" },
                  { t: "Enseñarles un juego con las gotas", go: "juego" }] },
      arriba: { say: [["copo", "Arriba ya está lleno. Los viejos primero. Después los que tienen criaturas. Después nosotros."],
                      ["copo", "No importa. Aquí abajo por lo menos se oye la música de las gotas. Arriba hace demasiado silencio."]], back: "a" },
      tapar: { say: [[null, "Aprietan nieve con las manos y la meten en las grietas del techo. Los chicos se suben a hombros de otros. Tardan toda la tarde."],
                     [null, "Las goteras paran. Por una noche. A la mañana siguiente, la nieve apretada gotea igual que el hielo."],
                     ["copo", "Bueno. Por lo menos dormimos secos una noche. Mañana tapamos de nuevo. Es como un trabajo."]], end: { xp: 10 } },
      juego: { say: [[null, "Le enseñas a Copo a escuchar las gotas: cada una cae en una taza distinta y suena distinto. Si las pones en orden, suenan como una canción."],
                     [null, "En una hora los chicos ordenaron cuarenta tazas. Suena la nana, a gotas, desafinada, lenta."],
                     ["copo", "¡El techo canta! La maestra va a decir que no es aprender. Pero suena lindo."]], end: { xp: 14, heal: 0.1, flag: "e4_gotasNana" } },
    } },

    "e4-turno": { kind: "dialogo", need: { era: 4, layer: 1 }, who: { carambano: "Nevado, del Turno" }, start: "a", nodes: {
      a: { say: [[null, "El círculo del Turno sigue en su sala de hielo, pero el hielo gotea sobre los que duermen. Hay menos soñadores que antes. Cada uno tiene una manta encerada encima."],
                 ["carambano", "Soy Nevado. Cuido el Turno desde que murió Nevisca. Seguimos durmiendo. No sé bien para quién. Ya ni las familias del Prado pagan: compran turnos de Campana."],
                 ["carambano", "Lo raro es que los que duermen aquí sueñan todos lo mismo desde hace un año: un ruido que no se oye y algo enorme que se queda quieto."]],
           opts: [{ t: "«Nevisca dormía para la Raíz con la mitad de los soñadores.»", go: "raiz", cNeed: "end_e3nevisca_A" },
                  { t: "«El Fondo cobraba el doble por cada sueño.»", go: "doble", cNeed: "end_e3nevisca_B" },
                  { t: "«Nevisca recibía a los que llegaban con huecos.»", go: "huecos", cNeed: "end_e3nevisca_C" },
                  { t: "«Ese sueño es la Campana.»", go: "campana" },
                  { t: "«Despiértelos. Que nadie sueñe eso a la fuerza.»", go: "despertar" }] },
      raiz: { say: [["carambano", "Sí. La mitad sigue. Soñamos blanco, como decía ella. Pero ahora el blanco tiene una raya roja en el medio. No se va."],
                    ["carambano", "Si soñamos lo que sueña la Raíz, la Raíz tiene miedo. Nunca la había soñado con miedo."]], back: "a" },
      doble: { say: [["carambano", "El doble. Y después nadie pagó nada. Tenemos leña para diez inviernos y nadie que la compre."],
                     ["carambano", "Ahora regalamos los sueños. Nadie los quiere. Un sueño gratis vale menos que uno caro, aunque sea el mismo."]], back: "a" },
      huecos: { say: [["carambano", "Seguimos. Llegan del Cráter, ahora. Con las manos grises y un hueco. No les falta un recuerdo: les falta el tacto. No saben si algo está caliente."],
                      ["carambano", "Les damos caldo. Lo agarran con las dos manos y no saben si quema. Lo tomamos con ellos, para avisarles."]], back: "a" },
      campana: { say: [["carambano", "¿La Campana? ¿Soñamos la Campana antes de que suene?"],
                       [null, "Mira a los que duermen. Uno se mueve, se queja, vuelve a quedarse quieto."],
                       ["carambano", "Entonces el Turno sabe lo que va a pasar. Y nadie le pregunta al Turno. Voy a escribir los sueños. Todos. Por si alguien quiere saber qué siente la Raíz."]], end: { xp: 16, flag: "e4_suenosEscritos" } },
      despertar: { say: [[null, "Nevado despierta a los soñadores uno por uno. Algunos lloran al abrir los ojos. Uno pregunta si ya sonó."],
                         ["carambano", "No. Todavía no. Vuelvan a sus casas. Si la Raíz quiere soñar con miedo, que sueñe sola un tiempo. Nosotros no somos su miedo."],
                         [null, "El Turno queda vacío por primera vez en mil años. Gotea sobre las mantas enceradas, vacías."]], end: { xp: 12, flag: "e4_turnoVacio" } },
    } },

    "e4-nieve": { kind: "dialogo", need: { era: 4, layer: 2 }, who: { nieve: "Doña Nieve" }, start: "a", nodes: {
      a: { say: [[null, "Sobre el lago helado del Fondo, que ahora tiene charcos de agua encima, una anciana patina despacio, con un bastón en cada mano. Da una vuelta, dos. Se detiene a tu lado, sin aliento."],
                 ["nieve", "Cuidador. Soy Nieve. La niña del hielo. Patino todavía, mire. Mal. Pero patino."],
                 ["nieve", "Este invierno el lago no se congeló entero. Hay agua debajo, moviéndose. Cuando patino, la oigo. Suena como cuando se cayó mi hermano."]],
           opts: [{ t: "«Usted le devolvió su hermano al lago.»", go: "devolvio", cNeed: "end_e3nieve_A" },
                  { t: "«Usted bebió la caída de su hermano.»", go: "bebio", cNeed: "end_e3nieve_B" },
                  { t: "«Usted saluda la copa todas las mañanas.»", go: "copa", cNeed: "end_e3nieve_C" },
                  { t: "«No patine más aquí. Se va a romper.»", go: "noPatinar" },
                  { t: "Patinar con ella una vuelta", go: "patinar" }] },
      devolvio: { say: [["nieve", "Se lo devolví. El agujero se cerró. Ahora el lago se abre de nuevo, en otros lados. A lo mejor me lo devuelve a mí."],
                        ["nieve", "No quiero. Que se quede donde está. Ya me despedí."]], back: "a" },
      bebio: { say: [["nieve", "Tengo su risa. Todavía. Sesenta años con la risa de otro adentro."],
                     ["nieve", "Cuando el lago suena, la risa se me sale sola. Los chicos creen que estoy loca. A lo mejor."]], back: "a" },
      copa: { say: [["nieve", "Todas las mañanas. La cera está intacta. Pero este invierno la copa suda. Por fuera. Como si adentro hiciera calor."],
                    ["nieve", "No la voy a abrir. Pero la miro más."]], back: "a" },
      noPatinar: { say: [["nieve", "Tiene razón. Me lo dijeron todos. Usted es la primera persona que me lo dice mientras estoy sobre el hielo."],
                         [null, "Sale del lago despacio, con los bastones. Se sienta en la orilla y se saca los patines."],
                         ["nieve", "Bueno. Ya patiné sesenta años. Que patinen los chicos cuando vuelva a congelarse. Si vuelve."]], end: { xp: 12, flag: "e4_nieveOrilla" } },
      patinar: { say: [[null, "Patinas con ella, despacio, del brazo. El hielo cruje. Debajo se mueve el agua."],
                       [null, "A mitad de la vuelta, Nieve se ríe. Es una risa de chico, muy vieja y muy nueva a la vez."],
                       ["nieve", "Gracias. Ahora sí. Si se rompe mañana, que se rompa. Hoy aguantó."]], end: { xp: 16, heal: 0.1, flag: "e4_nievePatina" } },
    } },

    "e4-hielero": { kind: "encuentro", need: { era: 4, layer: 2 }, who: { tempano: "Témpano, guardiana del hielo", fuelle: "Fuelle, maestro joven" }, start: "a", nodes: {
      a: { say: [[null, "En la entrada del Fondo hay una fila de carretas vacías del Gremio. Los del Fondo cortan bloques de hielo viejo, azul, y los cargan. Fuelle cuenta los bloques."],
                 ["fuelle", "El hielo del Fondo enfría los moldes de la Campana mejor que nada. Les pagamos bien. ¡Por fin el Fondo vende algo!"],
                 ["tempano", "Vendemos el hielo que se está derritiendo por sus hornos para enfriar lo que sus hornos calientan. Si me lo explica despacio, a lo mejor le encuentro sentido."]],
           opts: [{ t: "«¿Cuánto hielo queda?»", go: "cuanto", once: true },
                  { t: "«Que paguen con hornos cerrados, no con monedas.»", go: "hornos" },
                  { t: "«Que solo corten el hielo que ya se está derritiendo.»", go: "derretido" },
                  { t: "Volcar una carreta de hielo en el camino", go: "volcar" }] },
      cuanto: { say: [["tempano", "Al ritmo de ahora, diez años. Con las carretas, cinco."],
                      ["fuelle", "En cinco años la Campana está lista y no hacen falta más hornos. Es una buena cuenta."],
                      ["tempano", "Es una buena cuenta para usted. Para el Fondo es una cuenta hacia atrás."]], back: "a" },
      hornos: { say: [["fuelle", "¿Hornos cerrados? ¿A cambio de hielo?"],
                      [null, "Témpano se cruza de brazos. Los del Fondo dejan de cortar."],
                      ["fuelle", "Bueno. Un horno cerrado por cada cien bloques. Fogarín me va a matar. O me va a felicitar. Con él nunca se sabe."]], end: { xp: 18, flag: "e4_hieloPorHornos" } },
      derretido: { say: [[null, "Témpano marca con pintura roja los bloques que ya gotean. Solo esos se cargan. Son menos, más chicos, más blandos."],
                         ["fuelle", "Esto no enfría ni la mitad."],
                         ["tempano", "Entonces sus moldes tardan el doble. Y el Fondo dura el doble. Me parece justo."]], end: { xp: 14, flag: "e4_hieloMarcado" } },
      volcar: { say: [[null, "Empujas una carreta llena hasta que se vuelca. Los bloques de hielo se rompen en el camino, azules, brillantes."],
                      ["fuelle", "¿Qué hace? ¡Eso estaba pagado!"],
                      ["tempano", "Ya no. Ya es del Fondo otra vez. Aunque sea en pedazos."],
                      [null, "Fuelle se va furioso. Las otras carretas se van vacías. Al día siguiente vuelven, con un guardia."]], end: { xp: 10, flag: "e4_hieloVolcado" } },
    } },

    "e4-glaciar": { kind: "encuentro", need: { era: 4, layer: 2 }, who: {}, start: "a", nodes: {
      a: { say: [[null, "En el borde del glaciar del Fondo se oye un crujido largo, como un árbol que se quiebra muy despacio. Una grieta azul se abre en el hielo, de lado a lado."],
                 [null, "Del otro lado de la grieta quedaron atrapadas unas criaturas de escarcha: cinco, chicas, blancas, que se esconden entre los bloques. La grieta se ensancha."],
                 [null, "Tu criatura corre hasta el borde, ladra, vuelve hacia ti, corre otra vez al borde."]],
           opts: [{ t: "Tender una tabla sobre la grieta", go: "tabla" },
                  { t: "Mandar a tu criatura a guiarlas", go: "criatura" },
                  { t: "Rodear el glaciar por arriba", go: "rodear" }] },
      tabla: { say: [[null, "Buscas una tabla larga y la tiendes sobre la grieta. Cruje. Cruzas a gatas. Agarras a las criaturas de a dos y las pasas."],
                     [null, "Cuando vuelves por la última, la tabla se parte. Saltas. Llegas al otro lado con las piernas colgando y te subes con los codos."],
                     [null, "La última criatura queda del otro lado. Te mira. Se da vuelta y se mete más adentro del glaciar, donde todavía hace frío."]], end: { xp: 16, hurt: 0.1, flag: "e4_criaturasGrieta" } },
      criatura: { say: [[null, "Tu criatura salta la grieta donde es más angosta. Del otro lado junta a las cinco y las lleva por el borde, hasta un puente de hielo que tú no habías visto."],
                        [null, "Cruzan en fila, detrás de ella. Las cinco. Tu criatura vuelve última, con el pelo lleno de escarcha, orgullosa."]], end: { xp: 18, heal: 0.05, flag: "e4_criaturaGuia" } },
      rodear: { say: [[null, "Subes por el borde del glaciar durante horas. Cuando llegas al otro lado, la grieta ya es un cañón. Las criaturas no están."],
                      [null, "Las encuentras más arriba, juntas, apretadas en una cueva de hielo que todavía no gotea. Te miran. No bajan."],
                      [null, "Les dejas comida en la entrada. Cuando bajas, el glaciar suena otra vez, lejos."]], end: { xp: 10 } },
    } },

    "e4-guardado": { kind: "encuentro", need: { era: 4, layer: 3 }, who: { tempano: "Témpano, guardiana del hielo", fogarin: "Fogarín, Maestro del Gremio" }, start: "a", nodes: {
      a: { say: [[null, "El hielo más viejo del Fondo se derritió hasta el suelo. Témpano te lleva a ver lo que había debajo. Es una sala enorme, de piedra, con el techo goteando."],
                 [null, "En el suelo, ordenadas en filas, hay campanas. Cientos. Chicas, grandes, de piedra, de hueso, de metal oscuro. Todas tienen la lengua atada con cuerdas que se deshacen al tocarlas."],
                 ["tempano", "No sabía. Nadie sabía. El hielo las tapaba. Alguien, antes de todas las eras que conocemos, hizo campanas para dormir a la Raíz. Y después las ató. Y después las enterró en el frío."]],
           opts: [{ t: "«¿Por qué las ataron?»", go: "porque", once: true },
                  { t: "Llevar una campana atada al Corazón", go: "llevar" },
                  { t: "Volver a taparlas con hielo y nieve", go: "tapar" },
                  { t: "Contarle a Fogarín", go: "fogarin" }] },
      porque: { say: [["tempano", "No sé. Pero mire: hay una tablilla de piedra en la entrada. Las letras son viejas. Rada las podría leer con los dedos. Yo solo entiendo una palabra, que se repite."],
                      ["tempano", "La palabra es «no». Escrita muchas veces. En cada campana. Como si cada uno que la hizo hubiera vuelto a escribir lo mismo."]], back: "a" },
      llevar: { say: [[null, "Cargas una campana chica, de hueso, con la lengua atada. Pesa poco. Témpano camina contigo hasta el Corazón. No habla en todo el camino."],
                      [null, "La dejas al pie de la tercera estatua, junto a la campana de prueba del Gremio. Las dos, una al lado de la otra. Una atada. Una no."],
                      ["tempano", "Que la vean. Que alguien antes que nosotros tuvo la misma idea. Y que la enterró. El Fondo va a ir al Corazón con esto."]], end: { xp: 22, flag: ["e4_campanasViejas", "u4_escarcha"] } },
      tapar: { say: [[null, "Paleas nieve sobre las campanas con Témpano y diez del Fondo. Tardan tres días. Encima ponen bloques del hielo que todavía no se derritió."],
                     ["tempano", "No va a aguantar. El calor sigue viniendo de abajo. Pero por ahora están tapadas. Que no las encuentre el Gremio. Les daría ideas."]], end: { xp: 14, flag: "e4_campanasTapadas" } },
      fogarin: { say: [[null, "Fogarín baja al Fondo con pieles encima. Camina entre las filas de campanas atadas. Toca una. Toca otra. Se sienta en el suelo mojado."],
                       ["fogarin", "Ya se hizo. Muchas veces. Y todos las ataron. Y yo pensé que era el primero."],
                       [null, "No dice nada más. Vuelve al Cráter esa noche. Al día siguiente, la Campana grande sigue en el molde. Pero los hornos hondos trabajan la mitad."]], end: { xp: 20, flag: "e4_fogarinCampanas" } },
    } },

    "e4-fondovoto": { kind: "dialogo", need: { era: 4, layer: 3 }, who: { tempano: "Témpano, guardiana del hielo", carambano: "Nevado, del Turno" }, start: "a", nodes: {
      a: { say: [[null, "En la sala alta, donde el Fondo se mudó, la gente se junta alrededor de un brasero. Por primera vez en la historia del Fondo hay fuego adentro. Hace falta: los de abajo vienen empapados."],
                 ["tempano", "Nos llaman al Corazón. Por la Campana. Si vamos, vamos a pedir que se apaguen los hornos. Todos. El Fondo no sobrevive si no."],
                 ["carambano", "Y si se apagan todos, el Cráter se muere de hambre. Ellos también son gente. Yo duermo al lado de los que vienen con las manos grises."]],
           opts: [{ t: "«Vayan a pedir lo que necesitan. Que el Corazón decida.»", go: "pedir" },
                  { t: "«Vayan a escuchar primero.»", go: "escuchar" },
                  { t: "«No vayan. Suban más alto y esperen.»", go: "esperar" }] },
      pedir: { say: [["tempano", "Pedir. Sí. Es lo que el Fondo nunca hizo. Siempre esperamos a que el frío nos defendiera."],
                     [null, "Levanta un balde de agua de deshielo. Lo pone en el medio del círculo."],
                     ["tempano", "Llevamos esto. Agua que era hielo eterno. Que lo vean, que lo toquen. Y que digan después si el Fondo pide mucho."]], end: { xp: 18, flag: ["e4_fondoPide", "u4_escarcha"] } },
      escuchar: { say: [["carambano", "Escuchar. Eso sí sabemos. Mil años escuchando a la Raíz dormida."],
                        ["tempano", "Bueno. Vamos a escuchar. Pero si alguien dice que el Fondo puede esperar, yo hablo. Ya esperamos bastante."]], end: { xp: 16, flag: ["e4_fondoEscucha", "u4_escarcha"] } },
      esperar: { say: [[null, "El Fondo no va. Suben más alto, a las cuevas de la cumbre, y esperan."],
                       ["tempano", "Que nos llegue la noticia. Buena o mala. El frío siempre esperó. A lo mejor es lo único que sabemos hacer."]], end: { xp: 8, flag: "e4_fondoNoVa" } },
    } },
  });

  /* ---------- Corazón del Claro: el Tocón, la estatua, los que llegan, el nombre, la víspera y los cantores ---------- */
  add("heart", {
    "e4-tocon": { kind: "encuentro", need: { era: 4, layer: 1 }, who: { retama: "Retama, guarda del Tocón" }, start: "a", nodes: {
      a: { say: [[null, "En el Corazón, el Tocón está tibio. Las raíces que asoman del suelo alrededor tienen vetas rojas, finas, como venas debajo de la piel. Las flores del Tocón se abren de noche y se cierran de día, al revés."],
                 ["retama", "Soy Retama. Cuido el Tocón. Antes lo cuidaba Brezo. Él decía que el Tocón era frío como una piedra de río. Ahora quema si lo tocas mucho rato."],
                 ["retama", "Las criaturas no se acercan como antes. Las que vienen, vienen a morir. Se acuestan en las raíces tibias y no se levantan."]],
           opts: [{ t: "«¿Desde cuándo está tibio?»", go: "cuando", once: true },
                  { t: "Poner la mano en el Tocón", go: "mano" },
                  { t: "Ayudarla a enterrar a las criaturas", go: "enterrar" },
                  { t: "Cantar la nana al Tocón", go: "nana" }] },
      cuando: { say: [["retama", "Desde que empezaron los hornos hondos. Primero un poco. Después más. Ahora, en las noches de la Corte, cuando no duerme, se ve un brillo rojo en las grietas de la corteza."],
                      ["retama", "Brezo me enseñó a escuchar el Tocón. Ahora el Tocón suena distinto. Como alguien con fiebre."]], back: "a" },
      mano: { say: [[null, "Pones la mano en la corteza del Tocón. Está caliente, como la frente de un chico enfermo. Debajo, algo late rápido."],
                    [null, "Te quedas así un rato. El latido no se calma. Pero tu mano, después, queda tibia por horas."],
                    ["retama", "Lo sintió. Le cambió la cara. Brezo ponía la misma cara."]], end: { xp: 12, flag: "e4_toconFiebre" } },
      enterrar: { say: [[null, "Cavas con Retama tres tumbas chicas al pie del Tocón. Las criaturas son livianas. Tienen las patas grises."],
                        [null, "Tu criatura mira desde lejos. Cuando terminan, se acerca y se acuesta sobre la tierra removida."],
                        ["retama", "Aquí siempre se enterraba a las criaturas del Claro. Antes eran viejas. Estas son jóvenes."]], end: { xp: 14, flag: "e4_criaturasTocon" } },
      nana: { say: [[null, "Cantas la nana con la mano en el Tocón. El latido se hace un poco más lento. Las flores, que estaban abiertas al mediodía, se cierran despacio."],
                    ["retama", "Se cerraron. Como antes. Como tienen que cerrarse."],
                    [null, "Cuando dejas de cantar, las flores tardan en volver a abrirse. Pero se abren."]], end: { xp: 16, heal: 0.1, flag: "e4_toconNana" } },
    } },

    "e4-estatua": { kind: "encuentro", need: { era: 4, layer: 2 }, who: { yunque: "Yunque, forjador" }, start: "a", nodes: {
      a: { say: [[null, "Al pie de la tercera estatua del Corazón, la del forjador sin cara con escoria pegada en la base, Yunque está arrodillado. Tiene el brazo gris hasta el hombro. Lo apoya en la piedra como si fueran de la misma familia."],
                 ["yunque", "Vengo todas las semanas. Antes rezaba. Ahora le hablo. Es como hablar con un compañero de turno que ya se jubiló."],
                 ["yunque", "Mire la base. La escoria de la estatua y la de mis manos son la misma. El que hizo esta estatua sabía lo que iba a pasar. La hizo de advertencia. Y nosotros le rezamos."]],
           opts: [{ t: "«Diga su nombre en voz alta.»", go: "nombre", cNeed: "e4_nombreYunque" },
                  { t: "«¿Qué le dice cuando le habla?»", go: "dice", once: true },
                  { t: "«Deje la Campana. Le queda un brazo.»", go: "dejar" },
                  { t: "«Termine la Campana. Es lo que quiere.»", go: "terminar" }] },
      nombre: { say: [[null, "Yunque saca el papel doblado del amuleto. Lo desdobla con la mano buena. Lee el nombre en voz alta, una vez, fuerte."],
                      [null, "Los que pasan por el Corazón se detienen. Alguien lo repite. Otro. El nombre del primer forjador corre por la plaza, de boca en boca, después de mil años."],
                      ["yunque", "Ya está. Tiene nombre otra vez. Ya no es un santo. Es uno de los nuestros. Ahora puedo dejar de rezarle y empezar a acordarme de él."]], end: { xp: 22, flag: "e4_yunqueNombra" } },
      dice: { say: [["yunque", "Le cuento cómo va la Campana. Cuántos se fueron al Vado con las manos grises. Le pregunto si a él también le pesaba."],
                    ["yunque", "No contesta. Pero la escoria de la base está tibia siempre. Algo hay ahí adentro, todavía. Como en los cuarenta de las Cuevas."]], back: "a" },
      dejar: { say: [["yunque", "¿Dejar? ¿Con la Campana casi lista?"],
                     [null, "Mira su brazo. Lo mueve un poco. Cruje."],
                     ["yunque", "Un brazo. Bueno. Con un brazo se puede cargar a un nieto. Con un brazo de piedra, no. Me voy al Vado. Que la termine otro. O nadie."]], end: { xp: 16, flag: "e4_yunqueDeja" } },
      terminar: { say: [["yunque", "Sí. La termino. Es lo que vine a hacer al mundo, parece."],
                        [null, "Se levanta con trabajo. Le das la mano buena para ayudarlo. La otra pesa como un yunque de verdad."],
                        ["yunque", "Cuando suene, voy a estar ahí. Aunque sea de piedra entero. Que alguien me ponga al lado de él, en la base."]], end: { xp: 14, flag: "e4_yunqueTermina" } },
    } },

    "e4-llegan": { kind: "encuentro", need: { era: 4, layer: 2 }, who: { retama: "Retama, guarda del Tocón", cobre: "Cobre, de las Casas" }, start: "a", nodes: {
      a: { say: [[null, "Al Corazón empiezan a llegar los pueblos. No todos juntos: de a poco, en grupos, con lo que tienen. Leñadores con resina, mineros con piedras grabadas, gente de las Casas con papeles."],
                 [null, "Acampan alrededor del Tocón, cada pueblo en su lugar, sin mezclarse. Hay fuegos separados. Hay miradas."],
                 ["cobre", "Las Casas trajeron sillas. Nadie más trajo sillas. Ya nos están mirando por las sillas."],
                 ["retama", "Cada pueblo armó su fuego lejos de los otros. Si se juntan para hablar de la Raíz, que se junten primero alrededor del mismo fuego."]],
           opts: [{ t: "Hacer un solo fuego en el medio", go: "fuego" },
                  { t: "Repartir las sillas de las Casas", go: "sillas" },
                  { t: "Dejar que cada pueblo se acomode a su modo", go: "dejar" }] },
      fuego: { say: [[null, "Juntas leña de cada pueblo: un tronco del Bosque, carbón de la Corte, una tabla de los baños, un pedazo de lona de los Altos. Haces un fuego grande en el medio."],
                     [null, "Al principio nadie se acerca. Después un chico del Barrio. Después Pizca, la de los túneles. Después los viejos, para calentarse las manos."],
                     ["retama", "Así. El fuego no es de nadie y todos lo necesitan. Igual que la Raíz."]], end: { xp: 18, flag: "e4_fuegoComun" } },
      sillas: { say: [["cobre", "¿Repartir las sillas? Son de mi Casa."],
                      [null, "Te mira. Mira a los obreros sentados en el suelo, con las manos grises en las rodillas."],
                      ["cobre", "Bueno. Mi madre ya vendió todo lo demás. Que se vayan también las sillas."],
                      [null, "Cobre lleva las sillas él mismo, una por una, a los más viejos de cada pueblo. Cuando termina, se sienta en el suelo."]], end: { xp: 16, flag: "e4_sillasRepartidas" } },
      dejar: { say: [[null, "Cada pueblo se queda en su fuego. Esa noche hay nueve fuegos en el Corazón y nueve canciones distintas, ninguna la nana."],
                     ["retama", "Nueve fuegos. Bueno. Por lo menos vinieron. Ya es más de lo que pasó la última vez."]], end: { xp: 8 } },
    } },

    "e4-pruebas": { kind: "dialogo", need: { era: 4, layer: 3 }, who: { fogarin: "Fogarín, Maestro del Gremio", escoria: "Escoria, obrera" }, start: "a", nodes: {
      a: { say: [[null, "En el Corazón, Fogarín y Escoria están sentados en el mismo banco, sin mirarse. La campana de prueba cuelga del andamio, cerca. Hace un mes que no la tocan."],
                 ["escoria", "Le estaba diciendo al Maestro que la campana de prueba hace callar a la Raíz una hora. Y que en esa hora, en el Cráter, los hornos hondos se enfrían solos."],
                 ["fogarin", "Y yo le decía que entonces funciona. Que si una campana chica da una hora, la grande da para siempre. Y los hornos se enfrían para siempre."],
                 ["escoria", "Y yo le pregunté: ¿y qué más se enfría para siempre? No me contestó."]],
           opts: [{ t: "«Bajé al Fondo. Hay cientos de campanas atadas.»", go: "atadas", cNeed: "e4_campanasViejas" },
                  { t: "«En las Cuevas hay cuarenta obreros de piedra.»", go: "cuarenta", cNeed: "e4_cuarentaVistos" },
                  { t: "«Toquen la de prueba otra vez y escuchen todos.»", go: "tocar" },
                  { t: "«Ninguno de los dos sabe. Hay que preguntarle a los nueve.»", go: "nueve" }] },
      atadas: { say: [["fogarin", "Lo sé. Las vi. Alguien las hizo antes. Alguien las ató."],
                      ["escoria", "¿Y no le da miedo?"],
                      ["fogarin", "Me da miedo todo. Me da miedo que las hayan atado porque funcionaban demasiado bien. Me da miedo que las hayan atado porque no funcionaban. No sé cuál me da más."]], back: "a" },
      cuarenta: { say: [["escoria", "Cuarenta. Como nosotros, pero antes. Siguieron trabajando hasta ser piedra."],
                        ["fogarin", "Y la Campana termina con eso. Nadie más baja. Nadie más se vuelve piedra. Por eso la hago, Escoria. Por los cuarenta."],
                        ["escoria", "Los cuarenta también pensaban que estaban haciendo algo para que nadie más bajara. Seguro."]], back: "a" },
      tocar: { say: [[null, "Fogarín se levanta. Toca la campana de prueba una vez. La nota baja por el suelo."],
                     [null, "Todo el Corazón se queda en silencio. No es un silencio de gente callada: es un silencio de debajo, como si alguien hubiera apagado algo que siempre sonaba sin que nadie lo oyera."],
                     [null, "Una hora después, cuando vuelve el ruido de fondo, tres criaturas que estaban dormidas junto al Tocón no se despiertan."],
                     ["escoria", "¿Eso es dormir?"],
                     [null, "Fogarín no contesta. Se sienta otra vez en el banco, más cerca de ella."]], end: { xp: 18, flag: "e4_pruebaVista" } },
      nueve: { say: [["fogarin", "¿Los nueve? ¿Que el Herrero, las Casas, la Corte y los pescadores decidan sobre mi Campana?"],
                     ["escoria", "Nuestra Campana. Yo la martillé también. Con estas manos."],
                     [null, "Fogarín la mira. Mira las manos de ella, grises hasta la muñeca. Después las suyas."],
                     ["fogarin", "Bueno. Los nueve. Si se juntan. Si no se juntan, decido yo. Que nadie diga que no esperé."]], end: { xp: 18, flag: "e4_fogarinEspera" } },
    } },

    "e4-vispera": { kind: "dialogo", need: { era: 4, layer: 4 }, who: { fogarin: "Fogarín, Maestro del Gremio" }, start: "a", nodes: {
      a: { say: [[null, "La noche antes de que bajen la Campana grande al Corazón, Fogarín está solo en el taller del Gremio, con una lámpara. La Campana está tapada con una lona, enorme, roja por debajo."],
                 ["fogarin", "Pasa. No puedo dormir. Tengo ochenta y cuatro años y nunca pude dormir la noche antes de una fundición. Esta es la última."],
                 ["fogarin", "Me crié entre las Mareas. Ola me sacó del agua cuando me caí del muelle. Le debía una vida. Y lo que hice con ella fue hervirles el lago. ¿Cómo se paga eso?"]],
           opts: [{ t: "«Su abuelo del abuelo está en la lista de Ébano.»", go: "lista", cNeed: "e4_fogarinLista" },
                  { t: "«Usted grabó su mano en la pared de los vivos.»", go: "pared", cNeed: "e4_fogarinPared" },
                  { t: "«No se paga. Se deja de cobrar.»", go: "cobrar" },
                  { t: "«Mañana no la baje. Una noche más.»", go: "noche" },
                  { t: "Sentarte con él hasta que amanezca", go: "sentarse" }] },
      lista: { say: [["fogarin", "Sí. Con la mano gris. Mi familia viene forjando ese metal desde antes de que tuviera nombre. Y antes de que alguien lo borrara."],
                     ["fogarin", "Pensé que la Campana era la forma de terminar con eso. A lo mejor es la forma de terminarlo como siempre: con otro que no se acuerda."]], back: "a" },
      pared: { say: [["fogarin", "La grabé. Cuando me muera, la van a encontrar ahí. Entre las de los obreros. No arriba, en la sala de los maestros."],
                     ["fogarin", "Es lo único que hice en mi vida sin que me lo pidiera nadie y sin que nadie me pagara. Me hizo bien. Raro."]], back: "a" },
      cobrar: { say: [["fogarin", "Dejar de cobrar. Ola decía eso. Cobrar poco y sacar menos."],
                      [null, "Se queda mirando la lona. Después saca de un cajón un papel y lo firma: los hornos bajo el Lago, todos, se cierran al día siguiente. No dos. Todos."],
                      ["fogarin", "No alcanza. Nunca alcanza. Pero es lo que sé hacer: firmar papeles. Ella me enseñó a nadar. Yo sé firmar."]], end: { xp: 20, flag: "e4_lagoLibre" } },
      noche: { say: [["fogarin", "Una noche más. ¿Para qué?"],
                     [null, "Le dices: para que lleguen todos los pueblos al Corazón. Para que nadie la baje sin que los nueve la vean."],
                     ["fogarin", "Una noche más. Bueno. Se la doy. A ellos y a mí. Total, no iba a dormir igual."]], end: { xp: 14, flag: "e4_nocheMas" } },
      sentarse: { say: [[null, "Te sientas en un banco al lado de él. No hablan mucho. Él cuenta historias de cuando era aprendiz, del fuelle que tosía, de un Cuidador que lo ayudó a tirar de una cadena hace muchos años."],
                        ["fogarin", "Eras tú. Siempre fuiste tú. Ya no me acuerdo de tu cara de entonces. Pero me acuerdo de que nadie más me ayudó a tirar."],
                        [null, "Amanece. Fogarín se levanta, se pone el delantal y destapa la Campana."]], end: { xp: 16, heal: 0.1, flag: "e4_vigiliaFogarin" } },
    } },

    "e4-cantores": { kind: "encuentro", need: { era: 4, layer: 4 }, who: { romanza: "Romanza, mensajera", pizarra: "Pizarra, maestra" }, start: "a", nodes: {
      a: { say: [[null, "En el Corazón, la última noche antes de decidir, alguien se pregunta en voz alta quién sabe la nana entera. No la de los cuentos: la de verdad, con todos los versos."],
                 [null, "Se levantan pocos. Romanza, la mensajera de los Altos, con su tambor. Pizarra, la maestra del Prado, con tiza en el pelo. Un viejo del Fondo. Una chica de la Hondura. Nadie más."],
                 ["romanza", "Cinco. Para cantarla bien hacen falta nueve pueblos. Somos cinco personas."],
                 ["pizarra", "Los chicos de mi escuela la saben. Pero desafinada. Y la mitad de los versos se los inventaron."]],
           opts: [{ t: "«Que la canten los cinco. Ahora.»", go: "cantar" },
                  { t: "«Enséñenla a todos esta noche.»", go: "ensenar" },
                  { t: "«Que la canten los chicos, con sus versos inventados.»", go: "chicos" }] },
      cantar: { say: [[null, "Los cinco se paran juntos al pie del Tocón. Cantan. Romanza marca el ritmo con el tambor. La nana suena flaca, con huecos, pero entera."],
                      [null, "El Tocón deja de latir rápido. Las raíces rojas se oscurecen un poco. Las criaturas que dormían junto a las raíces abren los ojos."],
                      ["romanza", "Funciona. Con cinco funciona un poco. Con nueve, ¿qué pasaría?"]], end: { xp: 18, flag: "e4_cincoCantan" } },
      ensenar: { say: [[null, "Toda la noche, Romanza y Pizarra van de fuego en fuego enseñando la nana. Verso por verso. Algunos se duermen. Otros la aprenden."],
                       [null, "Al amanecer, doscientas personas la saben. Mal. Pero la saben."],
                       ["pizarra", "Doscientas. No está en el programa. Pero es la mejor clase que di en mi vida."]], end: { xp: 20, flag: "e4_nanaEnsenada" } },
      chicos: { say: [[null, "Pizarra trae a sus alumnos. Los chicos se paran en ronda alrededor del Tocón y cantan la nana como la aprendieron: desafinada, rápida, con un verso sobre una taza y otro sobre un perro."],
                      [null, "Los grandes se ríen. Después se callan. El Tocón se calma igual."],
                      ["romanza", "Con versos inventados. No sabía que se podía. A lo mejor la nana nunca fue la letra. A lo mejor fue que alguien la cante."]], end: { xp: 18, heal: 0.05, flag: "e4_nanaChicos" } },
    } },
  });

})(window.EVEVENTS);
